INSERT INTO bible_chapters (book_id, chapter_number, total_verses)
INSERT INTO bible_verses (chapter_id, verse_number, text) VALUES
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 1), 1, 'No ano trigésimo, no quarto mês, a cinco do mês, aconteceu que, estando no meio dos cativos, ao rio Cobar, se abriram os céus, e tive visões divinas, (ver nota)'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 1), 2, 'A cinco do mês, no quinto ano da deportação do rei Joaquim,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 1), 3, 'foi dirigida a palavra do Senhor a Ezequiel, filho de Buzi, sacerdote, na terra dos Caldeus, junto ao rio Cobar, e lá a mão do Senhor fez-se sentir sobre ele.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 1), 4, 'Tive pois uma visão; Da banda do norte vinha um vento tempestuoso, e uma grande nuvem, com um feixe de fogo resplendoroso, saindo do centro, do meio do fogo, uma espécie de metal brilhante.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 1), 5, 'No meio, aparecia uma semelhança de quatro seres vivos que aparentavam forma humana.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 1), 6, 'Cada um tinha quatro rostos, e cada um quatro asas.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 1), 7, 'As suas pernas eram direitas, e a planta dos (seus) pés era como a planta do pé dum novilho, e cintilavam como bronze incandescente.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 1), 8, 'Apareciam mãos de homem debaixo das suas asas aos quatro lados. As faces de todos os quatro estavam voltadas para as quatro direcções.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 1), 9, 'As asas dum estavam juntas às do outro; não se voltavam quando iam caminhando, mas cada um seguia segundo a direcção do seu rosto.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 1), 10, 'O seu semblante era assim: rosto de homem pela frente, e face de leão à direita, em todos os quatro, face de touro à esquerda, em todos os quatro, e face de águia nos mesmos quatro.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 1), 11, 'Tais eram seus rostos. As suas asas estendiam-se para o alto; duas asas de cada um juntavam-se, e duas cobriam os seus corpos.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 1), 12, 'Cada um deles caminhava segundo a direcção do seu rosto; para onde os Impelia o espírito, para ali caminhavam, nem se voltavam quando iam andando. (ver nota)'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 1), 13, 'O aspecto destes seres vivos assemelhava-os a carvões ardentes, como archotes. Via-se discorrer pelo meio dos seres vivos, um resplendor de fogo, e sair relâmpagos do fogo.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 1), 14, 'E esses seres vivos iam e voltavam, à semelhança de raios.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 1), 15, 'Ora, enquanto eu estava olhando para estes viventes, apareceu junto de cada um dos quatro uma roda sobre a terra.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 1), 16, 'O aspecto das rodas e a sua estrutura pareciam ter o brilho de pedra de Tarsis; e todas quatro eram semelhantes; e o seu aspecto e estrutura eram como de uma roda que está no meio doutra roda.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 1), 17, 'Avançavam nas quatro direcções e não se voltavam quando iam rodando.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 1), 18, 'Tinham também estas rodas uma altura horrível; todo o corpo das quatro rodas estava cheio de olhos ao redor.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 1), 19, 'Quando os viventes andavam, andavam também as rodas junto deles; e, quando os viventes se elevavam da terra, também as rodas se elevavam juntamente.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 1), 20, 'Para onde o espírito as impelia, as rodas iam, seguindo-o, e igualmente se elevavam, porque o espírito da cada vivente estava nas rodas.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 1), 21, 'Andando os viventes, andavam as rodas; parando eles, paravam elas; e quando eles se elevavam da terra, também as rodas, seguindo-os, juntamente se elevavam, por que o espírito de cada vivente estava nas rodas.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 1), 22, 'Por cima das cabeças dos seres vivos via-se uma o semelhança de firmamento, como de cristal estupendo, estendido por cima de suas cabeças.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 1), 23, 'E debaixo deste firmamento(viam-se) as suas asas estendidas tocando a asa dum na do outro; cada um cobria o seu corpo com duas asas.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 1), 24, 'Eu ouvia, quando eles andavam, o ruído das suas asas, como o ruído de muitas águas, como a voz do Omnipotente. como o ruído dum exército; quando paravam, baixavam as suas asas.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 1), 25, 'Porque, quando saía uma voz de sobre o firmamento que ficava por cima das suas cabeças, paravam e baixavam as suas asas.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 1), 26, 'Sobre este firmamento, que ficava por cima das suas cabeças, havia uma semelhança de pedra de safira, como um trono, e sobre esta semelhança de trono havia, no alto, um ser com aparência humana.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 1), 27, 'Vi uma espécie de metal brilhante, como fogo, no interior e em volta dele, da sua cintura para cima; e da cintura para baixo vi como um fogo que resplandecia ao redor;'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 1), 28, 'qual arco íris que aparece numa nuvem em dia de chuva, tal era o aspecto do resplendor em roda.');
INSERT INTO bible_chapters (book_id, chapter_number, total_verses)
INSERT INTO bible_verses (chapter_id, verse_number, text) VALUES
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 2), 1, 'Esta visão era a semelhança da glória do Senhor. Ao vê-la, caí com o meu rosto em terra e ouvi uma voz de alguém que falava. Disse-me; Filho de homem, põe-te de pé, e eu falarei contigo.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 2), 2, 'Enquanto me falava, entrou em mim o espírito, e me firmou sobre os meus pés; e ouvi o que me falava.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 2), 3, 'Dizia-me: Filho de homem, eu te envio aos filhos de Israel, aos povos rebeldes que se revoltaram contra mim; eles e seus pais foram-me infiéis até ao dia de hoje. Aqueles a quem te envio são filhos de semblante duro de coração empedernido. Dir-lhes-ás: Assim fala o Senhor Iavé.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 2), 5, 'Quer te escutem ou não é gente rebelde (ao menos) saberão que esteve no meio deles um profeta.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 2), 6, 'Tu filho de homem, não tenhas medo deles, não temas as suas palavras, embora te encontres em meio de cardos e espinhos, e habites com escorpiões. Não temas as suas palavras, não te assustes com os seus semblantes, porque é uma casa rebelde.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 2), 7, 'Tu, pois, lhes intimarás as minhas palavras, quer escutem ou não, porque são rebeldes.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 2), 8, 'Tu, filho de homem, ouve o que te digo: não sejas rebelde como esta casa; abre a tua boca e come tudo o que te dou.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 2), 9, 'Olhei e vi que uma mão estava estendida para mim, na qual se achava um livro enrolado. Abriu-o diante de mim; estava escrito por dentro e por fora, e viam-se escritas nele lamentações, canções lúgubres e ais.');
INSERT INTO bible_chapters (book_id, chapter_number, total_verses)
INSERT INTO bible_verses (chapter_id, verse_number, text) VALUES
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 3), 1, 'Disse-me: Filho de homem, come tudo o que achares; come esse livro, e depois, vai falar aos filhos de Israel. (ver nota)'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 3), 2, 'Então abri a minha boca, e ele deu-me a comer o livro,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 3), 3, 'dizendo-me: Filho de homem, alimenta o teu ventre, enche as tuas entranhas deste livro que te dou. Comi-o, e ele na minha boca era doce como mel.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 3), 4, 'Então disse-me: Filho de homem, vai à casa de Israel anunciar as minhas palavras,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 3), 5, 'Não és enviado a nenhum povo de linguagem obscura, nem de língua bárbara, mas à casa de Israel;'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 3), 6, 'não a povos numeroso linguagem obscura, de língua bárbara, cujas palavras não poderias entender; se a esses fosses enviado, eles te ouviriam.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 3), 7, 'Mas a casa de Israel não te quer ouvir a ti, porque me não quer ouvir a mim, pois a casa de Israel tem uma fronte obstinada e um coração endurecido.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 3), 8, 'Porém vou tornar o teu rosto tão duro como o deles, a tua fronte tão dura como a sua.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 3), 9, 'Vou tornar o teu rosto (tão duro) como o diamante, mais duro que a pederneira. Não os temas não tenhas medo diante deles, porque é uma casa rebelde.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 3), 10, 'Depois acrescentou: Filho de homem, recebe no teu coração todas as palavras que eu te disser ouve-as com os teus ouvidos,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 3), 11, 'e vai até junto dos deportados, filhos do teu povo, para lhes falar. Dir-lhes-ás: Assim fala o Senhor Iavé — quer eles escutem, quer não.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 3), 12, 'Então o espírito me tomou, e ouvi atrás de mim um grande ruído tumultuoso (que dizia): Abençoada a glória do Senhor, no lugar da sua morada.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 3), 13, 'Ouvi também o ruído das asas dos seres vivos, que batiam uma contra a outra, e o ruído das rodas junto deles, grande ruído tumultuoso.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 3), 14, 'E o espírito levantou-me e levou-me consigo, e eu me fui, com o espírito cheio de amargura e indignação; e a mão do Senhor segurava-me fortemente.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 3), 15, 'Fui ter com os deportados, a Tel-Abib, onde estavam instalados, junto do rio Cobar, e permaneci estupefacto, durante sete dias, no meio deles.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 3), 16, 'Passados os sete dias, foi-me dirigida a palavra do Senhor, a qual dizia;'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 3), 17, 'Filho de homem, eu dei-te por sentinela à casa de Israel. Quando ouvires da minha boca uma palavra, anunciá-la-ás a eles da minha parte.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 3), 18, 'Se eu disser ao ímpio; Vais morrer e tu lho não anunciares, não lhe falares, para que ele se retire do seu caminho ímpio e viva — este ímpio morrerá na sua iniquidade, mas eu requererei da tua mão o seu sangue (ou perdição).'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 3), 19, 'Se, porém, avisares o ímpio, e ele se não converter da sua impiedade e do seu mau caminho, morrerá ele por certo na sua iniquidade, mas tu salvar-te-ás.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 3), 20, 'Do mesmo modo, se o justo deixar a sua justiça e cometer a iniquidade, e se eu puser diante dele um tropeço, ele morrerá; porque tu lho não advertiste, morrerá no seu pecado, apagar-se-á a lembrança de todas as acções de justiça que praticou, mas eu requererei da tua mão o seu sangue.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 3), 21, 'Se, porém, avisares o justo, para que não peque, e ele não pecar, viverá com certeza, porque tu o advertiste, e tu serás salvo.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 3), 22, 'Ali se fez sentir sobre mim a mão do Senhor, que me disse: Levanta-te, sai ao descampado, e lá falarei contigo.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 3), 23, 'Levantei-me, saí para o descampado, e eis que estava lá a glória do Senhor, como a glória que eu tinha visto junto do rio Cobar. Prostrei-me com o rosto por terra.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 3), 24, 'Então o espirito entrou em mim e pôs-me de pé; falou-me e disse-me: Vai-te fechar dentro da tua casa.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 3), 25, 'E tu, ó filho de homem, sabe que eles lançarão cadeias sobre ti, e te ligarão com elas, de sorte que não sairás do meio deles.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 3), 26, 'E farei que a tua língua se pegue ao teu paladar, de sorte que estejas mudo, incapaz de os repreender porque são uma casa rebelde. (ver nota)'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 3), 27, 'Mas, depois que eu te tiver falado, abrirei a tua boca e tu lhes dirás: Assim fala o Senhor Deus: Quem quiser ouvir, ouça; quem não quiser ouvir, não ouça, — porque são uma casa rebelde.');
INSERT INTO bible_chapters (book_id, chapter_number, total_verses)
INSERT INTO bible_verses (chapter_id, verse_number, text) VALUES
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 4), 1, 'Tu, filho de homem, pega num tijolo, coloca-o diante de ti e desenha nele uma cidade: Jerusalém,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 4), 2, 'Delinearás um assédio contra ela, levantarás fortificações, farás trincheiras, assentarás um exército contra ela e colocarás aríetes ao redor.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 4), 3, 'Toma também uma frigideira de ferro e põe-na como um muro de ferro entre ti e a cidade; depois olha para ela; ela será sitiada, e tu a sitiarás. Isto é um sinal para a casa de Israel.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 4), 4, 'Em seguida deita-te sobre o teu lado esquerdo e põe sobre ele as iniquidades da casa de Israel; durante os dias em que dormires sobre ele, tomarás sobre ti as suas iniquidades.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 4), 5, 'Conto-te um dia por cada ano da iniquidade deles: trarás sobre ti, durante trezentos e noventa dias, a iniquidade da casa de Israel.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 4), 6, 'Depois que tiveres cumprido isto, deitar-te-ás segunda vez, (mas) sobre o teu lado direito, e tomarás sobre ti a iniquidade da casa de Judá durante quarenta dias; conto-te, por cada dia, um ano.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 4), 7, 'Voltarás o teu rosto para Jerusalém sitiada, estenderás o teu braço nu, e assim profetizarás contra ela.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 4), 8, 'Eis que te rodeei de cadeias, e não te poderás voltar de um lado para outro, enquanto não cumprires os dias da tua reclusão.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 4), 9, 'Toma também trigo, cevada, favas, lentilhas milho e espelta, põe tudo isto dentro dum vaso e faze para ti pães, conforme o número dos dias que hás-de dormir sobre o teu lado; comerás deles durante trezentos e noventa dias.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 4), 10, 'A comida de que te hás-de sustentar, será do peso de vinte siclos por dia; no tempo fixado (uma vez por dia) a comerás.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 4), 11, 'Hás-de beber também a água por medida, (isto é) a sexta parte dum hin; tu a beberás no tempo marcado.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 4), 12, 'O pão, tu o comerás, como uma torta de cevada, cozida sobre excrementos humanos, à vista deles. (ver nota)'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 4), 13, 'E o Senhor disse: Assim comerão os filhos de Israel o seu alimento imundo entre as gentes, para onde eu os lançarei.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 4), 14, 'Então eu disse: Ai, Senhor Deus. a minha alma não está manchada! Desde a minha infância até agora, jamais comi coisa morta, ou despedaçada pelas feras, nem na minha boca entrou carne alguma imunda.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 4), 15, 'Ele disse-me: Eis aí te dou esterco de bois em lugar de excremento humano; farás cozer sobre ele o teu pão.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 4), 16, 'Depois disse-me; Filho de homem, vou quebrar o báculo do pão em Jerusalém; comerão o pão por peso e com sobressalto, e beberão a água por medida e com angústia,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 4), 17, 'de modo que, faltando-lhes o pão e a água, serão todos juntamente consumidos e perecerão por causa das suas Iniquidades.');
INSERT INTO bible_chapters (book_id, chapter_number, total_verses)
INSERT INTO bible_verses (chapter_id, verse_number, text) VALUES
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 5), 1, 'Tu, filho de homem, toma uma espada (lâmina) afiada, toma-a como navalha de barbeiro e passa-a por cima da tua cabeça e da tua barba; em seguida toma uma balança e divide em (três) partes (o que cortaste).'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 5), 2, 'Uma terça parte lançá-la-ás ao fogo no meio da cidade, quando os dias do cerco se tiverem cumprido; tomarás a outra terça parte, que ferirás com a navalha ao redor da cidade; deitarás ao vento a outra terça parte, e em seguida eu irei atrás deles com a espada. (ver nota)'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 5), 3, 'Porém reservarás uma pequena quantidade, que atarás nas orlas da tua capa.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 5), 4, 'E ainda daqui tirarás uma parte, que lançarás no meio do fogo e queimarás. É daí que sairá um fogo para toda a casa de Israel.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 5), 5, 'Isto diz o Senhor Deus: Esta é aquela Jerusalém que coloquei no meio das nações, cercada das suas terras,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 5), 6, 'Ela, com perversidade, revoltou-se contra os meus decretos, mais que as gentes, contra os meus preceitos ainda mais que todos os países que estão ao redor dela; com efeito (os Israelitas) rejeitaram as minhas leis e não andaram nos meus preceitos.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 5), 7, 'Portanto isto diz o Senhor Deus: Porque excedestes (em impiedade) as nações que estão ao redor de vós, não andastes nos meus preceitos, não observastes as minhas leis, e nem sequer procedestes segundo as leis das gentes que vivem à roda de vós,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 5), 8, 'por isso, assim fala o Senhor Deus: Aqui estou também (ó Jerusalém) contra ti, executarei no meio de ti os meus castigos à vista das nações.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 5), 9, 'Farei contra ti o que nunca fiz e que nunca mais farei, por causa de todas as tuas abominações.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 5), 10, 'Por isso os pais comerão os seus filhos no meio de ti, e os filhos comerão os seus pais; porei em execução contra ti os meus juízos e dispersarei a todo o vento o que restar de ti.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 5), 11, 'Portanto, (juro) por minha vida, diz o Senhor Deus, que, assim como violaste o meu santuário com todas as tuas infâmias e com todas as tuas abominações, eu também te exterminarei, sem um olhar benigno, sem compaixão (de ti).'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 5), 12, 'Um terço dos teus morrerá de peste e será consumido de fome no meio de ti; outro terço dos teus cairá ao fio da espada ao redor de ti; quanto porém ao outro terço, eu o espalharei a todo o vento e irei atrás dele com a espada.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 5), 13, 'Darei largas ao meu furor, neles saciarei a minha indignação, e ficarei satisfeito; então saberão que eu, o Senhor, falei no meu zelo (pela minha glória) quando tiver satisfeito sobre eles a minha indignação.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 5), 14, 'Reduzir-te-ei (ó Jerusalém) a uma desolação, a ser o opróbrio entre as nações que estão ao redor de ti, à vista de todos os que forem passando.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 5), 15, 'Serás um opróbrio, uma vergonha, um escarmento e assombro entre os povos que te cercam, quando eu executar contra ti os meus juízos com furor, com indignação, com a minha ira vingadora sou eu, o Senhor, que o digo;'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 5), 16, 'quando despedir as funestas e mortíferas setas da fome contra vós (aumentarei, mais e mais, a fome, quebrarei entre vós o báculo do pão);'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 5), 17, 'quando enviar contra vós a fome e as mais cruéis feras até vos privarem de filhos; quando a peste e o sangue passarem por meio de ti (ó povo infiel), quando fizer vir a espada sobre ti. Sou eu, o Senhor, que o digo.');
INSERT INTO bible_chapters (book_id, chapter_number, total_verses)
INSERT INTO bible_verses (chapter_id, verse_number, text) VALUES
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 6), 1, 'Foi-me dirigida a palavra do Senhor, a qual dizia:'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 6), 2, 'Filho de homem, vira o teu rosto, para os montes de Israel e profetiza contra eles.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 6), 3, 'Dirás: Montes de Israel, ouvi a palavra do Senhor Iavé: Assim fala o Senhor Iavé às montanhas e aos outeiros, às quebradas e aos vales: Eis que mandarei sobre sobre vós a espada e destruirei os vossos (santuários construídos nos) lugares altos.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 6), 4, 'Serão demolidos os vossos altares, quebradas as vossas colunas; farei cair os vossos (homens) mortos diante dos vossos ídolos;'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 6), 5, 'estenderei os cadáveres dos filhos de Israel diante dos seus ídolos; espalharei os vossos ossos ao redor dos vossos altares;'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 6), 6, 'em todos os lugares, em que habitais, as cidades ficarão desertas, e os altos serão arrasados, de modo que os vossos altares serão destruídos e devastados, os vossos ídolos partidos e aniquilados, as vossas colunas despedaçadas, desfeitas as vossas obras.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 6), 7, 'Feridos de morte cairão no meio de vós, e sabereis que eu sou o Senhor.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 6), 8, 'Mas deixar-vos-ei um resto, (isto é) alguns salvos da espada, quando vos tiver dispersado por vários países.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 6), 9, 'E esses dentre vós que tiverem escapado, lembrar-se-ão de mim entre as nações, para onde foram levados cativos, quando eu quebrar o seu coração adúltero, que se afastou de mim, e os seus olhos prostituídos aos ídolos. Eles se desgostarão de si mesmos, por causa dos males que fizeram, praticando todas as suas abominações;'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 6), 10, 'saberão que eu, o Senhor, não disse debalde que lhes havia de fazer este mal.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 6), 11, 'Assim fala o Senhor Deus; Bate com a tua mão, dá pancadas com o teu pé, e dize: Ai! sobre todas as abominações iníquas da casa de Israel, porque eles hão-de perecer pela espada, pela fome e pela peste.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 6), 12, 'Aquele que estiver longe, morrerá de peste; o que estiver perto, cairá aos golpes da espada; o que ficar sitiado, morrerá de fome, porque fartarei neles a minha indignação.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 6), 13, 'Saberão que eu sou o Senhor, quando os seus mortos estiverem estendidos no meio dos seus ídolos, à roda dos seus altares, em todos os outeiros elevados, em todos os cumes dos montes, debaixo de toda a árvore verdejante, debaixo de todo o carvalho frondoso, lugares onde queimaram fragrantes incensos a todos os seus ídolos.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 6), 14, 'Estenderei a minha mão contra eles, e deixarei desolada e devastada a terra, desde o deserto até Diblata, em todos os lugares em que habitam, e saberão que eu sou o Senhor.');
INSERT INTO bible_chapters (book_id, chapter_number, total_verses)
INSERT INTO bible_verses (chapter_id, verse_number, text) VALUES
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 7), 1, 'Foi-me dirigida a palavra do Senhor, a qual dizia:'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 7), 2, 'Tu, filho de homem, (atende) assim fala o Senhor Deus à terra de Israel: Eis o fim! Já vem o fim sobre os quatro lados desta terra.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 7), 3, 'Agora chega o fim para ti; desafogarei o meu furor contra ti, julgar-te-ei segundo o teu proceder, farei recair sobre ti todas as tuas abominações.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 7), 4, 'O meu olho não te poupará. não me compadecerei de ti, mas farei recair sobre ti as tuas obras, e as tuas abominações estarão no meio de ti. Então sabereis que eu sou o Senhor.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 7), 5, 'Isto diz o Senhor Deus: Uma desgraça única! Eis que uma calamidade (singularíssima) chega.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 7), 6, 'O fim vem, vem o fim; ele despertou contra ti; ei-lo aí vem!'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 7), 7, 'Ó tu que habitas nesta terra, uma total ruína vem sobre ti! É chegado o tempo, está perto o dia (da mortandade)! É (chegada) a confusão! Não mais alegria sobre os montes.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 7), 8, 'E agora, vou já derramar a minha ira sobre ti, satisfazer em ti o meu furor; julgar-te-ei segundo os teus caminhos, farei recair sobre ti todas as tuas abominações.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 7), 9, 'O meu olho não perdoará, não me compadecerei de ti, mas farei recair sobre ti as tuas obras, e as tuas abominações estarão no meio de ti. Então sabereis que sou eu, o Senhor que castigo.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 7), 10, 'Eis o dia, ei-lo aí vem! Chegou o dia da total destruição, floresceu a vara, brotou-a soberba.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 7), 11, 'A iniquidade levantou-se com a vara da impiedade; não escapará nada deles, nem do povo, nem do seu ruído; e não haverá neles descanso.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 7), 12, 'Chegou o tempo, está próximo o dia! O que compra, não alegre; e o que vende, não chore, porque a ira (do Senhor) está sobre todo o seu povo.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 7), 13, 'O que vende, não tornará a possuir o que vendeu, ainda que esteja entre os viventes, porque a visão (que tive) relativa a toda a sua multidão não ficará sem efeito, e ninguém encontrará segurança por causa da sua iniquidade.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 7), 14, 'Soa a trombeta, tudo está pronto, mas ninguém vai à batalha, porque a minha ira está sobre todo o povo.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 7), 15, 'Fora, a espada; dentro, a peste e a fome; o que está no campo, morrerá à espada; os que estão na cidade, serão devorados pela peste e pela fome.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 7), 16, 'Os que dentre eles fugirem, andarão sobre as montanhas como pombas dos vales, todos gemendo, cada um por causa da sua iniquidade.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 7), 17, 'Todas as mãos se enfraquecerão, todos os joelhos se fundirão em água.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 7), 18, 'Cingir-se-ão de sacos, o medo os cobrirá; em todo o rosto haverá confusão, e todas as suas cabeças serão rapadas (em. sinal de dor).'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 7), 19, 'A sua prata será lançada às ruas, e o seu ouro será reputado como esterco. A sua prata e o seu ouro não os poderão livrar no dia do furor do Senhor. Não saciarão (com, isso) a sua alma, e os seus ventres se não se encherão, porque a sua iniquidade fez disso um motivo de queda.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 7), 20, 'Orgulhavam-se dos seus adornos, e disso fizeram os seus ídolos abomináveis; por tal motivo farei que seja para eles uma imundicie,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 7), 21, 'pô-lo-ei nas mãos dos estranhos para ser saqueado: servirá de presa aos ímpios da terra, que o contaminarão.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 7), 22, 'Apartarei deles o meu rosto e será profanado o meu santuário; entrarão nele bárbaros que o macularão.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 7), 23, 'Prepara cadeias, porque a terra está cheia de delitos sanguinários, e a cidade repleta de violências.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 7), 24, 'Farei vir os mais perversos dentre as gentes, e eles se apoderarão das suas casas; farei cessar a soberba dos poderosos, e serão profanados os seus santuários.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 7), 25, 'Chega a ruína! Eles buscarão a paz, e não a haverá.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 7), 26, 'A um desastre sucederá outro, a uma notícia (funesta) outra notícia sucederá; buscarão visões junto dos profetas, e a lei não existirá no sacerdote, nem o conselho nos anciães.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 7), 27, 'O rei chorará, e o príncipe cobrir-se-á de tristeza, e as mãos do povo da terra tremerão de medo. Tratá-los-ei segundo as suas obras, julgá-los-ei conforme eles julgaram os outros. Então saberão que eu sou o Senhor.');
INSERT INTO bible_chapters (book_id, chapter_number, total_verses)
INSERT INTO bible_verses (chapter_id, verse_number, text) VALUES
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 8), 1, 'No ano sexto, no sexto mês, aos cinco do mês, quando eu estava sentado em minha casa e estavam sentados diante de mim os anciães de Judá, caiu sobre mim a mão do Senhor Deus.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 8), 2, 'E tive uma visão; Era uma figura que tinha o aspecto de fogo; dos seus rins para baixo, era de fogo; e dos rins para cima, era como uma luz resplandecente, como um metal brilhante.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 8), 3, 'E estendeu uma semelhança de mão, tomou-me por uma madeixa da minha cabeça; e o espírito levantou-me entre a terra e o céu, e levou-me a Jerusalém, em visões divinas, pondo-me junto da porta interior que olha para a banda do aquilão, onde tinha sido colocado o ídolo do ciúme, que provoca a emulação (de Deus).'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 8), 4, 'E eis que aparecia ali a glória do Deus de Israel, conforme a visão que eu tinha tido no descampado,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 8), 5, 'Ele disse-me: Filho de homem, levanta os teus olhos para o norte. Levantei os olhos para o norte e vi ao norte da porta do altar aquele ídolo do ciúme, à entrada.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 8), 6, 'E ele disse-me: Filho de homem, vês o que fazem estes, as grandes abominações que a casa de Israel comete aqui, para que me retire para longe do meu santuário? Pois verás abominações ainda maiores,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 8), 7, 'Conduziu-me à entrada do átrio, e vi que havia ali um buraco na parede.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 8), 8, 'E disse-me: Filho de homem, escava a parede. Tendo eu escavado a parede, apareceu uma porta.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 8), 9, 'E ele disse-me: Entra e vê as péssimas abominações que estes aqui cometem.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 8), 10, 'Tendo entrado, vi que havia ali imagens de toda a sorte de répteis e de animais imundos, e que ídolos da casa de Israel estavam pintados na parede por toda a roda.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 8), 11, 'Setenta homens dos anciães da casa de Israel estavam em pé diante dos ídolos e Jezomas, filho de Safam, também em pé no meio, deles, tendo cada um na sua mão um turíbulo, donde se elevava o fumo do incenso, como uma névoa.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 8), 12, 'E ele disse-me: Vês bem, filho de homem, o que os anciães da casa de Israel fazem nas trevas, o que cada um deles pratica no segredo da sua câmara, ornada de ídolos? Com efeito, eles dizem: O Senhor não nos vê, o Senhor retirou-se da (nossa) terra.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 8), 13, 'Então disse-me ele: Verás ainda muitas outras grandes abominações que estes cometem.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 8), 14, 'E levou-me a entrada da porta da casa do Senhor, que olha para a banda do aquilão, e eis que estavam ali umas mulheres sentadas, chorando Adónis.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 8), 15, 'Ele disse-me: Viste, filho de homem? (Pois) ainda adorado, maiores abominações do que estas.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 8), 16, 'Introduziu-me, então, no átrio interior da casa do Senhor; e eis que se achavam à porta do templo do Senhor, entre o vestíbulo e o altar, uns vinte e cinco homens, que tinham as costas voltadas para o templo do Senhor, e o rosto voltado para o oriente, os quais se prostravam, para o oriente, diante do Sol. (ver nota)'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 8), 17, 'E ele disse-me: Viste, filho de homem; Porventura é coisa pouca, para a casa de Judá, fazer as abominações que têm feito aqui? (Será preciso que) vão ainda encher a terra de iniquidade e irritar-me sem cessar? E eis que chegam ao seu nariz um ramo.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 8), 18, 'Pois também eu os tratarei com rigor, o meu olho não os poupará, não me compadecerei deles: quando me gritarem aos ouvidos em alta voz, não os atenderei.');
INSERT INTO bible_chapters (book_id, chapter_number, total_verses)
INSERT INTO bible_verses (chapter_id, verse_number, text) VALUES
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 9), 1, 'Então uma grande voz gritou aos meus ouvidos: Os flagelos da cidade estão a chegar, cada um com um instrumento de morte em sua mão.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 9), 2, 'E eis que vinham seis homens pelo caminho da porta superior que olha para o norte, trazendo cada um em sua mão um instrumento de ruína. Havia também no meio deles um homem vestido de roupas de Unho, com um tinteiro de escriba à cinta. Entraram e puseram-se junto do altar de bronze. (ver nota)'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 9), 3, 'E a glória do Deus de Israel elevou-se de cima do querubim, sobre o qual estava, indo-se pôr à entrada do templo. O Senhor chamou o homem, que estava vestido de roupas de linho e que tinha o tinteiro de escriba à cinta,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 9), 4, 'e disse-lhe: Passa pelo meio da cidade, pelo meio de Jerusalém, e com um tau marca a fronte dos homens que gemem e que se doem de todas as abominações que se fazem no meio dela.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 9), 5, 'E aos outros disse, ouvindo-o eu: Passai pela cidade, seguindo-o, e feri; não sejam, compassivos os vossos olhos, não tenhais compaixão alguma. (ver nota)'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 9), 6, 'Velhos, jovens, donzelas, meninos, mulheres, matai-os a todos, sem que nenhum escape; mas não mateis nenhum daqueles sobre quem virdes o tau. E começai pelo meu santuário. Começaram, pois, (a matança) pelos anciães que estavam diante da casa (do Senhor).'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 9), 7, 'E disse-lhes: Profanai a casa, enchei os seus átrios de mortos, e depois, sai. Eles saíram e iam matando os que estavam na cidade.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 9), 8, 'Acabada a matança, ficando só eu ali, prostrei-me com o rosto por terra e disse, gritando: Ai, Senhor Deus! Porventura destruirás tudo o que resta de Israel, derramando o teu furor sobre Jerusalém?'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 9), 9, 'Ele disse-me: A iniquidade da casa de Israel e da casa de Judá é grande, imensamente grande: a terra está toda coberta de sangue, e a cidade repleta de injustiças, porque eles disseram: O Senhor abandonou a terra, o Senhor não vê.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 9), 10, 'Pois também o meu olho não poupará, não terei compaixão alguma; sobre a sua cabeça farei recair as suas obras.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 9), 11, 'E eis que o homem, vestido de roupas de linho, que tinha o tinteiro à cinta, veio dar contas (da sua missão), dizendo: Fiz o que mandaste.');
INSERT INTO bible_chapters (book_id, chapter_number, total_verses)
INSERT INTO bible_verses (chapter_id, verse_number, text) VALUES
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 10), 1, 'E olhei, e eis que no firmamento, que estava sobre a cabeça dos querubins, havia uma espécie de pedra de safira, à semelhança dum trono, sobre eles.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 10), 2, '(O Senhor) falou ao homem que estava vestido de roupas de linho, assim: Vai aos intervalos das rodas que estão debaixo dos querubins, enche a tua mão de carvões ardentes, que estão entre os querubins, e espalha-os sobre a cidade. E ele foi, à minha vista.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 10), 3, 'Os querubins estavam ao lado direito da casa (do Senhor) quando lá entrou aquele homem, e a nuvem encheu o átrio interior.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 10), 4, 'A glória do Senhor elevou-se de cima dos querubins, indo-se pôr à entrada da casa, e a casa ficou coberta com a nuvem, e o átrio encheu-se do esplendor da glória do Senhor.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 10), 5, 'O ruído das asas dos querubins ouviu-se até ao átrio exterior, parecendo-se com a voz de Deus Omnipotente, quando fala.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 10), 6, 'Tendo o Senhor dado ao homem, que estava vestido de roupas de linho, esta ordem: Toma do fogo do intervalo das rodas que estão entre os querubins ele foi e pôs-se junto das rodas.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 10), 7, 'Então um querubim estendeu a mão do meio dos querubins para o fogo, que estava entre os querubins, pegou nele e pô-lo nas mãos daquele que estava vestido de roupas de linho, o qual, tomando-o, saiu.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 10), 8, 'Via-se nos querubins uma semelhança de mão de homem debaixo das suas asas.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 10), 9, 'Olhei ainda e (vi que) havia quatro rodas junto dos querubins: uma roda junto de cada querubim. O aspecto destas rodas era como ó duma pedra de crisólito.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 10), 10, 'Todas quatro pareciam semelhantes, como se uma roda estivesse no melo de outra roda.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 10), 11, 'Ao avançar, moviam-se nas quatro direcções, e não tornavam para trás quando andavam, porque, para onde a que estava primeiro dirigia o seu caminho, para lá também as outras seguiam, sem voltar para nenhum outro lado.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 10), 12, 'Todo o corpo (dos querubins), o seu dorso, as suas mãos e asas, bem como as rodas, estavam cheios de olhos em toda a volta: cada um dos quatro tinha uma roda.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 10), 13, 'A estas rodas ouvi dar o nome de turbilhão.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 10), 14, 'Cada um (destes querubins) tinha quatro faces: a primeira face era face de querubim; a segunda face era face de homem; a terceira era face de leão; e a quarta era face de águia.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 10), 15, 'Os querubins elevaram-se: eram os seres vivos que eu tinha visto junto do rio Cobar.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 10), 16, 'Quando os querubins andavam, também as rodas andavam igualmente junto deles; e, quando os querubins estendiam as suas asas para se elevarem da terra, as rodas também não se desviavam de junto deles.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 10), 17, 'Quando eles paravam, paravam elas; quando eles se elevavam, elas se elevavam com eles, porque o espirito dos seres vivos (também) estava nelas.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 10), 18, '(Depois) saiu a glória do Senhor da entrada do templo e pôs-se sobre os querubins.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 10), 19, 'Os querubins estenderam as suas asas e elevaram-se da terra, a meus olhos, partindo, juntamente com as rodas. Pararam à entrada da porta oriental da casa do Senhor, e a glória do Deus de Israel estava sobre eles.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 10), 20, 'Estes são os mesmos seres vivos que vi debaixo do Deus de Israel, junto do rio Cobar; conheci que eram querubins.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 10), 21, 'Cada um deles tinha quatro faces, cada um quatro asas; e debaixo das suas asas apareciam umas semelhanças de mãos humanas.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 10), 22, 'As suas faces eram semelhantes às que eu tinha visto do rio Cobar. Cada um caminhava direito para a frente.');
INSERT INTO bible_chapters (book_id, chapter_number, total_verses)
INSERT INTO bible_verses (chapter_id, verse_number, text) VALUES
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 11), 1, '(Depois disto) o espirito arrebatou-me e conduziu-me à porta oriental da casa do Senhor, a que olha para o nascente. E eis que se achavam à entrada da porta vinte e cinco homens, no meio dos quais distingui Jezonias, filho de Azur, e Feltias, filho de Banaias, chefes do povo.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 11), 2, '(O Senhor) disse-me: Filho de homem, são estes os varões que maquinaram o mal e dão maus conselhos nesta cidade,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 11), 3, 'dizendo: Porventura não estão as nossas casas edificadas há muito tempo? Esta (cidade) é a caldeira, e nós somos a carne.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 11), 4, 'Por isso profetiza contra eles, profetiza, filho de homem.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 11), 5, 'Então caiu sobre mim o espírito do Senhor e disse-me: Fala: Isto diz o Senhor: Assim é que discorreis, ó (filhos da), casa de Israel! Eu conheço os pensamentos que sobem ao vosso espírito.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 11), 6, 'Multiplicastes as mortes nesta cidade, enchestes as suas ruas de cadáveres.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 11), 7, 'Portanto isto diz o Senhor Deus: Os que vós matastes, que prostrastes no meio da cidade, estes são a carne, e ela é a caldeira; mas eu vos tirarei do meio dela. (ver nota)'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 11), 8, 'Vós temeis a espada, e eu farei cair sobre vós a espada, diz o Senhor Deus.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 11), 9, 'Lançar-vos-ei fora desta cidade, entregar-vos-ei nas mãos dos estrangeiros e exercerei sobre vós os meus juízos.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 11), 10, 'Perecereis aos golpes da espada; julgar-vos-ei nos confins de Israel, e sabereis que sou o Senhor.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 11), 11, 'Esta cidade não será para vós uma caldeira, nem vós sereis a carne no meio dela; julgar-vos-ei nos confins de Israel.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 11), 12, 'E sabereis que sou o Senhor, cujos preceitos não seguistes, cujas leis não observastes, pois procedestes segundo os costumes das gentes que vivem à roda de vós.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 11), 13, 'Enquanto eu profetizava, morreu Feltias filho de Banaias. Então prostrei-me com o rosto em terra, gritando em alta voz; Ai, Senhor Deus! Vais acabar com os restos de Israel? (ver nota)'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 11), 14, 'Foi-me dirigida a palavra do Senhor, nestes termos:'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 11), 15, 'Filho de homem, os teus irmãos, os teus irmãos, as pessoas do teu parentesco, toda a casa de Israel, são todos aqueles a quem os moradores de Jerusalém dizem: Estais longe do Senhor! A nós é que a terra foi dada para a possuirmos. (ver nota)'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 11), 16, 'Por isso, assim fala o Senhor Iavé: Coloquei-os longe entre as nações, dispersei-os por vários países, mas eu mesmo lhes servirei de santuário, durante breve tempo, nos países para onde foram.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 11), 17, 'Dize-lhes pois: Isto diz o Senhor Deus: Juntar-vos-ei do meio dos povos, reunir-vos-ei dos países, pelos quais fostes dispersados, e dar-vos-ei a terra de Israel.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 11), 18, 'Eles entrarão nela e tirarão do seu seio todos os ídolos e todas as abominações,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 11), 19, 'e eu lhes darei um só coração e derramarei no seu íntimo um novo espírito; tirarei da sua carne o coração de pedra e dar-lhes-ei um coração de carne,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 11), 20, 'para que andem nos meus preceitos e guardem as minhas leis e as cumpram. Então serão o meu povo e eu o seu Deus.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 11), 21, 'Quanto àqueles, cujo coração anda preso aos seus ídolos e às suas abominações, farei recair sobre as suas cabeças as suas obras, diz o Senhor Deus.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 11), 22, 'Então os querubins estenderam as suas asas, e com eles se puseram em movimento as rodas, enquanto a glória do Deus de Israel estava sobre eles.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 11), 23, 'E a glória do Senhor elevando-se para sair da cidade, foi-se pôr sobre o monte que está no oriente da cidade.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 11), 24, 'Depois disto, o espírito tomou-me e conduziu-me outra vez, em visão, no espírito de Deus, à Caldeia, onde estavam os cativos, e, assim, se dissipou a visão que eu tinha tido.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 11), 25, 'E contei aos cativos tudo o que o Senhor me havia feito ver.');
INSERT INTO bible_chapters (book_id, chapter_number, total_verses)
INSERT INTO bible_verses (chapter_id, verse_number, text) VALUES
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 12), 1, 'Foi-me dirigida a palavra do Senhor, nestes termos:'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 12), 2, 'Filho de homem, tu moras no meio duma raça de rebeldes, que têm olhos para ver e não vêem ouvidos para ouvir e não ouvem: é uma raça de rebeldes.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 12), 3, 'Tu, filho de homem, vai preparando para ti uma bagagem de emigrante e emigra em pleno dia, diante deles; passa do lugar em que estás a outro lugar, à vista deles: talvez reconheçam que são uma raça de rebeldes.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 12), 4, 'Á vista deles tira para fora, de dia, os teus utensílios de emigrante, como bagagem de quem emigra, e sai de tarde diante deles, como faz quem vai emigrar.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 12), 5, 'Faze à vista deles uma abertura na muralha, por onde sairás.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 12), 6, '(Em seguida) à vista deles, põe às costas a tua bagagem e leva-a quando escurecer; cobre com um véu o teu rosto, para não veres a terra, porque eu te dei como sinal à casa de Israel.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 12), 7, 'Fiz, como me tinha sido ordenado; tirei para fora a minha bagagem, em pleno dia, como bagagem de emigrante; à tarde, fiz pela minha mão uma abertura na muralha e saí na escuridão, levando às costa a minha bagagem, à vista deles.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 12), 8, 'Pela manhã foi-me dirigida a palavra do Senhor, nestes termos:'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 12), 9, 'Filho de homem, porventura a casa de Israel, casa de rebeldes, não te disse: Que fazes tu?'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 12), 10, 'Dize-lhes: Assim fala o Senhor Iavé: Este oráculo é sobre o príncipe que está em Jerusalém e sobre toda a casa de Israel que está nesta cidade.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 12), 11, 'Dize: Eu sou para vós um símbolo: assim como eu fiz, assim lhes sucederá a eles: serão deportados, irão para o cativeiro.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 12), 12, 'O príncipe, que está no meio deles, levará às costas a sua bagagem e sairá na escuridão; escavarão a muralha para o fazerem sair; cobrirá o seu rosto com um véu, para com os seus olhos não ver a terra.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 12), 13, 'Estenderei sobre ele a minha rede, e ele será tomado nas minhas malhas; levá-lo-ei a Babilônia, à terra dos Caldeus, mas ele não a verá, e lá morrerá,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 12), 14, 'Espalharei, a todos os ventos, todos aqueles que estão em redor dele, a sua guarda e as suas tropas, e irei com a espada desembainhada atrás deles.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 12), 15, 'E saberão que eu sou o Senhor, quando os tiver dispersado entre as nações e disseminado por países estrangeiros.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 12), 16, 'Mas reservarei dentre eles um pequeno número de homens que escaparão da espada, da fome e da peste, para que contem todas as suas maldades entre as nações para onde forem. E saberão que eu sou o Senhor.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 12), 17, 'Foi-me dirigida a palavra do Senhor nestes termos:'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 12), 18, 'Filho de homem, come o teu pão com susto e bebe a tua água com inquietação e angústia,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 12), 19, 'E dirás ao povo desta terra; Assim fala o Senhor Deus aos que habitam em Jerusalém, à terra de Israel: Eles comerão o seu pão com susto, e beberão a sua água na desolação, porque esta terra será privada de tudo o que contém, será desolada por causa da iniquidade de todos os que habitam nela.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 12), 20, 'As cidades, agora povoadas, ficarão desertas, e a terra devastada. Assim sabereis que eu sou o Senhor.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 12), 21, 'Foi-me dirigida a palavra do Senhor, nestes termos:'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 12), 22, 'Filho de homem, que provérbio é esse que vós tendes na terra de Israel: Os dias passam, e em nada vão parar todas as visões? (ver nota)'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 12), 23, 'Pois dize-lhes: Assim fala o Senhor Deus: Farei cessar este provérbio; não se tornará mais a dizer em Israel. Assegura-lhes que estão para chegar os dias e o cumprimento de todas as visões.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 12), 24, 'Porque não será vã, daqui em diante, visão alguma, nem haverá predição enganadora no meio da casa de Israel,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 12), 25, 'pois eu, o Senhor, falarei; toda a palavra que eu proferir será cumprida sem demora; em vossos dias, ó casa rebelde, falarei e executarei a minha palavra, diz o Senhor Deus.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 12), 26, 'Foi-me dirigida a palavra do Senhor, nestes termos:'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 12), 27, 'Filho de homem, eis o que dizem os da casa de Israel: A visão que este vê, é para daqui a muitos dias, ele profetiza para tempos remotos,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 12), 28, 'Por isso dize-lhes; Assim fala o Senhor Deus: Não será mais diferida qualquer palavra minha; a palavra que eu proferir, cumprir-se-á, diz o Senhor.');
INSERT INTO bible_chapters (book_id, chapter_number, total_verses)
INSERT INTO bible_verses (chapter_id, verse_number, text) VALUES
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 13), 1, 'Foi-me dirigida a palavra do Senhor, nestes termos;'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 13), 2, 'Filho de homem, profetiza contra os (falsos) profetas de Israel, que se metem a profetizar, dize a esses que profetizam por sua cabeça: Ouvi a palavra do Senhor:'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 13), 3, 'Assim fala o Senhor Deus: Ai dos profetas insensatos, que seguem o seu próprio espírito e não vêem nada!'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 13), 4, 'Os teus profetas, ó Israel, são como raposas nos escombros.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 13), 5, 'Vós não subistes às brechas, não construístes um muro em defesa da casa de Israel, para resistir no combate, no dia do Senhor.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 13), 6, 'Têm visões inanes, profetizam a mentira, dizendo: Oráculo do Senhor sendo certo que o Senhor não os enviou: apesar disso, ainda esperam a realização da sua palavra.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 13), 7, 'Porventura não são vãs as visões que tendes mentirosos os oráculos que proferis, quando dizeis: Assim falou o Senhor sendo certo que eu não falei?'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 13), 8, 'Por cuja causa assim fala o Senhor Deus: Porque dizeis coisas vãs e tendes visões mentirosas, por isso eis que venho contra vós, diz o Senhor Deus.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 13), 9, 'A minha mão descarregará sobre os profetas que têm visões vãs e que profetizam a mentira: não serão admitidos na assembleia do meu povo. não serão inscritos no censo da casa de Israel, não entrarão na terra de Israel e vós sabereis que eu sou o Senhor Deus.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 13), 10, 'Porque eles enganaram o meu povo. dizendo: Paz! e paz não havia. Quando o meu povo levanta uma parede, eles cobrem-na de barro.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 13), 11, 'Dize (pois) a esses, que rebocam a parede com barro, que ela cairá; porque virá uma chuva de inundação, e farei cair do céu pedras grandes, e (enviarei) um vento tempestuoso que tudo destruirá.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 13), 12, 'E, quando a muralha tiver caído, não vos será dito (por zombaria): Onde está o reboco que fizestes?'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 13), 13, 'Por cuja causa isto diz o Senhor Deus: Farei sair impetuosamente um vento de tempestade na minha indignação, e sobrevirá uma chuva que tudo inunde no meu furor, e arrojarei pedras enormes com ira para total destruição.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 13), 14, 'Destruirei a muralha que vós rebocastes com o barro, arrasá-la-ei, descobrir-se-ão os seus fundamentos, e ela cairá; e o que a rebocou será destruído com ela. Assim sabereis que eu sou o Senhor.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 13), 15, 'E satisfarei a minha indignação contra a muralha e contra aqueles que a rebocaram com barro, e vos direi então: Já não existe a muralha, nem existem os que a rebocaram,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 13), 16, 'esses profetas de Israel que profetizavam sobre Jerusalém, e que tinham acerca dela visões de paz, quando tal paz não havia, diz o Senhor Deus.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 13), 17, 'Tu, filho de homem, volta o teu rosto contra as filhas do teu povo, que se põem a profetizar por sua cabeça, e profetiza contra elas.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 13), 18, 'dizendo-lhes: Isto diz o Senhor Deus: Ai daqueles que cosem ligaduras para todas as junturas das mãos e que fabricam véus para as cabeças das pessoas de todas as estaturas, a fim de lhes apanharem as almas! Acaso pretendeis atentar contra a vida do meu povo e poupar a vossa própria vida? (ver nota)'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 13), 19, 'Vós profanais-me diante do meu povo por um punhado de cevada e por um pedaço de pão, matando as almas que não deviam morrer, e prometendo a vida às que não deviam viver, mentindo ao meu povo, que acredita nestas mentiras.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 13), 20, 'Por cuja causa isto diz o Senhor Deus: Eis que vou contra as vossas ligaduras, com que apanhais as almas como a pássaros; arrancá-las-ei dos vossos braços e deixarei fugir as almas que vós apanhastes, como a pássaros.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 13), 21, 'Romperei os vossos véus e livrarei o meu povo do vosso poder, e eles não serão mais expostos à presa entre as vossas mãos, e sabereis que eu sou o Senhor.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 13), 22, 'Porque contristastes o coração do justo com as vossas mentiras, quando eu mesmo o não contristei, e porque fortificastes as mãos do ímpio, para que ele se não convertesse do seu mau caminho e vivesse,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 13), 23, 'por isso não tomareis mais a ter visões vãs, nem a pronunciar oráculos, porque livrarei o meu povo das vossas mãos, e vós sabereis que eu sou o Senhor.');
INSERT INTO bible_chapters (book_id, chapter_number, total_verses)
INSERT INTO bible_verses (chapter_id, verse_number, text) VALUES
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 14), 1, 'Vieram ter comigo alguns dos anciães de Israel e sentaram-se diante de mim.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 14), 2, 'Então foi-me dirigida a palavra do Senhor, nestes termos:'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 14), 3, 'Filho de homem, essas pessoas instalaram os seus ídolos nos seus corações, e põem incessantemente o escândalo da sua iniquidade diante da sua face: acaso deverei permitir que me consultem?'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 14), 4, 'Por isso fala-lhes e dize-lhes: Assim fala o Senhor Deus: Se qualquer da casa de Israel, que tiver posto ídolos no seu coração e colocado o escândalo da sua iniquidade diante de seus olhos, for ter com algum profeta (para me interrogar per meio dele), eu mesmo, o Senhor, lhe responderei segundo a multidão dos seus ídolos.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 14), 5, 'a fim de apanhar a casa de Israel pelo seu próprio coração, ela que se retirou de mim por causa de todos os seus ídolos.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 14), 6, 'Por isso dize à casa de Israel: Assim fala o Senhor Deus: Convertei-vos, retirai-vos dos vossos ídolos, afastai o vosso rosto de todas as vossas abominações.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 14), 7, 'Com efeito, se um homem da casa de Israel, ou um estrangeiro estabelecido em Israel, se afastar de mim e puser ídolos no seu coração, e colocar o escândalo da sua iniquidade diante dos seus olhos, e for, depois, ter com algum profeta para me interrogar por melo dele, eu, o Senhor, lhes responderei por mim mesmo (castigando-o);'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 14), 8, 'voltarei o meu rosto contra tal homem, farei dele um exemplo e um provérbio, exterminá-lo-ei do meio do meu povo e vós sabereis que eu sou o Senhor. (ver nota)'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 14), 9, 'Se o profeta errar e proferir um (falso) oráculo, serei eu, o Senhor, que permitirei que se engane esse profeta; estenderei a minha mão sobre ele e exterminá-lo-ei do meio do meu povo de Israel.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 14), 10, '(Desta forma) levarão sobre si (o castigo da) sua iniquidade a falta do profeta será como a do consulente'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 14), 11, 'a fim de que a casa de Israel se não torne mais a extraviar, para longe de mim, e a fim de que ela se não corrompa por todas as suas prevaricações. Então serão o meu povo, e eu o seu Deus, diz o Senhor Iavé.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 14), 12, 'Foi-me dirigida a palavra do Senhor, nestes termos:'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 14), 13, 'Filho de homem, se algum país pecar contra mim, cometendo grandes prevaricações, e eu estender a minha mão sobre ele, quebrando a vara do seu pão, enviando contra ele a fome, para exterminar animais e pessoas, (ver nota)'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 14), 14, 'ainda que no meio dele se achem estes três homens, Noé, Daniel e Job, eles salvar-se-ão (apenas a si próprios) pela sua justiça, diz o Senhor Iavé. (ver nota)'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 14), 15, 'Se eu enviar a essa terra animais ferozes, para a destruírem, e ela se tornar um deserto, em que ninguém possa passar por causa das feras,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 14), 16, 'ainda que estes três homens estejam nela, (juro) pela minha vida, diz o Senhor Deus, que eles não livrarão nem os seus filhos, nem as suas filhas; só eles serão livres, e a terra, será destruída.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 14), 17, 'Ou se eu fizer vir a espada sobre esta terra, dizendo: Passe a espada pelo meio desta terra e lhe matar os homens e os animais,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 14), 18, 'se estes três homens se acharem no meio dela, (juro) pela minha vida, diz o Senhor Deus, que eles não livrarão nem os seus filhos, nem as suas filhas: só eles serão livres.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 14), 19, 'Ou se eu enviar a peste contra essa terra, e saciar a minha indignação sobre ela no sangue, exterminando os homens e os animais,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 14), 20, 'se Noé, Daniel e Job se acharem no meio dela, (juro) pela minha vida, diz o Senhor Deus, que não livrarão nem os seus filhos, nem as suas filhas; só eles se salvarão pela sua própria justiça.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 14), 21, 'Assim fala o Senhor Deus; Se eu enviar contra Jerusalém os meus quatro terríveis flagelos, a espada e a fome, os animais ferozes e a peste para lhe matar os homens e o gado.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 14), 22, 'ficarão nela todavia alguns que se salvarão, que escaparão, filhos e filhas. Eis que eles virão ter convosco (aqui a Babilônia) e vós vereis o seu (mau) proceder e as suas obras, e consolar-vos-eis do mal que fiz vir sobre Jerusalém, de todas as calamidades que sobre ela descarreguei.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 14), 23, 'Eles vos consolarão, quando virdes o seu (mau) proceder e as suas obras; reconhecereis que não foi sem um justo motivo que eu fiz nela tudo o que fiz oráculo do Senhor Iavé.');
INSERT INTO bible_chapters (book_id, chapter_number, total_verses)
INSERT INTO bible_verses (chapter_id, verse_number, text) VALUES
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 15), 1, 'Foi-me dirigida a palavra do Senhor, nestes termos:'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 15), 2, 'Filho de homem, por que há-de valer mais o pau da vide que o de qualquer outro ramo das árvores da floresta?'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 15), 3, 'Porventura tomar-se-á dela um pau que sirva para se fazer alguma obra, ou fabricar-se-á dela uma estaca para que se lhe pendure qualquer objecto?'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 15), 4, 'Eis que se lança ao fogo para lhe servir de pasto; ambas as suas extremidades consome a chama, e o meio dele é abrasado; acaso será útil para alguma obra?'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 15), 5, 'Mesmo quando estava inteiro, não servia para nenhuma obra; quanto menos, depois que um fogo o devorar e queimar, poderá ser trabalhado?'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 15), 6, 'Portanto isto diz o Senhor Deus: assim como, entre as árvores das selvas, é o pau da vide aquele que destinei para ser consumido pelo fogo, assim entregarei (ao fogo) os habitantes de Jerusalém.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 15), 7, 'Voltarei o meu rosto (irado) contra eles; escaparam ao fogo, mas o fogo os consumirá. Saberão que eu sou o Senhor, depois que tiver voltado o meu rosto contra eles,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 15), 8, 'e tiver tornado a sua terra deserta, por eles terem sido infiéis, diz o Senhor Deus.');
INSERT INTO bible_chapters (book_id, chapter_number, total_verses)
INSERT INTO bible_verses (chapter_id, verse_number, text) VALUES
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 16), 1, 'Foi-me dirigida a palavra do Senhor, nestes termos:'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 16), 2, 'Filho de homem, faze conhecer a Jerusalém as suas abominações.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 16), 3, 'Dir-lhe-iás: Assim fala o Senhor Deus a Jerusalém: Pela tua origem e pelo teu nascimento és da terra de Canaan; teu pai era Amorreu, e tua mãe Heteia. (ver nota)'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 16), 4, 'Quando vieste ao mundo, no dia do teu nascimento, não te foi cortado o cordão umbilical, não foste lavada em água, não te esfregaram com sal, nem foste enfaixada.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 16), 5, 'Não houve olho que olhasse para ti com piedade, com o intuito de te prestar algum destes serviços, compadecido de ti; mas foste arrojada sobre a face da terra, com desprezo por ti, no dia em que nasceste.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 16), 6, 'Passando junto de ti, vi-te, debatendo-te no teu sangue, e disse-te: Vive no teu sangue. Ainda que coberta do teu sangue, vive!'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 16), 7, 'Fiz-te crescer como a erva no campo, e cresceste, e te tornaste grande, e atingiste uma beleza perfeita, no tempo da puberdade, em que se te desenvolveram os seios e cresceu o cabelo; porém estavas nua, completamente nua.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 16), 8, 'Passei junto de ti, e vi-te: era (chegado) o teu tempo, o tempo dos amores (ou da puberdade). Estendi sobre ti o meu manto e cobri a tua nudez; jurei-te (fidelidade), fiz aliança contigo, diz o Senhor Deus, e tu ficaste sendo minha.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 16), 9, 'Lavei-te com água, limpei-te do teu sangue e ungi-te com óleo.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 16), 10, 'Vesti-te de roupas bordadas, dei-te calçado de couro fino, cingi-te de linho e cobri-te de seda'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 16), 11, 'Ornei-te de preciosos enfeites, pus-te braceletes nas mãos, um colar ao pescoço.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 16), 12, 'uma argola no nariz, arrecadas nas orelhas, e um formoso diadema na cabeça.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 16), 13, 'Foste enfeitada de ouro e prata, vestida de linho fino, de seda e de roupas bordadas; nutriste-te da flor da farinha, de mel e de azeite; tornaste-te mui formosa e chegaste a ser rainha.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 16), 14, 'O teu renome espalhou-se entre as nações, por causa da tua formosura, porque era perfeita, graças ao esplendor de que eu te havia revestido, diz o Senhor Deus.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 16), 15, 'Mas puseste a tua confiança na tua beleza, aproveitaste-te da tua reputação para te prostituires, ofereceste a tua lascívia a todos os que passavam, entregando-te a eles.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 16), 16, 'Tomando dos teus vestidos, fizeste lugares altos para ti, de variadas cores, e ali fornicaste, como nunca sucedeu, nem sucederá'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 16), 17, 'Pegaste nos teus belos adornos, feitos do meu ouro e da minha prata, que te tinha dado, e fizeste deles figuras humanas, às quais te prostituiste.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 16), 18, 'Pegaste nos teus vestidos bordados e cobriste com eles os teus ídolos, diante dos quais puseste o meu azeite e os meus perfumes.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 16), 19, 'Puseste diante deles, como oferenda de agradável odor, o pão que te dei, a flor da farinha, o azeite e o mel, com que te nutria. Eis o que foi feito, diz o Senhor Deus.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 16), 20, 'Pegaste nos teus filhos e nas tuas filhas, que me tinhas gerado, e sacrificaste-os a esses ídolos, para seu pasto. Porventura é pequena demais a tua fomicação?'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 16), 21, 'Imolaste os meus filhos e entregaste-lhos, fazendo-os passar pelo fogo, em sua honra.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 16), 22, 'No meio de todas as tuas abominações e prostituições, não te lembraste dos dias da tua mocidade, quando estavas nua, completamente nua, rojando-te no teu sangue.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 16), 23, 'Depois de tanta malícia tua (ai, ai de ti! diz o Senhor Deus),'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 16), 24, 'edificaste para ti um lupanar, e fizeste para ti em todas as praças públicas uma casa de prostituição.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 16), 25, 'Puseste à entrada de todas as ruas o sinal da tua prostituição, tornaste abominável a tua formosura, entregaste-te a todos os que passavam, e multiplicaste as tuas fornicações.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 16), 26, 'Prostituiste-te aos filhos do Egipto, teus vizinhos, muito corpulentos, multiplicaste as tuas prostituições para me irritares.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 16), 27, 'Eis que estendi a minha mão sobre ti, diminuí a tua porção, entreguei-te ao arbítrio das filhas dos Filisteu, tuas inimigas, que se envergonham do teu infame procedimento.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 16), 28, 'Não te dando ainda por satisfeita, prostituíste-te aos filhos dos Assírios; e, depois desta prostituição, nem ainda assim ficaste satisfeita.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 16), 29, 'Multiplicaste a tua fornicação (ou idolatria) na terra dos mercadores, entre os Caldeus, mas nem ainda assim ficaste saciada.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 16), 30, 'Quão fraco é o teu coração, diz o Senhor Deus, para teres feito todas estas obras próprias da mais descarada meretriz!'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 16), 31, 'Edificaste a casa da tua prostituição à entrada de todas as ruas fizeste o teu alto em todas as praças públicas; nem foste como uma meretriz que com o seu desdém aumenta o preço, (ver nota)'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 16), 32, 'mas como uma mulher adúltera, que, em vez de seu marido, recebe os estranhos.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 16), 33, 'A todas as prostitutas se dão presentes mas tu é que os deste a todos os teus amantes, que os recompensaste, para de todas as partes virem a tua casa para as tuas prostituições. (ver nota)'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 16), 34, 'Assim, nas tuas prostituições, te sucedeu tudo ao contrário das mulheres (de má vida): ninguém te procurava, mas tu é que davas a paga, em vez de a receber, fazendo tudo ao contrário do que as outras fazem.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 16), 35, 'Por isso, ó meretriz, ouve a palavra do Senhor.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 16), 36, 'Isto diz o Senhor Deus: Porque gastaste mal o teu dinheiro e descobriste a tua nudez, nas tuas prostituições com teus amantes e com teus ídolos abomináveis e porque lhes deste o sangue de teus filhos,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 16), 37, 'eis que vou juntar todos os teus amantes, com quem luxuriaste todos os que amaste e todos os que aborreceste, juntá-los-ei de todas as partes contra ti, e descobrirei a tua nudez diante deles, e verão toda a tua nudez.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 16), 38, 'Julgar-te-ei segundo as leis que há sobre as adúlteras e sobre as que derramam sangue, e farei de ti uma vítima sangrenta de furor e do zelo.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 16), 39, 'Entregar-te-ei nas suas mãos, e eles destruirão o lugar da tua prostituição, demolirão os teus lugares altos, despir-te-ão dos teus vestidos, roubarão os teus adornos e deixar-te-ão despojada e nua.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 16), 40, 'Conduzirão contra ti uma multidão de gente, apedrejar-te-ão e atravessar-te-ão com as suas espadas;'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 16), 41, 'queimarão as tuas casas, pondo-lhes fogo, e executarão contra ti juízos, aos olhos dum grande número de mulheres; porei fim às tuas prostituições e não tornai-ás mais a dar recompensas. (ver nota)'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 16), 42, 'Saciarei a minha indignação contra ti, e o meu zelo se retirará de ti, e me apaziguarei, e não me tornarei mais a irar.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 16), 43, 'Porque te não lembraste dos dias da tua mocidade e me irritaste com todos estes excessos, por isso também fiz que recaísse sobre a tua cabeça o teu proceder, diz o Senhor Deus. Não cometeste o mal com todas as tuas práticas abomináveis?'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 16), 44, 'Eis que todos os que proferem provérbios te aplicarão este: Tal mãe, tal filha. (ver nota)'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 16), 45, 'Tu és bem a filha de tua mãe, a qual abandonou o seu esposo (místico, que ó Deus) e os seus filhos (sacrificando-os aos ídolos); e és a irmã de tuas irmãs, que abandonaram os seus esposos e os seus filhos; vossa mãe é Hetela e vosso pal Amorreu.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 16), 46, 'Tua irmã mais velha é a Samaria com as suas filhas (ou cidades) que habitam à tua mão esquerda; e tua irmã mais nova, que habita à tua mão direita, é Sodoma com suas filhas (ou cidades). (ver nota)'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 16), 47, 'Porém tu não sòmente não ficaste atrás em seguir os seus caminhos e em obrar segundo as suas maldades, mas foste mais perversa que elas em teu proceder,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 16), 48, 'Por minha vida, diz o Senhor Deus. (juro) que o que fez Sodoma, tua irmã, ela e suas filhas, não foi tanto como o que tu e suas filhas fizestes.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 16), 49, 'Eis qual foi a iniquidade de Sodoma, tua irmã: a soberba, a fartura de pão, a ociosidade dela e de suas filhas e o não estender a mão para o pobre e para o desgraçado.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 16), 50, 'Ensoberbeceram-se, cometeram abominações diante de mim, e eu as destruí, como tu viste.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 16), 51, 'A Samaria também não cometeu metade dos teus pecados; tu as ultrapassaste ambas com as tuas maldades, justificaste as tuas irmãs com todas as abominações que cometeste. (ver nota)'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 16), 52, 'Leva, pois, a ignomínia das tuas faltas, com que justificaste tuas irmãs, procedendo mais culpàvelmente que elas: são mais justas do que tu. Por isso confunde-te, também, leva a tua ignomínia, tu que justificaste as suas irmãs.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 16), 53, 'Todavia eu as restabelecerei, fazendo que voltem os cativos de Sodoma e de suas filhas, como também os cativos da Samaria e de suas filhas; depois farei voltar os teus filhos cativos para o meio dos ídolos,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 16), 54, 'a fim de que suportes a tua ignomínia e te confundas de tudo o que tens feito para as consolar.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 16), 55, 'Tua irmã Sodoma e suas filhas tornarão ao seu antigo estado; Samaria e suas filhas tornarão também ao seu estado antigo; e tu e tuas filhas tomareis também ao vosso primitivo estado.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 16), 56, 'O nome da tua irmã Sodoma não foi ouvido na tua boca, no tempo da tua soberba. (ver nota)'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 16), 57, 'Antes que a tua malícia estivesse descoberta, como agora está, antes que tu fosses o opróbrio para as filhas da Síria e das suas redondezas, para todas as filhas dos Filisteus, que te insultam de todos os lados.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 16), 58, 'Levaste sobre ti as tuas maldades e a tua ignomínia, diz o Senhor Deus.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 16), 59, 'Porque isto diz o Senhor Deus: Procederei contigo como tu procedeste, tu que desprezaste o juramento, rompendo a aliança (que tinha feito contigo).'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 16), 60, 'Apesar disso, lembrar-me-ei da aliança que tinha feito contigo, nos dias da tua mocidade, e estabelecerei contigo uma aliança eterna.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 16), 61, 'Então te recordarás do teu (mau) proceder e te confundirás, quando receberes tuas irmãs mais velhas e tuas irmãs mais novas, e eu tas der por filhas, mas isto não em virtude da tua aliança. (ver nota)'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 16), 62, 'Eu é que renovarei a minha aliança contigo, e saberás que sou o Senhor,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 16), 63, 'a fim de que te recordes e te confundas, e não te atrevas a abrir mais a boca por causa da tua confusão, quando eu te tiver perdoado todas as coisas que fizeste, diz o Senhor Deus.');
INSERT INTO bible_chapters (book_id, chapter_number, total_verses)
INSERT INTO bible_verses (chapter_id, verse_number, text) VALUES
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 17), 1, 'Foi-me dirigida a palavra do Senhor, nestes termos:'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 17), 2, 'Filho de homem, propõe um enigma, conta uma parábola à casa de Israel.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 17), 3, 'Dir-lhe-ás; Assim fala o Senhor Deus: uma grande águia, de grandes asas, de enorme envergadura coberta de penas multícolores, veio ao Líbano e levou o cimo do cedro.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 17), 4, 'arrancou as últimas pontas dos seus ramos, transportou-as à terra de Canaan e pô-las numa cidade de negociantes (que é Babilônia).'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 17), 5, 'Depois tomou um rebento de planta daquele país e pô-lo num terreno preparado, plantou-o como um salgueiro, junto de águas abundantes.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 17), 6, 'Depois de ter brotado, cresceu e tornou-se uma videira extensa, porém de pouca altura, cujos ramos olhavam para a águia, e cujas raízes estavam debaixo dela. Tornou-se uma cepa, lançou sarmentos e produziu renovos. (ver nota)'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 17), 7, 'Havia uma grande águia, de grandes asas e de muitas penas; e eis que esta videira voltou as suas raízes e estendeu os seus sarmentos para ela, do talhão em que estava plantada, a fim de ser regada.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 17), 8, 'Estava plantada numa boa terra, junto de copiosas águas, a fim de lançar folhas e dar fruto, e tornar-se uma grande videira. (ver nota)'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 17), 9, 'Dize; Assim fala o Senhor Deus: Será possível que ela venha a ser bem sucedida? (A primeira águia) não lhe arrancará as suas raízes, não deitará abaixo os seus frutos, não secará todos os sarmentos que tiver brotado, e não ficará ela árida, e isto sem necessidade de grande força, nem de muita gente para arrancar pela raiz?'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 17), 10, 'Ei-la aí está plantada; mas prosperará? Quando a tocar um vento abrasador, não se secará ela, não ficará árida, no talhão em que foi plantada?'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 17), 11, 'Foi-me dirigida a palavra do Senhor, nestes termos:'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 17), 12, 'Dize a esta casa rebelde: Não sabeis o que isto significa? Dize: Eis que veio o rei de Babilônia sobre Jerusalém, tomou o rei e os seus príncipes e levou-os para o seu reino, para Babilônia.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 17), 13, 'Depois tomou um (membro) da estirpe real, fez aliança com ele e recebeu dele juramento; até os fortes do país ele tirou'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 17), 14, 'para que o reino ficasse abatido e não se levantasse, mas guardasse a sua aliança e a observasse.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 17), 15, 'Porém este (príncipe), revoltou-se contra ele, enviando mensageiros ao Egipto, para que lhe desse cavalos e muita gente. Porventura prosperará ou encontrará salvação, quem isto fez? O que violou a aliança, escapará?'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 17), 16, '(Juro) pela minha vida, diz o Senhor Deus, que no país do monarca que o fez rei, cujo juramento desprezou, cuja aliança violou, (lá) no meio de Babilônia morrerá.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 17), 17, 'Faraó, com o seu grande exército e com o seu muito povo, não combaterá a seu favor, quando se levantarem plataformas e construírem muros, para matar muitas pessoas.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 17), 18, 'Desprezou o juramento, violou a aliança, apesar de ter dado a sua mão. Tendo feito todas estas coisas, não escapará. (ver nota)'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 17), 19, 'Portanto isto diz o Senhor Deus: Juro pela minha vida que foi o meu juramento que ele desprezou, a minha aliança que violou: farei recair isso sobre a sua cabeça.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 17), 20, 'Estenderei a minha rede sobre ele, e será apanhado nos meus laços; levá-lo-ei a Babilônia e lá o julgarei pela prevaricação cometida contra mim.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 17), 21, 'Todos os fugitivos do seu exército cairão mortos a espada; os que ficarem serão espalhados a todo o vento, e sabereis que eu, o Senhor, é que falei.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 17), 22, 'Isto diz o Senhor Deus: Tomarei do cimo do elevado cedro, cortarei do mais alto de seus ramos um tenro garfo, e plantá-lo-ei sobre uma elevadíssima montanha, (ver nota)'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 17), 23, 'Eu o plantarei na alta montanha de Israel, e ele deitará ramos e dará fruto, e tornar-se-á um grande cedro; todas as aves habitarão debaixo dele, todas as espécies de voláteis repousarão à sombra dos seus ramos.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 17), 24, 'E saberão todas as árvores dos campos que eu, o Senhor é que humilho a árvore elevada e exalto a árvore humilde, que seco a árvore verde e faço reverdecer a árvore seca. Eu o Senhor, o disse e o farei.');
INSERT INTO bible_chapters (book_id, chapter_number, total_verses)
INSERT INTO bible_verses (chapter_id, verse_number, text) VALUES
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 18), 1, 'Foi-me dirigida a palavra do Senhor, nestes termos:'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 18), 2, 'Por que repetis este provérbio na terra de Israel: Os pais comeram os agraços, e os dentes dos filhos é que ficaram botos?'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 18), 3, '(Juro) pela minha vida, diz o Senhor Deus, que não tereis de repetir mais entre vós este provérbio em Israel.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 18), 4, 'Eis que todas as vidas são minhas; como é minha a vida do pai, assim o é também a do filho. O que pecar, esse morrerá. (ver nota)'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 18), 5, 'Se um homem for justo, procedendo conforme a equidade e a justiça;'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 18), 6, 'se não comer nos montes e não levantar os seus olhos para os ídolos da casa de Israel; se não manchar a mulher do seu próximo e não se juntar com a menstruada;'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 18), 7, 'se não oprimir ninguém e der o penhor ao seu devedor; se não tirar nada do alheio por violência; se der do seu pão ao faminto e agasalhar o nu;'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 18), 8, 'se não emprestar com usura e não receber mais do que o que emprestou; se afastar a sua mão da iniquidade, e sentenciar com justiça entre homem e homem;'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 18), 9, 'se andar nos meus preceitos e guardar os meus mandamentos, agindo segundo a verdade esse tal é justo; viverá certamente, diz o Senhor Deus.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 18), 10, 'Porém, se gerar filho violento que derrame sangue, que cometa qualquer destas faltas'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 18), 11, 'ainda quando não as cometa todas que coma sobre os montes, que manche a mulher do seu próximo,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 18), 12, 'que maltrate o necessitado e o pobre, que tire por violência os bens de outro, que não dê o penhor ao seu devedor, que levante os seus olhos para os ídolos, que cometa abominações,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 18), 13, 'que empreste com usura e receba mais do que o que emprestou este filho não poderá viver: porque praticou tais abominações, deve morrer, e o seu sangue será contra ele mesmo.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 18), 14, 'Porém, se este, por sua vez, tiver um filho que, vendo todos os pecados que seu pai cometeu, os vir e não os fizer semelhantes,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 18), 15, 'que não comer sobre os montes, não levantar os seus olhos para os ídolos da casa de Israel, não violar a mulher do seu próximo;'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 18), 16, 'que não oprimir pessoa alguma, que não retiver o penhor, que nada tirar por violência, que der do seu pão ao faminto e agasalhar o nu;'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 18), 17, 'que apartar a sua mão de toda a injustiça contra o pobre, que não receber usura, nem mais do que emprestou; que observar as minhas leis, que andar nos meus preceitos este não morrerá por causa da iniquidade de seu pai, mas certamente viverá.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 18), 18, 'Seu pai porque praticou violências e rapinas contra seu irmão, porque praticou o mal no meio do seu povo, (esse, sim, é que) morrerá em castigo da sua iniquidade.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 18), 19, 'E vós dizeis: por que razão não leva o filho a iniquidade de seu pai? Porque o filho procedeu conforme a equidade e conforme a justiça, porque guardou todos os meus preceitos e os praticou, por isso viverá certamente.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 18), 20, 'O que pecar, esse morrerá: o filho não levará a iniquidade do pai, e o pai não levará a Iniquidade do filho; a justiça do justo será sobre ele, e a impiedade do ímpio será sobre ele.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 18), 21, 'Mas, se o ímpio se apartar de todos os pecados que cometeu, se guardar todos os meus preceitos e proceder conforme a equidade e a justiça, certamente viverá, não morrerá.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 18), 22, 'Não se guardará mais lembrança de nenhuma das iniquidades que cometeu; ele viverá por causa da justiça que praticou.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 18), 23, 'Porventura será do meu gosto a morte do ímpio? — diz o Senhor Deus. Não quero antes que ele se retire dos seus (maus) caminhos e viva?'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 18), 24, 'Mas, se o justo se apartar da sua justiça e vier a cometer a iniquidade, segundo todas as abominações que o ímpio pratica, porventura viverá? Serão esquecidas todas as obras de justiça que tiver feito; por causa da prevaricação em que caiu e do pecado que cometeu, por causa disto morrerá.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 18), 25, 'E vós dizeis: O caminho do Senhor não é justo! Ouvi, pois, (filhos da) casa de Israel: Porventura o meu caminho não é justo? Não são antes os vossos injustos?'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 18), 26, 'Quando o justo se apartar da sua justiça, para cometer a iniquidade, e morrer nesse estado, morrerá pelas obras injustas que cometeu.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 18), 27, 'Quando o ímpio se apartar da impiedade cometida e proceder segundo a equidade e a justiça, fará viver a sua alma.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 18), 28, 'Reconsiderando e apartando-se de todas as iniquidades que praticou, viverá certamente, não morrerá.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 18), 29, 'Contudo, dizem ainda os filhos de Israel: O caminho do Senhor não é justo. Porventura os meus caminhos não são justos, casa de Israel? Não são antes os vossos injustos?'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 18), 30, 'Por isso, casa de Israel, julgarei cada um conforme os seus caminhos, diz o Senhor Deus. Convertei-vos, apartai-vos de todas as vossas iniquidades, e a iniquidade não se tornará em vossa ruína.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 18), 31, 'Lançai para longe de vós todas as prevaricações de que vos tornastes culpados, e fazei-vos um coração novo e um espírito novo. Por que hás-de morrer, ó casa de Israel?'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 18), 32, 'Não sinto gosto na morte do que morre, diz o Senhor Deus! Convertei-vos e vivei.');
INSERT INTO bible_chapters (book_id, chapter_number, total_verses)
INSERT INTO bible_verses (chapter_id, verse_number, text) VALUES
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 19), 1, 'E tu pronuncia uma lamentação sobre os príncipes de Israel.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 19), 2, 'Dirás: Que era a tua mãe? Uma leoa entre leões; criava os seus filhos deitada no meio dos leõezinhos.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 19), 3, 'Criou um dos seus filhos, e ele se fez leão; aprendeu a despedaçar uma presa e devorou homens.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 19), 4, 'As nações ouviram falar dele, e ele foi apanhado no fosso delas. Levaram-no preso com cadeias para a terra do Egipto.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 19), 5, 'A mãe, vendo que a sua expectativa, que as suas esperanças se tinham malogrado, pegou noutro dos seus filhos e fez dele um (novo) leão.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 19), 6, 'Andava entre os leões, tornou-se leão; aprendeu a despedaçar a presa e devorou homens;'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 19), 7, 'devastou os seus palácios e converteu em deserto as suas cidades; o país, com tudo o que nele havia, ficou amedrontado, ao ouvir os seus rugidos.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 19), 8, 'Juntaram-se contra ele as nações vizinhas, estenderam sobre ele a sua rede, e foi apanhado no fosso delas.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 19), 9, 'Meteram-no numa jaula, levaram-no ao rei ao Babilônia, carregado de cadeias puseram-no numa fortaleza, para que se não tornasse mais a ouvir o seu rugido sobre os montes de Israel.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 19), 10, 'Tua mãe, sendo como uma videira plantada junto das águas, deu frutos e lançou folhagem, por causa das muitas águas.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 19), 11, 'Os seus ramos vigorosos vieram a ser ceptros de soberanos, e o seu tronco elevou-se no meio dos seus ramos frondosos. Mostrou-se em (toda a) sua grandeza, com a multidão dos seus sarmentos.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 19), 12, 'Mas depois foi arrancada com ira, lançada por terra; o vento do oriente secou o seu fruto; foram quebrados e secaram-se os seus ramos robustos; o fogo os devorou.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 19), 13, 'E agora ela foi transplantada para um deserto, para uma terra seca e árida.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 19), 14, 'Dos seus ramos saiu uma chama que devorou o seu fruto, e não mais houve nela ramo vigoroso. Ceptro de soberanos. Cântico lúgubre é este, e para pranto servirá.');
INSERT INTO bible_chapters (book_id, chapter_number, total_verses)
INSERT INTO bible_verses (chapter_id, verse_number, text) VALUES
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 20), 1, 'No ano sétimo, no quinto mês, aos dez dias do mês, vieram alguns dos anciães de Israel consultar, o Senhor e sentaram-se diante de mim.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 20), 2, 'Foi-me dirigida a palavra do Senhor, nos termos seguintes:'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 20), 3, 'Filho de homem, fala assim aos anciães de Israel: Isto diz o Senhor Deus: Porventura viestes vós a consultar-me? (Juro) pela minha vida, que não vos responderei, diz o Senhor Deus.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 20), 4, 'Se tu os julgas, filho de homem, se tu os julgas, põe-lhes diante dos olhos as abominações de seus pais.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 20), 5, 'Dir-lhes-ás; Isto diz o Senhor Deus : No dia em que escolhi Israel, em que levantei a minha mão em favor da casa de Jacob e me dei a conhecer na terra do Egipto, em que levantei a minha mão a favor deles, dizendo: Eu sou o Senhor vosso Deus —'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 20), 6, 'nesse dia levantei a minha mão em seu favor, jurando transferi-los da terra do Egipto para a terra que lhes tinha preparado, a qual mana leite e mel, a mais excelente de todas as terras.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 20), 7, 'Disse-lhes então: Cada um afaste de si os ídolos sedutores dos seus olhos; não vos mancheis com os ídolos do Egipto; eu sou o Senhor vosso Deus.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 20), 8, 'Eles, porém, revoltaram-se contra mim, não me quiseram ouvir; nenhum lançou fora os abomináveis ídolos sedutores dos seus olhos; não abandonaram os ídolos do Egipto. Pensei derramar a minha indignação sobre eles, saciar neles a minha ira no meio da terra do Egipto;'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 20), 9, 'porém procedi (de outra forma) por amor do meu nome, para que ele não ficasse desacreditado diante das gentes, no melo das quais estavam, entre as quais me tinha dado a conhecer, para os tirar da terra do Egipto.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 20), 10, 'Tirei-os, pois, da terra do Egipto e conduzi-os ao deserto.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 20), 11, 'Dei-lhes os meus preceitos, ensinei-lhes as minhas leis, em cuja observância o homem encontrará a vida.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 20), 12, 'Além disto, dei-lhes os meus sábados, para que fossem um sinal entre mim e eles e para que soubessem que eu sou o Senhor que os santifico.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 20), 13, 'Mas, (depois de tudo isto) os filhos da casa de Israel irritaram-me no deserto, não andaram nos meus preceitos, rejeitaram as minhas leis, que dão vida ao que as observa, e profanaram inteiramente os meus sábados. Resolvi, pois, derramar o meu furor sobre eles no deserto e exterminá-los.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 20), 14, 'Mas, por amor do meu nome, procedi (de outra forma) de modo que ele não ficasse desacreditado diante das gentes, aos olhos das, quais eu os tinha feito sair.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 20), 15, 'Também levantei a minha mão contra eles no deserto, jurando não os introduzir na terra que lhes dei, a qual mana leite e mel, a melhor de todas as terras'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 20), 16, 'porque eles rejeitaram as minhas leis. não andaram nos meus preceitos, profanaram os meus sábados, pois o seu coração ia após os ídolos.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 20), 17, 'Todavia olhei para eles com olhos de misericórdia, para os não matar, e (de facto) não os exterminei no deserto.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 20), 18, 'Disse a seus filhos no deserto: Não sigais os exemplos de vossos pais, não imiteis os seus costumes, não vos mancheis com os seus ídolos.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 20), 19, 'Eu sou o Senhor vosso Deus; andai nos meus preceitos, guardai as minhas leis e praticai-as.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 20), 20, 'Santificai os meus sábados, para que eles sejam um sinal entre mim e vós, e para que se saiba que eu sou o Senhor vosso Deus.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 20), 21, 'Porém os filhos revoltaram-se contra mim, não andaram segundo os meus preceitos, não guardaram nem puseram em prática as minhas leis, que o homem deve cumprir para viver, e profanaram os meus sábados. Planeei derramar o meu furor sobre eles, satisfazer a minha ira contra eles no deserto.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 20), 22, 'Mas desviei a minha mão, o que fiz por causa do meu nome, para que ele não fosse profanado diante das gentes, aos olhos das quais eu os tinha feito sair.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 20), 23, 'Tornei outra vez a levantar a minha mão contra eles no deserto, jurando espalhá-los por entre as nações, disseminá-los por países estrangeiros,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 20), 24, 'visto não terem observado as minhas leis, haverem rejeitado os meus preceitos, profanado os meus sábados, e terem-se-lhes ido os olhos após os ídolos de seus pais.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 20), 25, 'Por isso cheguei mesmo a dar-lhes preceitos não bons, leis nas quais não podiam achar a vida.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 20), 26, 'Tornei-os impuros pelas suas oblações, quando faziam sacrificar os seus primogênitos (a Moloch) para os punir, a fim de que soubessem que eu sou o Senhor.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 20), 27, 'Portanto fala à casa de Israel, filho de homem, desta maneira: Isto diz o Senhor Deus: Ainda depois disto me ultrajaram vossos pais, sendo-me infiéis.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 20), 28, 'Quando os introduzi na terra, que com juramento tinha prometido dar-lhes, olharam para todos os outeiros elevados e para todas as árvores frondosas, e ali fizeram os seus sacrifícios, apresentaram as suas oferendas que me irritavam, ali trouxeram os seus agradáveis perfumes e ofereceram as suas libações.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 20), 29, 'Disse-lhes então: Que lugar alto é este aonde vós ides? E até ao dia de hoje lhe ficou o nome de lugar alto.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 20), 30, 'Portanto dize à casa de Israel: Assim fala o Senhor Deus: É verdade que vos tornais imundos, segundo os caminhos de vossos pais, e vos entregais à mesma prostituição com os seus ídolos (ou idolatria).'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 20), 31, 'Na oblação dos vossos dons (a Moloch), quando fazeis passar os vossos filhos pelo fogo, vós vos contaminais com todos os vossos ídolos até hoje. E (depois disto) deixar-me-ei ainda consultar por vós, casa de Israel? (Juro) pela minha vida, diz o Senhor Deus. que o não farei.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 20), 32, 'Nem se efectuará o que pensais no vosso espirito quando dizeis: Seremos (felizes) como as nações e como os povos da terra, adorando os paus e as pedras.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 20), 33, 'Juro pela minha vida, diz o Senhor Deus, que reinarei sobre vós com mão forte, com braço estendido, na efusão do meu furor.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 20), 34, 'Tirar-vos-ei do meio dos povos e vos juntarei dos países, para onde tínheis sido dispersos, com mão forte, com braço estendido, com efusão do meu furor,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 20), 35, 'e vos levarei ao deserto dos povos e lá entrarei em juízo convosco, cara a cara. (ver nota)'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 20), 36, 'Assim como entrei em juízo com vossos pais no deserto da terra do Egipto, assim vos julgarei a vós, diz o Senhor Deus.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 20), 37, 'E vos submeterei ao meu ceptro, e vos farei entrar nos laços da minha aliança.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 20), 38, 'E separarei dentre vós os rebeldes, os que se revoltaram contra mim, e os farei sair da terra em que habitam como estrangeiros; porém não entrarão na terra de Israel, e vós sabereis que eu é que sou o Senhor.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 20), 39, 'A vós, casa de Israel, isto diz o Senhor Deus: Cada um de vós vá servir os seus ídolos. Porém, depois disto, com certeza me ouvireis e não profanareis mais o meu santo nome com as vossas oferendas e com os vosso ídolos. (ver nota)'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 20), 40, '(Eu sei que) sobre o meu santo monte sobre o alto monte de Israel, diz o Senhor Deus, ali me servirá toda a casa de Israel, toda ela estabelecida na terra; ali (os filhos de Israel) me serão agradáveis, ali requererei as vossas oferendas e as primícias dos vossos dons com tudo o que me consagrardes.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 20), 41, 'Então vos receberei como um perfume agradável quando vos tiver tirado do meio dos povos e vos tiver juntado dos países, por onde tínheis sido espalhados; e tornar-se-á manifesta em vós a minha santidade aos olhos das nações.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 20), 42, 'E sabereis que eu é que sou o Senhor, quando vos introduzir na terra de Israel, na terra que jurei, de mão levantada, dar a vossos pais.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 20), 43, 'Ali vos lembrareis dos vossos caminhos e de todas as maldades com as quais vos manchastes, e vos desagradareis de vós mesmos, à vista de todas as maldades que cometestes.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 20), 44, 'Então sabereis, casa de Israel, que eu é que sou o Senhor, quando eu proceder convosco (benignamente) por amor do meu nome, em vez de vos tratar conforme os vossos maus caminhos e os vossos detestáveis pecados, diz o Senhor Deus.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 20), 45, 'Foi-me dirigida a palavra do Senhor, nestes termos:'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 20), 46, 'Filho de homem, volta o rosto para meio-dia fala para o sul, profetiza contra a floresta do meio-dia.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 20), 47, 'Dirás à floresta do meio-dia: Ouve a palavra do Senhor: Isto diz o Senhor Deus: Eis que vou acender em ti um fogo que queimará em ti todo o lenho verde e todo o lenho seco; não se apagará a chama deste incêndio, e queimar-se-á nela todo o rosto, desde o meio-dia até ao aquilão.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 20), 48, 'Toda a carne verá que eu, o Senhor, lancei o fogo o qual se não apagará.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 20), 49, 'Então eu disse: Ah! Senhor Deus! Eles dizem isto de mim: Este não nos fala, senão por parábolas (obscuras)?');
INSERT INTO bible_chapters (book_id, chapter_number, total_verses)
INSERT INTO bible_verses (chapter_id, verse_number, text) VALUES
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 21), 1, 'Foi-me dirigida a palavra do Senhor nestes termos:'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 21), 2, 'Filho de homem, volta o teu rosto para Jerusalém fala contra o santuário, profetiza contra a terra de Israel.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 21), 3, 'Dirás á terra de Israel: Assim fala o Senhor Deus: Eis que venho contra ti; tirarei a minha espada da sua bainha e matarei no meio de ti o justo e o ímpio.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 21), 4, 'Porque vou exterminar no meio de ti o justo e o ímpio, por isso a minha espada sairá da sua bainha contra toda a carne, desde o meio-dia até ao aquilão.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 21), 5, 'Toda a carne saberá que eu, o Senhor, tirei a minha espada da sua bainha e que a não tornarei a meter nela.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 21), 6, 'Tu pois, filho de homem, geme, geme na presença deles com o coração despedaçado e repleto de amargura.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 21), 7, 'Quando te disserem: Por que gemes? responderás: Pelo que ouço; ao chegar da notícia, todos os corações se mirrarão de medo, todas as mãos ficarão sem forças, todos os espíritos se abaterão e todos os joelhos se farão em água. Ei-la aí vem, e já se realiza, diz o Senhor Deus.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 21), 8, 'Foi-me dirigida a palavra do Senhor, nestes termos:'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 21), 9, 'Filho de homem, profetiza, dize; Isto diz o Senhor Deus; Fala; A espada, sim, a espada está aguçada e polida.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 21), 10, 'Ela está aguçada para matar, polida para reluzir. Alegrar-nos-emos. O ceptro de meu filho despreza toda a madeira. (ver nota)'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 21), 11, 'Dei-a a polir para a ter na mão; esta espada está aguçada e polida, para estar na mão do (rei de Babilônia) que deve fazer a matança,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 21), 12, 'Grita e uiva, filho de homem, porque esta (espada) está desembainhada contra o meu povo, contra todos os príncipes de Israel que foram entregues à espada com o meu povo. Tu, pois, dá pancadas na tua coxa,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 21), 13, 'porque a prova foi feita; e que sucederia se não houvesse ceptro desprezador? diz o Senhor Deus.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 21), 14, 'Tu, pois filho de homem, profetiza e bate com as mãos uma na outra; dobre-se, triplique-se esta espada mortífera, a espada da grande matança que os assalta de todos os lados.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 21), 15, 'Para fazer mirrar os corações e multiplicar as vítimas, levei a todas as portas esta espada mortífera, polida para reluzir, afiada para matar.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 21), 16, 'Corta à direita ou à esquerda, para onde quer que te voltes!'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 21), 17, 'Eu mesmo baterei palmas, satisfarei a minha indignação. Eu, o Senhor, falei.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 21), 18, 'Foi-me dirigida a palavra do Senhor, nestes termos:'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 21), 19, 'Tu, filho de homem, traça dois caminhos por onde a espada do rei de Babilônia pode vir; ambos sairão dá mesma terra; no princípio de cada caminho que dá para uma cidade, põe um sinal.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 21), 20, 'Traçarás um caminho, por onde esta espada vá atacar Rabat (capital) dos filhos de Amon, e outro por onde vá para Judá, atacar a fortaleza de Jerusalém.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 21), 21, 'Porque o rei de Babilônia parou na encruzilhada, no princípio dos dois caminhos, procurando adivinhar por meio da mistura das setas, pela consulta aos ídolos domésticos e pelo exame do fígado (das vitimas).'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 21), 22, 'Caiu a sorte sobre Jerusalém, à direita, para dispor os aríetes, para intimar a mortandade, para levantar gritos de guerra, para pôr aríetes contra as portas, para erguer plataformas e edificar fortes.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 21), 23, 'Aos olhos deles isso são vãos presságios, pois têm a seu favor juramentos feitos, mas ele lembrar-lhes-á a sua iniquidade e cativá-los-á.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 21), 24, 'Portanto isto diz o Senhor Deus: Porque (me) haveis recordado a vossa iniquidade, manifestando as vossas prevaricações, patenteando os vossos pecados em todas as vossas acções, porque, digo trouxestes isso à memória, sereis castigados.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 21), 25, 'Tu, porém, ó profano, tu, ó ímpio príncipe de Israel, a quem chegou o dia com o fim da (tua) iniquidade.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 21), 26, 'Isto diz o Senhor Deus; Tira a tiara, depõe a coroa! Tudo vai mudar. O baixo será elevado, e o alto abaixado.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 21), 27, 'Ruína, ruína, ruína! Eis o que farei dela (Jerusalém): será aniquilada até que venha aquele a quem pertence o direito e a quem o entregarei.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 21), 28, 'E tu, filho de homem, profetiza e dize: Assim fala o Senhor Deus a respeito dos filhos de Amon e dos seus insultos (contra Israel). Dirás: Espada, espada, desembainhada está para matar, polida para massacrar e para luzir'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 21), 29, 'enquanto se te apresentam visões vãs, oráculos enganadores para cair sobre o pescoço dos ímpios (Amonitas) feridos, cujo dia marcado chegou com o fim da (sua) iniquidade.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 21), 30, 'Torna a recolhê-la na bainha: No lugar em que foste criada, na terra do teu nascimento, é que te julgarei; (ver nota)'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 21), 31, 'derramarei sobre ti a minha indignação; soprarei contra ti o fogo do meu furor, entregar-te-ei às mãos de homens bárbaros, artífices da destruição.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 21), 32, 'Servirás de pasto ao fogo, derramado será o teu sangue no meio da terra, ficarás entregue ao esquecimento, porque eu, o Senhor, falei.');
INSERT INTO bible_chapters (book_id, chapter_number, total_verses)
INSERT INTO bible_verses (chapter_id, verse_number, text) VALUES
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 22), 1, 'Foi-me dirigida a palavra do Senhor, nestes termos;'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 22), 2, 'E tu, filho de homem, não julgarás, não julgarás (Jerusalém) a cidade do sangue?'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 22), 3, 'Mostra-lhe todas as suas abominações. Dirás: Assim fala o Senhor Deus: Esta é a cidade que derrama o sangue no meio dela para que depressa chegue o dia da sua destruição, e a que faz ídolos para se manchar.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 22), 4, 'Tu pecaste pelo sangue que por ti foi derramado; ficaste manchada pelos ídolos que fabricaste; apressaste os teus dias (de castigo), chegaste ao termo dos teus anos; por isso fiz de ti o opróbrio das nações e o ludíbrio de todas as terras.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 22), 5, 'Os povos vizinhos e os povos distantes escarnecerão de ti, cidade de nome conspurcado, repleta de desordens.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 22), 6, 'Eis que os príncipes de Israel fiam-se na força do seu braço, para derramarem o sangue, no meio de ti.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 22), 7, 'Enchem de afrontas no meio de ti o pai e a mãe, maltratam o estrangeiro no meio de ti, oprimem no teu recinto o órfão e a viúva.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 22), 8, 'Desprezaste o meu santuário e profanaste os meus sábados.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 22), 9, 'No meio de ti há homens denunciadores que fazem derramar sangue, em ti realizam-se banquetes (idolátricos) sobre os montes, cometem-se infâmias.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 22), 10, 'Dentro de ti descobre-se a nudez do próprio pai; dentro de ti ultraja-se a mulher na ocasião do seu mênstruo;'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 22), 11, 'um comete abominações com a mulher do seu próximo, outro corrompe com um horrível incesto a sua nora, um outro faz violência à própria irmã, filha de seu pai.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 22), 12, 'Recebem-se presentes no meio de ti para derramar o sangue; tu recebes usura ou mais do que o emprestado, despojas violentamente o teu próximo, esqueces-te de mim, diz o Senhor Deus.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 22), 13, 'Por isso bati as mãos (em sinal de horror), ao ver as tuas pilhagens e o sangue derramado no meio de ti.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 22), 14, 'Porventura estará firme o teu coração, ou aguentar-se-ão as tuas mãos nos dias em que eu for contra ti? Eu, o Senhor, o disse e o farei.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 22), 15, 'Espalhar-te-ei por entre as nações, deitar-te-ei ao vento por diversas terras e farei cessar em ti a tua impureza,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 22), 16, 'e novamente tomarei conta de ti, à vista das gentes, e tu saberás que eu sou o Senhor,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 22), 17, 'Foi-me dirigida a palavra do Senhor nestes termos:'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 22), 18, 'Filho de homem, a casa de Israel tornou-se para mim em escória; todos eles são como o cobre, o estanho, o ferro e o chumbo no meio da fornalha; tornaram-se como escórias da prata. (ver nota)'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 22), 19, 'Por cuja causa isto diz o Senhor Deus: Porque vos tornastes todos em escória, por isso eis que vou juntar-vos no meio de Jerusalém.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 22), 20, 'Como se juntam a prata, o cobre, o estanho, o ferro e o chumbo no meio da fornalha, e se acende nela o fogo para os fundir, assim vos juntarei no meu furor e na minha ira, lançar-vos-ei à fornalha para vos derreter.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 22), 21, 'Juntar-vos-ei e abrasar-vos-ei nas chamas do meu furor, para vos fazer derreter no meio de Jerusalém.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 22), 22, 'Como a prata se funde no meio da fornalha, assim vós no meio desta cidade; então sabereis que eu, o Senhor, derramei a minha indignação sobre vós.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 22), 23, 'Foi-me dirigida a palavra do Senhor nestes termos:'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 22), 24, 'Filho de homem, dize a Jerusalém: Tu és uma terra imunda, que não foi regada pelas chuvas no dia do furor.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 22), 25, 'Os seus príncipes conjuram no meio dela, devoram as pessoas como um leão que ruge e que arrebata a sua presa, apoderam-se de bens e tesouros. multiplicam as viúvas no meio dela.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 22), 26, 'Os seus sacerdotes desprezam a minha lei, profanam o meu santuário; não distinguem entre o santo e o profano, não ensinam a distinguir o puro do impuro, apartam os seus olhos dos meus sábados: sou profanado no meio deles.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 22), 27, 'Os seus chefes, no meio dela, são como lobos que despedaçam a sua presa, que derramam sangue, fazem perecer vidas, para arrebatar os bens.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 22), 28, 'Os seus profetas rebocam as paredes com barro solto; têm inanes visões, oráculos enganosos. Dizem: Assim fala o Senhor Deus quando o Senhor não falou.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 22), 29, 'O povo do país entrega-se à violência e à rapina; oprime o pobre e o necessitado, vexa o estrangeiro com injustiças.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 22), 30, 'Busquei entre eles um homem que reconstruísse um muro e se pusesse na brecha, diante de mim, em favor desta terra, para eu a não destruir, e não o encontrei.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 22), 31, 'Por isso derramei a minha indignação sobre eles, consumi-os no fogo da minha ira, fiz que o seu (mau) proceder recaísse sobre as suas cabeças, diz o Senhor Deus.');
INSERT INTO bible_chapters (book_id, chapter_number, total_verses)
INSERT INTO bible_verses (chapter_id, verse_number, text) VALUES
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 23), 1, 'Foi-me dirigida a palavra do Senhor, nestes termos:'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 23), 2, 'Filho de homem, havia duas mulheres, filhas da mesma mãe.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 23), 3, 'as quais se prostituíram no Egipto, prostituíram-se na sua mocidade (como povo). Aí lhes apertaram os peitos lhes apalparam o seio virginal.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 23), 4, 'A mais velha chama-se Oola, e a sua irmã Ooliba. Desposei-me com elas, e deram à luz filhos e filhas. No tocante a seus nomes. Oola é a Samaria, e Ooliba é Jerusalém.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 23), 5, 'Oola foi-me infiel e apaixonou-se pelos seus amantes os Assírios, seus vizinhos,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 23), 6, 'vestidos de púrpura. governadores e chefes, jovens amáveis, cavaleiros montados a cavalo.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 23), 7, 'Dispensou os seus favores amorosos a estes homens escolhidos, filhos todos dos Assírios, e manchou-se com ídolos de todos aqueles de quem loucamente estava enamorada.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 23), 8, 'Porém não abandonou as prostituições que tinha tido no Egipto, pois (o Egípcios) dormiram com ela na sua adolescência, apertaram o seu selo virginal, comunicaram-lhe todas as suas impurezas.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 23), 9, 'Por isso entreguei-a nas mãos dos seus amantes, nas mãos dos filhos de Assur, por quem ardia de paixão.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 23), 10, 'Eles descobriram a sua nudez, levaram seus filhos e filhas, e mataram-na a ela própria com a espada. E ela tornou-se famosa entre as mulheres, pelo castigo que lhe foi aplicado.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 23), 11, 'Tendo visto isto, sua irmã Ooliba enlouqueceu de paixão ainda mais do que ela, e as suas prostituições excederam as de sua irmã.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 23), 12, 'Prendeu-se de paixão aos Assírios, governadores e chefes, seus vizinhos, magnificamente vestidos, cavaleiros montados nos seus cavalos, todos jovens de belo parecer.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 23), 13, 'Vi que também se manchava, que ambas seguiam o mesmo caminho,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 23), 14, '(Mas Ooliba) foi aumentando sempre a sua luxúria, mais que a outra: tendo visto uns homens pintados na parede, umas imagens dos Caldeus pintadas a mínio.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 23), 15, 'os quais tinham os rins cingidos de talabartes, e tiaras em suas cabeças, parecendo todos oficiais de guerra, dando ares de grandes senhores, representações de filhos de Babilônia, do país dos Caldeus, onde tinham nascido,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 23), 16, 'logo ao primeiro olhar concebeu por eles uma paixão louca, e mandou-lhes embaixadores à Caldeia.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 23), 17, 'E, tendo vindo ter com ela os filhos de Babilônia, ao leito dos seus amores, mancharam-na com as suas ignomínias, e ela foi por eles corrompida e, ficou farta deles.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 23), 18, 'Quando patenteou as suas fornicações e descobriu a sua nudez, retirei-me dela, assim como me tinha retirado de sua irmã.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 23), 19, 'Multiplicou as suas prostituições lembrando-se dos dias da sua mocidade, durante os quais se tinha prostituído na terra do Egipto.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 23), 20, 'Ardeu em amor por luxuriosos, cujas carnes são como as carnes dos jumentos, e cujo ardor como o ardor dos garanhões.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 23), 21, 'Renovaste as maldades da tua mocidade, quando os Egípcios apertavam os teus peitos, tocavam o teu seio juvenil.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 23), 22, 'Por isso, ó Ooliba, isto diz o Senhor Deus: Eis que vou suscitar contra ti os teus amantes, de que te aborreceste, e congregá-los-ei contra ti de todas as partes:'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 23), 23, 'os filhos de Babilônia, todos os Caldeus, os de Pecod, de Soa e de Coa, e, com eles, todos os Assirios; jovens de belo parecer, todos os governadores e chefes, capitães e cavaleiros famosos.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 23), 24, 'Virão contra ti apetrechados de carros e de rodas, com uma multidão de povos; eles se armarão de todas as partes contra ti de couraças, de escudos e de capacetes. Dar-lhes-ei o poder de te julgar, e eles te julgarão segundo as suas leis.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 23), 25, 'Desafogarei contra ti o meu zelo; eles tratar-te-ão com furor, cortar-te-ão (ignominiosamente) o nariz e as orelhas; o que restar de ti, retalharão à espada; cativarão os teus filhos e as tuas filhas, e o que restar de ti será devorado pelo fogo.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 23), 26, 'Eles te despojarão dos teus vestidos, e te roubarão os adornos.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 23), 27, 'Farei cessar as tuas maldades e prostituições que tinhas aprendido na terra do Egipto; não levantarás mais os olhos para eles, nem te lembrarás mais do Egipto.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 23), 28, 'Porque isto diz o Senhor Deus: Eis que vou entregar-te nas mãos daqueles que aborreces, nas mãos daqueles de que te fartaste.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 23), 29, 'Tratar-te-ão com ódio, levarão todos os teus trabalhos e te deixarão nua, cheia de ignomínia, ficando a descoberto a vergonha das tuas impudicícias, infâmias e prostituições.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 23), 30, 'Eles te tratarão assim, porque te prostituíste às nações entre as quais te manchaste pelo culto dos seus ídolos.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 23), 31, 'Andaste pelo mesmo caminho de tua irmã: meterei na tua mão o cálice (de amargura) que ela bebeu.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 23), 32, 'Isto diz o Senhor Deus; Beberás o cálice de tua irmã, cálice profundo e largo que dará ocasião ao riso e à mofa, tão grande é a sua capacidade.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 23), 33, 'Serás cheia de embriaguez e de dor; cálice de pasmo e terror, este cálice de tua irmã Samaria.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 23), 34, 'Tu o beberás e o esgotarás até às fezes; quebrá-lo-ás com os dentes, e, com os seus pedaços rasgarás os teus seios. Sou eu que o digo oráculo do Senhor Deus.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 23), 35, 'Portanto isto diz o Senhor Deus: Visto que te esqueceste de mim e me lançaste para trás das costas, carrega tu também com a tua maldade, com as tuas prostituições.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 23), 36, 'O Senhor disse-me; Filho de homem não julgarás tu Oola e Ooliba, não lhes mostrarás as suas maldades?'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 23), 37, 'Adulteraram e há sangue nas suas mãos; cometeram adultério com os seus ídolos, e, além disto, ofereceram-lhes para serem devorados (pelo fogo em honra de Moloch) até os filhos que me geraram.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 23), 38, 'E ainda fizeram mais contra mim; Mancharam o meu santuário, naquele dia, e profanaram os meus sábados.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 23), 39, 'Quando sacrificavam os seus filhos aos seus ídolos, entravam no meu santuário nesse mesmo dia para o profanarem: eis o que fizeram no meio da minha casa.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 23), 40, 'Mandaram buscar homens de longe, convidados por um mensageiro, os quais (logo) vieram. Para os receber te lavaste, pintaste os olhos e te adornaste com as tuas galas.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 23), 41, 'Tu te recostaste sobre um leito magnífico, diante do qual se pôs uma mesa sobre que havias colocado o meu incenso e o meu óleo.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 23), 42, 'À roda dela ouvia-se a voz de muita gente que folgava; e àquela multidão de gente, juntavam-se homens conduzidos do deserto; puseram nas suas mãos braceletes, e formosas coroas sobre as suas cabeças.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 23), 43, 'Então disse eu àquela que definhou nos adultérios; Continua ainda esta (prostituta) a entregar-se às suas luxúrias!'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 23), 44, 'Entra-se em sua casa, como em casa duma mulher pública; assim é que entravam em casa destas mulheres perdidas, Oola e Ooliba.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 23), 45, 'Mas homens justos as julgarão, como se julgam as adúlteras e como se julgam as que derramam o sangue, porque elas são adúlteras, e nas suas mãos há sangue,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 23), 46, 'Isto diz o Senhor Deus: Faze vir contra estas duas prostitutas uma multidão, para serem entregues ao terror e ao saque.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 23), 47, 'Sejam apedrejadas pelo povo e trespassadas com as suas espadas; matem seus filhos e suas filhas, e ponham fogo às suas casas.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 23), 48, 'Assim tirarei da terra a maldade, e todas as mulheres aprenderão a não imitar as vossas torpezas.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 23), 49, 'O castigo de vossas maldades cairá sobre a vossa cabeça, e suportareis o peso dos vossos pecados de idolatria. Assim sabereis que eu sou o Senhor Deus.');
INSERT INTO bible_chapters (book_id, chapter_number, total_verses)
INSERT INTO bible_verses (chapter_id, verse_number, text) VALUES
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 24), 1, 'No ano nono, no décimo mês, aos dez dias do mês, foi-me dirigida a palavra do Senhor nestes termos:'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 24), 2, 'Filho de homem, escreve a data deste dia, porque é hoje que o rei de Babilônia assentou arraiais contra Jerusalém.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 24), 3, 'Expõe à casa (de Israel) rebelde esta parábola. Assim lhes falarás; Isto diz o Senhor Deus: Põe uma caldeira ao lume; põe-na, digo, e deita-lhe água dentro.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 24), 4, 'Mete nela pedaços de carne, todos escolhidos, coxa e espádua, e acaba de a encher com os melhores ossos.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 24), 5, 'Pega na carne das reses mais gordas, põe por baixo da caldeira um montão de ossos; faze que ferva em borbulhões, até que se cozam também os ossos que estão dentro dela.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 24), 6, 'Eis o que diz o Senhor Deus: Ai da cidade do sangue, que é como uma caldeira cheia de ferrugem, ferrugem que não pode ser tirada. Esvazia-a dos bocados que tem dentro, uns após outros, sem tirar à sorte.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 24), 7, 'O sangue (inocente) que derramou está ainda no meio dela; sobre pedra nua o derramou; não o derramou sobre a terra, para o cobrir com o pó.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 24), 8, 'Para fazer cair sobre ela a minha indignação, para me vingar (como ela merece), espalhei também o seu sangue sobre a pedra nua, para que não fosse coberto.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 24), 9, 'Portanto isto diz o Senhor Deus; Ai da cidade do sangue! Também eu vou fazer uma grande fogueira!'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 24), 10, 'Junta muita lenha, acende o fogo, coze a carne prepara o tempero, e sejam queimados os ossos.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 24), 11, 'Põe, depois, a caldeira vazia sobre as brasas, para que ela aqueça e o seu cobre se abrase, e se funda dentro dela a sua imundície, e se consuma a sua ferrugem.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 24), 12, 'Vãos esforços! Não saiu dela a sua muita ferrugem, nem por meio do fogo.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 24), 13, 'Da iniundície do teu proceder eu quis limpar-te, mas não ficaste limpa das tuas impurezas; não mais serás limpa, até que satisfaça contra ti a minha indignação.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 24), 14, 'Eu, o Senhor, falei: isto acontecerá; agirei sem recuar, não perdoarei, não me aplacarei; segundo os teus caminhos e segundo as tuas obras far-se-á o teu julgamento, diz o Senhor.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 24), 15, 'Foi-me dirigida a palavra do Senhor nestes termos;'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 24), 16, 'Filho de homem, eis que vou tirar-te dum golpe aquilo que é mais agradável aos teus olhos (a tua esposa), mas tu não te lamentarás, não chorarás, não te correrão as lágrimas (pelo rosto).'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 24), 17, 'Geme em silêncio; não tomes luto, como se faz pelos mortos; põe na cabeça o teu turbante, o calçado nos teus pés; não cubras o rosto (com um véu) nem comas o pão que se dá aos que estão de luto.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 24), 18, 'Falei de manhã ao povo, e à tarde morreu minha mulher; ao outro dia, pela manhã, fiz o que me tinha sido ordenado.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 24), 19, 'Então me disse o povo; Por que nos não explicas o que significam estas coisas que fazes?'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 24), 20, 'Respondi; Foi-me dirigida a palavra do Senhor, nestes termos;'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 24), 21, 'Fala à casa de Israel: Isto diz o Senhor Deus: Eis que vou profanar o meu santuário, orgulho da vossa força, delícias dos vossos olhos, amor das vossas almas. Os vossos filhos e as vossas filhas que deixastes, cairão aos golpes da espada.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 24), 22, 'E vós fareis como eu fiz; não cobrireis o rosto (com véu) nem comereis do pão que se dá aos que estão de luto; (ver nota)'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 24), 23, 'tereis os vossos turbantes nas vossas cabeças, e calçado nos pés; não vos lamentareis, não chorareis, mas consumir-vos-eis nas vossas iniquidades e gemereis uns dom os outros.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 24), 24, 'Ezequiel será para vós um sinal; tudo o que ele fez (na morte de sua esposa), fá-lo-eis vós igualmente, quando estas coisas acontecerem, e sabereis que eu sou o Senhor Deus.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 24), 25, 'E tu, filho de homem, no dia em que eu tirar deles a sua fortaleza, a sua glória e a sua alegria, as delícias de seus olhos, o desejo das suas almas, a saber, seus filhos e suas filhas.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 24), 26, 'Nesse dia, quando vier ter contigo algum que escapar, para te dar novas,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 24), 27, 'nesse dia, digo, abrir-se-á a tua boca para falares com o fugitivo; falarás e não ficarás mais em silêncio e serás para eles um sinal (ou vatícinio), e, assim, saberão que eu sou o Senhor.');
INSERT INTO bible_chapters (book_id, chapter_number, total_verses)
INSERT INTO bible_verses (chapter_id, verse_number, text) VALUES
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 25), 1, 'Foi-me dirigida a palavra do Senhor, nestes termos;'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 25), 2, 'Filho de homem, volta o teu rosto contra os filhos de Amon e profetiza contra eles.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 25), 3, 'Dirás aos filhos de Amon: Ouvi a palavra do Senhor Deus: Isto diz o Senhor Deus: Porque disseste: É bem feito, é bem feito! sobre o meu santuário, por ter sido profanado, e sobre a terra de Israel, porque foi desolada, e sobre a casa de Judá, porque foi levada para o cativeiro,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 25), 4, 'por isso eu te entregarei como herança aos filhos do oriente, que estabelecerão em ti os seus acampamentos e levantarão as suas tendas, comerão os teus frutos e beberão o teu leite.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 25), 5, 'Reduzirei Rabat a pastagem de camelos, e (o país) dos filhos de Amon a redil de ovelhas. Assim sabereis que eu sou o Senhor.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 25), 6, 'Isto diz o Senhor Deus; Porque bateste palmas e saltaste de gozo, porque sentiste uma alegria desdenhosa pela (infelicidade da) terra de Israel,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 25), 7, 'eis que vou estender sobre ti a minha mão, entregar-te ao saque das gentes, apagar-te do número dos povos, exterminar-te de entre as terras, aniquilar-te. Assim saberás que eu sou o Senhor.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 25), 8, 'Isto diz O Senhor Deus; Porque Moab e Seir disseram: A casa de Judá é como todas as outras nações (nenhum privilégio tem)'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 25), 9, 'por isso eis que vou abrir o flanco de Moab, tirando-lhe as cidades, todas as suas cidades, desde as fronteiras, as mais formosas do pais, Betiesimot, Beelmeon e Cariataim.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 25), 10, 'Darei a posse disso, assim como da terra dos Amonitas, aos filhos do oriente, a fim de que não haja mais memória dos filhos de Amon entre as nações.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 25), 11, 'Sobre Moab exercerei assim os meus juízos, e eles saberão que eu sou o Senhor.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 25), 12, 'Isto diz o Senhor Deus: Porque a Idumeia exerceu vingança contra a casa de Judá, e pecou (por isso) por se vingar,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 25), 13, 'por tal motivo, assim fala o Senhor Deus: Estenderei a minha mão contra a Idumeia, tirar-lhe-ei os homens e os animais, e farei dela um deserto; desde Temau até Dedan cairão mortos à espada.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 25), 14, 'Exercerei a minha vingança sobre a Idumeia, pela mão do meu povo de Israel, que tratará Edom segundo a minha ira e o meu furor, e (os Idumeus) reconhecerão a minha vingança, diz o Senhor Deus.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 25), 15, 'Assim fala o Senhor Deus: Porque os Filisteus se entregaram à vingança, se vingaram com profundo desprezo, matando com o (seu) ódio eterno,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 25), 16, 'por esse motivo, isto diz o Senhor Deus: Vou estender a minha mão contra os Filisteus, matarei os Cretenses e exterminarei o que resta na costa do mar. (ver nota)'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 25), 17, 'Tomarei deles terríveis vinganças, castigando-os furiosamente. Saberão que sou o Senhor, quando tiver exercido a minha vingança sobre eles.');
INSERT INTO bible_chapters (book_id, chapter_number, total_verses)
INSERT INTO bible_verses (chapter_id, verse_number, text) VALUES
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 26), 1, 'No ano undécimo (do cativeiro), no primeiro do mês foi-me dirigida a palavra do Senhor, nestes termos:'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 26), 2, 'Filho de homem, porque Tiro disse de Jerusalém: É bem feito! Foi quebrada a porta dos povos! Volta-se para mim! Vou-me encher (com os despojos) dela que ficou devastada!'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 26), 3, 'por isso assim fala o Senhor Deus: Eis que vou contra ti, ó Tiro! Farei subir contra a ti muitas nações, como o mar faz subir as suas ondas quando se encrespa.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 26), 4, 'Elas destruirão os muros de Tiro e deitarão abaixo suas torres, Até o pó varrerei dela, torná-la-ei como uma pedra lisa.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 26), 5, 'Virá a ser no meio do mar como um enxugadouro das redes sou eu que o declaro, diz o Senhor Deus será presa das nações.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 26), 6, 'As suas filhas, que estão no campo, serão também passadas ao fio da espada. E saber-se-á que eu sou o Senhor.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 26), 7, 'Eis o que diz o Senhor Deus: Vou fazer vir, das partes do setentrião contra Tiro, a Nabucodonosor, rei de Babilônia, rei dos reis, com cavalos, carros, cavalaria e grande multidão de tropa.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 26), 8, 'Ele fará cair a golpes da espada as tuas filhas, que estão no campo, por-te-á cerco, erguerá plataformas, levantará o escuro contra ti.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 26), 9, 'Disporá contra os teus muros os seus aríetes e destruirá as tuas torres com as suas máquinas de guerra.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 26), 10, 'A multidão dos seus cavalos te cobrirá de pó; ao estrondo da sua cavalaria, das rodas e dos carros, tremerão as tuas muralhas, quando ele entrar pelas tuas portas, como quem entra numa cidade destruída.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 26), 11, 'Com os cascos dos seus cavalos pisará todas as tuas ruas; passará o teu povo à espada, e cairão por terra as tuas imponentes estátuas.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 26), 12, 'Saquearão todas as tuas riquezas, pilharão as tuas mercadorias, demolirão as tuas muralhas, destruirão as tuas magníficas casas e lançarão ao meio das águas as tuas pedras, as tuas madeiras e o teu pó.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 26), 13, 'Farei cessar o ruído dos teus cantares, e não se ouvirá mais em ti o som das tuas citaras.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 26), 14, 'Tornar-te-ei como uma pedra nua, virás a ser um enxugadouro de redes, e não tomarás a ser edificada sou eu que o declaro, diz o Senhor Deus.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 26), 15, 'Assim fala o Senhor Deus a Tiro: Porventura não tremerão as ilhas ao estrondo da tua ruína, quando gemerem os teus feridos, quando no meio de ti se fizer a carnificina?'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 26), 16, 'Todos os príncipes do mar descerão dos seus tronos e deporão os seus mantos, arrojarão de de si as suas vestes bordadas; revestir-se-ão de terror, sentar-se-ão na terra, e, atônitos com o teu caso, tremerão sem cessar.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 26), 17, 'Fazendo uma lamentação sobre ti, dirão: Como pereceste, tu que habitas no mar, ó cidade célebre, que tens sido poderosa no mar com os teus habitantes, a quem todos temiam!'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 26), 18, 'Agora tremem as ilhas no dia da tua queda, ficam turbadas as ilhas do mar, vendo o teu destino.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 26), 19, 'Eis o que diz o Senhor Deus: Quando te tiver reduzido a uma cidade deserta, como as cidades que não são habitadas, quando tiver feito vir sobre ti o abismo (as ondas do mar), e te tiver coberto um dilúvio do águas,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 26), 20, 'precipitar-te-ei com aqueles que descem ao sepulcro, para te juntar aos mortos antigos, colocar-te-ei no fundo da terra, nas solidões eternas, com os que foram conduzidos ao túmulo, a fim de ficares para sempre desabitada, quando eu tiver ornado de esplendor a terra dos viventes.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 26), 21, 'Tornar-te-ei um objecto de terror, e tu não existirás mais. Ainda que te busquem, nunca mais te acharão, diz o Senhor Deus.');
INSERT INTO bible_chapters (book_id, chapter_number, total_verses)
INSERT INTO bible_verses (chapter_id, verse_number, text) VALUES
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 27), 1, 'Foi-me dirigida a palavra do Senhor, nestes termos:'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 27), 2, 'Tu, filho de homem, faze uma lamentação sobre Tiro,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 27), 3, 'Dize a Tiro, que está sentada à entrada do mar, que faz comércio com povos de numerosas ilhas: Assim fala o Senhor Deus; ó Tiro, tu disseste: Sou duma formosura perfeita (ver nota)'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 27), 4, 'Está o teu império situado no coração do mar. Os que te edificaram, tornaram-te perfeita em formosura.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 27), 5, 'De cipreste de Sanir construíram todo o costado (do teu navio); tomaram um cedro do Líbano para te fazer um mastro; (ver nota)'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 27), 6, 'fizeram de carvalhos de Basan os teus remos; de marfim incrustado em cedro das ilhas de Kittim construíram os teus bancos;'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 27), 7, 'de fino linho do Egipto, bordado, foi tecido o teu velame, que te servia de toldo; de jacinto e de púrpura das ilhas de Elisa era formado o teu pavilhão;'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 27), 8, 'os habitantes de Sidónia e de Arada eram teus remadores; os teus sábios, ó Tiro, eram teus pilotos;'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 27), 9, 'os velhos de Gebal, e os mais hábeis de lá, empregavam na reparação do teu material. Todos os navios do mar e os seus marinheiros vinham a ti para o tráfico de mercadorias.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 27), 10, 'Persas, Lídios e Líbios eram guerreiros no teu exército; suspendiam em ti os seus escudos e capacetes, dando-te esplendor.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 27), 11, 'Os filhos de Arvad com o teu exército estavam sobre a cintura das tuas muralhas, e os de Gammad nas tuas torres; penduravam os seus escudos à roda dos teus muros e completavam a tua formosura.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 27), 12, 'Tarsis fazia tráfico contigo de toda a casta de riquezas, pagando-se mercadorias com prata, ferro, estanho e chumbo.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 27), 13, 'Javan, Tubal e Mosoc também negociavam contigo, trazendo ao teu povo escravos e artefactos de cobre.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 27), 14, 'Os de Togorma traziam ao teu mercado cavalos de tiro, corcéis e machos.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 27), 15, 'Os filhos de Dedan negociavam contigo; o teu mercado estendia-se a muitas ilhas; em troca das tuas mercadorias davam-te dentes de marfim e ébano.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 27), 16, 'A Síria negociava contigo, por causa da multidão dos teus produtos; expunha à venda, nos teus mercados, carbúnculos, púrpura, estofos bordados, linho fino, corais e rubis.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 27), 17, 'Judá e a terra de Israel negociavam contigo, levando aos teus mercados trigo de Minnith, cera, mel, azeite e bálsamo.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 27), 18, 'Damasco traficava contigo pela abundante variedade dos teus gêneros, pela multidão de riquezas várias, trazendo-te vinho de Helbon e lã de Sahar.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 27), 19, 'Dan, Javan e Uzal, em troca dos teus produtos, traziam aos teus mercados ferro forjado, cássia e cana aromática.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 27), 20, 'Os de Dedam traficavam contigo em gualdrapas de cavalgaduras.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 27), 21, 'A Arábia e todos os príncipes de Cedar compravam as tuas mercadorias, dando-te em troca cordeiros, carneiros e bodes.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 27), 22, 'Os mercadores de Sabá e de Reema comerciavam também contigo, pagando-te com os melhores aromas, pedras preciosas e ouro.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 27), 23, 'Haran, Quene e Eden negociavam igualmente contigo, assim como os mercadores de Sabá, Assur e Quelmad.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 27), 24, 'Faziam comércio de diversos produtos de luxo: mantos de púrpura ou bordados, tecidos matizados, fortes cordas entrançadas, tudo posto nos teus mercados.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 27), 25, 'Os navios de Tarsis serviam no teu comércio. Foste cheia de bens e de glória no coração do mar.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 27), 26, 'Os teus remadores conduziram-te sobre grandes águas, (porém) o vento do oriente quebrou-te no coração do mar.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 27), 27, 'As tuas riquezas, os teus produtos, as tuas mercadorias, os teus marinheiros e os teus pilotos, os tens calafates, os encarregados do teu comércio, os guerreiros que estavam contigo, e toda a multidão do povo que estava no meio de ti, cairão todos no fundo do mar, no dia da tua ruína.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 27), 28, 'Ao estrondo da gritaria dos teus pilotos se turbarão as praias;'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 27), 29, 'todos os remadores descerão dos seus navios; os marinheiros e todos os pilotos do mar ficarão em terra;'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 27), 30, 'farão sobre ti um grande pranto em altas vozes, gritarão com amargura, deitarão pó sobre a sua cabeça, rolarão na cinza,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 27), 31, 'raparão por tua causa os cabelos, vestindo-se de cilícios, e, na amargura do seu coração, derramarão lágrimas sobre ti, pranto amargosíssimo.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 27), 32, 'Entoarão sobre ti cânticos lúgubres, chorarão a tua desgraça, dizendo: Que cidade há como Tiro, que emudeceu no meio do mar?'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 27), 33, 'Quando desembarcavas mercadorias dos mares, enriquecias muitos povos; pela multidão das tuas riquezas e do teu tráfico, enriquecias os reis da terra.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 27), 34, 'Agora, que foste quebrada pelo mar, sumida no fundo das águas, as tuas mercadorias e toda a gente, que vivia no meio de ti, sossobraram contigo.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 27), 35, 'Todos os habitantes das ilhas estão cheios de espanto pelo teu caso; os seus reis, tomados de pânico ficaram com o aspecto alterado.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 27), 36, 'Os negociantes dos povos assobiam-te (escarnecendo); tornaste-te um objecto de pavor, foste reduzida a nada, para sempre.');
INSERT INTO bible_chapters (book_id, chapter_number, total_verses)
INSERT INTO bible_verses (chapter_id, verse_number, text) VALUES
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 28), 1, 'Foi-me dirigida a palavra do Senhor, nestes termos;'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 28), 2, 'Filho de homem, dize ao príncipe de Tiro: Assim fala o Senhor Deus: O teu coração elevou-se, tu disseste: Eu sou um deus, estou sentado sobre a cadeira divina, no meio do mar. Sendo um homem, e não um deus, consideraste o teu coração como o coração de um deus.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 28), 3, 'És mais sábio que Daniel, nenhum segredo há oculto para ti;'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 28), 4, 'pela tua sabedoria e pela tua inteligência, adquiriste riquezas, juntaste ouro e prata nos teus tesouros;'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 28), 5, 'pela extensão da tua sabedoria no teu comércio, aumentaste a tua fortuna, e, por isso, o teu coração se orgulhou.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 28), 6, 'Portanto isto diz o Senhor Deus: Porque o teu coração se elevou, como se fosse o coração dum deus,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 28), 7, 'por isso, vou fazer vir contra ti estrangeiros, os mais bárbaros de entre os povos; desembainharão a espada contra o brilho da tua sabedoria e mancharão o teu esplendor.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 28), 8, 'Precipitar-te-ão na fossa, e morrerás da morte daqueles que são mortos no seio dos mares.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 28), 9, 'Porventura dirás ainda: Eu sou um deus diante dos teus executores? Mas (afinal) és um homem, nas mãos dos que te matam, e não um deus.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 28), 10, 'Morrerás da morte dos incircuncidados, à mão de estrangeiros. Eu o disse oráculo do Senhor Deus. (ver nota)'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 28), 11, 'Foi-me dirigida a palavra do Senhor, nestes termos: Filho de homem, entoa uma lamentação sobre o rei de Tiro.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 28), 12, 'Dir-lhe-ás; Assim fala o Senhor Deus: Tu eras um modelo de perfeição, cheio de sabedoria e perfeito na beleza;'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 28), 13, 'vivias no Eden, jardim de Deus; a tua veste estava ornada de toda a casta de pedras preciosas; sárdio, topázio, diamante, crisólito, ónix jaspe, safira, carbúnculo, esmeralda e ouro, tudo foi empregado em realçar a tua formosura; os teus instrumentos músicos foram preparados no dia em que foste criado.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 28), 14, 'Eras um querubim protector que estendia, as suas asas, colocado sobre o monte santo de Deus; tu caminhavas no meio de pedras (brilhantes) de fogo.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 28), 15, 'Foste perfeito nos teus caminhos desde o dia da tua criação, até que a iniquidade se achou em ti.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 28), 16, 'Com a actividade do teu comércio encheu-se o teu interior de iniquidade, caíste no pecado, e eu lancei-te fora do monte de Deus, exterminei-te, ó querubim protector, do meio das pedras (brilhantes) de fogo.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 28), 17, 'O teu coração se elevou por causa da tua beleza; perdeste a tua sabedoria por causa do teu brilho; por isso te lancei por terra e te expus diante da face dos reis, para que eles te contemplassem.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 28), 18, 'Profanaste os teus santuários com a multidão das tuas iniquidades, com as injustiças do teu comércio; fiz, por isso, sair do meio de ti um fogo, para te devorar, e reduzir-te a cinzas sobre a terra, aos olhos de todos os que te viam.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 28), 19, 'Todos os que te conheciam entre as nações, ficaram espantados de ti. Tornaste-te. um objecto de espanto, e deixaste de existir, para sempre.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 28), 20, 'Foi-me dirigida a palavra do Senhor, nestes termos:'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 28), 21, 'Filho de homem, volta o teu rosto para Sidónia e profetiza sobre ela.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 28), 22, 'Dirás: Assim fala o Senhor Deus: Eis que venho contra ti, ó Sidónia. Vou ser glorificado no meio de ti. Saber-se-á que eu sou o Senhor, quando tiver exercido os meus juízos contra ela, e nela tiver feito resplandecer a minha santidade.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 28), 23, 'Enviarei contra ela a peste, inundarei de sangue as suas ruas; cairão no meio dela mortos à espada, levantada de todos os lados, e assim se saberá que eu sou o Senhor.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 28), 24, 'Desde então, não haverá mais, para a casa de Israel, espinho dilacerante ou acúleo pungente, da parte de qualquer dos seus vizinhos que a desprezam, e saber-se-á que eu sou o Senhor Deus.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 28), 25, 'Isto diz o Senhor Deus: Quando eu juntar a casa de Israel de entre os povos, pelos quais têm andado dispersos, mostrarei, por isso, a minha santidade aos olhos das gentes. (Os Israelitas) habitarão na terra, que dei a meu servo Jacob.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 28), 26, 'Habitarão nela com segurança, edificarão casas, plantarão vinhas, viverão em segurança. Quando tiver executado os meus juízos saber-se-á que sou o Senhor seu Deus.');
INSERT INTO bible_chapters (book_id, chapter_number, total_verses)
INSERT INTO bible_verses (chapter_id, verse_number, text) VALUES
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 29), 1, 'No ano décimo, no décimo mês, aos doze dias do mês, foi-me dirigida a palavra do Senhor, nestes termos: Filho de homem, volta o teu rosto contra Faraó, rei do Egipto, e profetiza contra ele e contra o Egipto.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 29), 3, 'Fala e dize: Isto diz o Senhor Deus; Eis que venho contra ti, ó Faraó, rei do Egipto, crocodilo enorme, que te deitas no meio dos teus rios e que dizes: O rio (Nilo), é meu, fui eu que o fiz.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 29), 4, 'Pôr-te-ei um freio nos queixos, colarei os peixes dos teus rios às tuas escamas, e te tirarei do meio dos teus rios, assim como todos os peixes dos teus rios, pegados às tuas escamas.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 29), 5, 'Lançar-te-ei para o deserto com todos os peixes do teu rio; cairás sobre a face da terra, e não te recolherão nem sepultarão; dar-te-ei por pasto aos animais da terra e às aves do céu.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 29), 6, 'e todos os habitantes do Egipto saberão que eu sou o Senhor, porque tu foste para a casa de Israel um apoio (frágil) de cana. (ver nota)'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 29), 7, 'Quando eles te tomaram na mão, quebraste, e lhes rasgaste todo o ombro; quando eles se apoiaram sobre ti, tu te partiste em pedaços e fizeste vacilar todos os seus rins.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 29), 8, 'Portanto isto diz o Senhor Deus: Vou fazer cair a espada sobre ti e exterminar do teu seio os homens e os animais.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 29), 9, 'A terra do Egipto será reduzida a um deserto e a uma solidão, e saber-se-á que eu sou o Senhor. Porque tu disseste; O rio é meu, eu é que o fiz'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 29), 10, 'por isso, eis-me aqui contra ti e contra os teus rios; transformarei a terra do Egipto num deserto e numa solidão, desde Mígdol até Siene, até aos confins da Etiópia.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 29), 11, 'Não passará por ela pé de homem, nem andará nela pé de animal; não será habitada durante quarenta anos.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 29), 12, 'Farei do país do Egipto um deserto, no meio de outros países desertos, e as suas cidades ficarão destruídas no meio de outras cidades destruídas, estarão desoladas durante quarenta anos; espalharei por diversas nações os Egípcios, disseminá-los-ei por várias terras.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 29), 13, 'Porque isto diz o Senhor Deus: Ao fim de quarenta anos, juntarei os Egípcios do meio dos povos, entre os quais tinham sido espalhados;'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 29), 14, 'tornarei a trazer os cativos do Egipto e estabelecê-los-ei na terra de Patros, na terra da sua nascença, onde formarão um reino humilde. (ver nota)'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 29), 15, '(O Egipto) será o mais humilde de todos os reinos, e não se tornará mais a levantar sobre as outras nações; diminui-los-ei, para que não dominem sobre elas.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 29), 16, 'Não serão mais motivo de confiança para a casa de Israel, recordarão a falta cometida por Israel em os seguir, e saber-se-á que eu sou o Senhor Deus.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 29), 17, 'No ano vinte e sete, no primeiro dia do primeiro mês, foi-me dirigida a palavra do Senhor, nestes termos;'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 29), 18, 'Filho de homem, Nabucodonosor, rei de Babilónia, fatigou muito o seu exército na guerra contra Tiro: todas as cabeças ficaram calvas, e todos os ombros maltratados. Contudo, nem a ele, nem ao seu exército foi dada recompensa alguma pelo serviço realizado contra Tiro.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 29), 19, 'Portanto isto diz o Senhor Deus; Vou dar a Nabucodonosor, rei de Babilônia, o país do Egipto: levará as suas riquezas, fará dele a sua presa, repartirá os seus despojos: esta será a recompensa do seu exército.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 29), 20, 'Pelo serviço que prestou contra Tiro, dou-lhe o país do Egipto, porque ele trabalhou para mim, diz o Senhor Deus.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 29), 21, 'Nesse dia farei brotar um chifre (ou poderio) à casa de Israel, e abrir-te-ei a boca no meio deles. E saberão que eu sou o Senhor.');
INSERT INTO bible_chapters (book_id, chapter_number, total_verses)
INSERT INTO bible_verses (chapter_id, verse_number, text) VALUES
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 30), 1, 'Foi-me dirigida a palavra do Senhor nestes termos:'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 30), 2, 'Filho de homem profetiza o seguinte: Isto diz o Senhor Deus: Soltai lamentos (ó Egípcios, dizendo): Ai! Que dia!'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 30), 3, 'Porque o dia está perto, aproxima-se o dia do Senhor: dia de nuvens, tempo (do castigo) das nações!'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 30), 4, 'espada (inimiga) virá contra o Egipto: o pavor se apossará da Etiópia, quando caírem os mortos no Egipto, quando forem arrebatadas as suas riquezas, destruídos os seus fundamentos.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 30), 5, 'Etíopes, Líbios, Lídios, e todos os outros povos, e Cub, e os filhos da minha aliança, cairão com eles ao fio da espada. (ver nota)'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 30), 6, 'Isto diz o Senhor Deus: Os que sustinham o Egipto, cairão, e a soberba da sua força será destruída: cairão aos golpes da espada, desde Migdol até Siene, diz o Senhor dos exércitos.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 30), 7, '(Aquelas regiões) serão assoladas, entre terras assoladas, e as suas cidades (devastadas) entre as cidades devastadas.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 30), 8, 'Saberão que eu sou o Senhor, quando eu tiver posto fogo ao Egipto, e forem derrotados todos os seus auxlliares.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 30), 9, 'Naquele dia partirão em navios mensageiros despachados por mim para perturbar a Etiópia na sua segurança, e haverá terror nela no dia (do castigo) do Egipto, dia que já está a chegar.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 30), 10, 'Isto diz o Senhor Deus: Destruirei a multidão do Egipto pela mão de Nabucodonosor, rei de Babilônia.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 30), 11, 'Ele e o seu povo com ele, o mais bárbaro dos povos, serão levados para assolar a terra: desembainharão a sua espada contra o Egipto e encherão o país de mortos.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 30), 12, 'Secarei o leito dos rios, entregarei o país nas mãos dos celerados, destruirei esta terra, e tudo o que ela contém, pela mão dos estrangeiros. Sou eu o Senhor, que o digo.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 30), 13, 'Isto diz o Senhor: Destruirei os ídolos, aniquilarei os falsos deuses de Mênfis. Não tornará mais a haver príncipe na terra do Egipto. Espalharei o terror pela terra do Egipto.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 30), 14, 'Arruinarei Patros, porei fogo a Soan (Tanis), exercerei os meus juízos em Nô (Tébas).'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 30), 15, 'Derramarei a minha indignação sobre Sin, baluarte do Egipto, e farei morrer a multidão de Nô.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 30), 16, 'Porei fogo ao Egipto. Sin sentirá dores angustiantes. Nô será destruída, e Mênfis assaltada em pleno dia.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 30), 17, 'Os jovens de Hellópolis e de Bubasto cairão ao fio da espada, e a sua população será levada cativa.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 30), 18, 'O dia se fará noite em Tafnis, quando eu quebrar o jugo do Egipto, e acabar nele a arrogância do seu poder. Uma nuvem cobrirá a cidade, e as suas filhas serão levadas para o cativeiro.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 30), 19, 'Exercerei contra o Egipto os meus juízos, e saber-se-á que eu sou o Senhor.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 30), 20, 'No ano undécimo, no primeiro mês, aos sete do mês, foi-me dirigida a palavra do Senhor, nestes termos;'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 30), 21, 'Filho de homem, quebrei o braço de Faraó, rei do Egipto, e eis que não foi pensado por ninguém, para se curar, não foi ligado, para que, tendo recobrado a força, pudesse manejar a espada.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 30), 22, 'Portanto isto diz o Senhor Deus: Eis-me aqui contra Faraó rei do Egipto: vou partir o seu braço válido, como o quebrado, e farei cair a espada da sua mão.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 30), 23, 'Dispersarei os Egípcios entre as nações, disseminá-los-ei por diversas terras.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 30), 24, '(Ao mesmo tempo) fortificarei os braços do rei de Babilônia e meter-lhe-ei a minha espada na mão; quebrarei os braços de Faraó, que soltará, diante dele, gemidos como os dum moribundo.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 30), 25, 'Fortificarei os braços do rei de Babilônia, e os braços de Faraó cairão. Saber-se-á que eu sou o Senhor, quando meter a minha espada na mão do rei de Babilônia, e ele a voltar contra a terra do Egipto.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 30), 26, 'Dispersarei os Egípcios entre as nações e disseminá-los-ei por diversas terras. Assim se saberá que eu sou o Senhor.');
INSERT INTO bible_chapters (book_id, chapter_number, total_verses)
INSERT INTO bible_verses (chapter_id, verse_number, text) VALUES
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 31), 1, 'No ano undécimo, no terceiro mês, no primeiro do mês, foi-me dirigida a palavra do Senhor, nestes termos:'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 31), 2, 'Filho de homem, dize a Faraó, rei do Egipto, e ao seu numeroso povo: A quem te assemelhas na tua grandeza? (ver nota)'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 31), 3, '(Assemelhas-te a) um cedro sobre o Líbano, de formosos ramos e espessa folhagem, de elevado tronco, erguendo até às nuvens o alto da sua copa.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 31), 4, 'As águas fizeram-no crescer, o abismo levantar-se muito alto, fazendo correr seus rios em torno do lugar onde estava plantado, passar os seus regatos por todas as árvores dos campos.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 31), 5, 'Por isso ultrapassou em altura todas as árvores dos campos, multiplicaram-se os seus braços, estenderam-se os seus ramos, por causa das águas abundantes enviadas.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 31), 6, 'Todas as aves do céu fizeram os ninhos sobre os seus ramos, todos os animais dos bosques criaram debaixo da sua copa, e ura grande número de nações habitava debaixo da sua sombra.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 31), 7, 'Era formoso pela sua grandeza e pela extensão dos seus braços, porque as suas raízes mergulharam em águas abundantes.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 31), 8, 'No jardim de Deus não havia cedros tão altos como ele; os ciprestes não se podiam comparar aos seus braços, nem os plátanos aos seus ramos; nenhuma árvore do jardim de Deus o igualava em formosura.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 31), 9, 'Eu tinha-o feito belo pela frondosidade dos seus ramos, de modo que tiveram dele emulação todas as árvores que havia no Eden, jardim de Deus.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 31), 10, 'Por essa causa isto diz o Senhor Deus: Visto que, sendo de elevada estatura, até chegar às nuvens com a ponta dos seus ramos, o seu coração se elevou por causa da sua grandeza,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 31), 11, 'eu o entreguei nas mãos do mais forte das gentes, que o tratará como a sua impiedade o merecer, que o destruirá.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 31), 12, 'Estrangeiros, os mais cruéis de todos os povos, cortaram-no pelo pé e lançaram-no sobre os montes; os seus ramos caíram por todos os vales, e os seus braços partidos jazem por todas as quebradas da terra; toda a gente da terra se retirou de debaixo da sua sombra e o abandonou.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 31), 13, 'Todas as aves do céu habitaram nas suas ruínas e todos os animais da terra se acolheram debaixo dos seus ramos.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 31), 14, 'Por isso nenhuma árvore plantada junto das águas se orgulhe da sua altura, nem eleve até às nuvens o alto da sua copa, nenhuma árvore de regadio confie na sua elevação. Porque todos foram entregues à morte, lançados no fundo da terra no meio dos filhos dos homens, entre aqueles que descem à fossa.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 31), 15, 'Isto diz o Senhor Deus: No dia em que ele desceu à morada dos mortos, ordenei luto; cobri o abismo, detive os seus rios, e pararam as águas abundantes; entristeci o Líbano por causa dele, e por causa dele todas as árvores do campo definharam.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 31), 16, 'Fiz estremecer as nações com o estrondo da sua ruína, quando o conduzi à habitação dos mortos com os que descem à fossa. Consolaram-se no fundo dá terra todas as árvores do Eden, as mais belas e as melhores do Líbano, todas as que eram regadas com as águas. (ver nota)'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 31), 17, 'Também desceram com ele à habitação dos mortos, para junto dos que pereceram ao fio da espada, aqueles que, sendo o braço (do rei), estavam debaixo da sua sombra entre as nações.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 31), 18, 'A quem eras semelhante (ó Faraó), em glória e grandeza entre as árvores do Eden? Com as árvores do Eden foste precipitado no fundo da terra; jazes no meio dos incircuncidados, com os que foram mortos á espada. Eis o (destino de), Faraó e seu numeroso povo, diz o Senhor Deus.');
INSERT INTO bible_chapters (book_id, chapter_number, total_verses)
INSERT INTO bible_verses (chapter_id, verse_number, text) VALUES
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 32), 1, 'No ano duodécimo, no primeiro dia do mês duodécimo, foi-me dirigida a palavra do Senhor, nestes termos:'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 32), 2, 'Filho de homem, entoa uma lamentação sobre Faraó, rei do Egipto. Dirás; Leão das gentes, pereceste! Eras como o crocodilo que está nos mares; atiravas-te pelos rios, turbavas as águas com as tuas patas, agitavas as suas correntes.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 32), 3, 'Por cuja causa, isto diz o Senhor Deus: Estenderei sobre ti a minha rede, por meio duma multidão imensa de povos, e tirar-te-ão para fora na minha rede.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 32), 4, 'Arrojar-te-ei à terra, lançar-te-ei sobre o campo, farei pousar sobre ti todas as aves do céu, fartarei em ti todos os animais da terra.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 32), 5, 'Lançarei as tuas carnes sobre os montes, encherei os vales dos teus destroços.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 32), 6, 'Regarei a terra das montanhas com o que escorrer de ti, com o teu sangue, e as que bradas ficarão cheias (do que tiver saldo) de ti.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 32), 7, 'Velarei os céus, quando fores morto, farei enegrecer as suas estrelas; encobrirei o sol de nuvens, e a lua não dará a sua luz.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 32), 8, 'Farei que todos os luzeiros do céu se vistam de luto, por ti, e espalharei as trevas sobre a tua terra, diz o Senhor Deus.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 32), 9, 'Encherei de dor o coração de muitos povos, quando espalhar os teus cativos por entre as nações, por países que não conheces.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 32), 10, 'Farei com que muitos povos fiquem atônitos, pelo teu caso, e com que os seus reis tremam por causa de ti, possuídos de terror, quando agitar a minha espada diante da sua face. Cada um incessantemente tremerá pela sua própria vida, no dia da tua ruína.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 32), 11, 'Eis o que diz o Senhor Deus; A espada do rei de Babilônia virá sobre ti.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 32), 12, 'Com a espada dos fortes (Caldeus) desfarei a tua multidão. São os mais bárbaros de todos os povos. Destruirão a soberba do Egipto, e toda a sua multidão será dissipada.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 32), 13, 'Farei perecer todos os seus animais (que pastam) junto de abundantes águas; não as turvará mais pé de homem, nem casco de animais.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 32), 14, 'Então farei repousar as suas águas, correr os seus rios como o azeite, diz o Senhor Deus. (ver nota)'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 32), 15, 'Quando eu tiver desolado a terra do Egipto, quando todo o país estiver despojado dos bens que contém, quando tiver ferido todos os seus habitantes, saberão que sou o Senhor.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 32), 16, 'Esta é a lamentação que hão-de entoar as filhas das nações; entoá-la-ão sobre o Egipto e sobre a sua multidão, diz o Senhor Deus. (ver nota)'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 32), 17, 'No ano duodécimo, aos quinze do mês, foi-me dirigida a palavra do Senhor, nestes termos:'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 32), 18, 'Filho de homem, entoa um cântico lúgubre sobre o povo do Egipto: (vaticinando) precipita-o a ele e ás filhas das nações fortes, no fundo da terra com aqueles que descem à fossa. (ver nota)'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 32), 19, 'A quem excedes em beleza? Desce e deita-te com os incircuncidados.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 32), 20, 'Cairão no meio daqueles que foram mortos à espada—foi dada a espada (por Deus nos Caldeus). Levaram após si o Egipto e todos os seus povos.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 32), 21, 'Do meio da habitação dos mortos lhes dirão os mais poderosos dentre os fortes, a ele e aos seus auxiliares: Desceram e jazem, passados ao fio da espada, os incircuncidados.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 32), 22, 'Ali está Assur, e toda a sua multidão de povo; os seus sepulcros estão ao redor dele; todos foram mortos, caíram a golpes de espada.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 32), 23, 'Os seus sepulcros foram postos no mais profundo da fossa; todo o seu povo jaz ao redor do seu sepulcro; todos foram mortos, abatidos à espada, eles que tinham espalhado o terror na terra dos vivos.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 32), 24, 'Ali está Elam, e todo o seu povo ao redor do seu sepulcro; todos foram mortos, passados ao fio da espada, e desceram incircuncidados às profundezas da terra. Eles, que (antes) foram o terror de todos na terra dos vivos, levam sobre si a própria ignomínia com os que descem à fossa.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 32), 25, 'No meio dos que foram mortos foi colocado o leito para ele, e para todos os seus povos, ao redor dele: os seus sepulcros estão ao redor dele. Todos estes incircuncidados foram passados ao fio da, espada, porque espalharam o terror na terra dos vivos: levaram sobre si a ignomínia com os que descem à cova, foram postos no meio dos que tinham sido mortos.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 32), 26, 'Ali se acham Mosoc e Tubal, e todo o seu povo; os seus sepulcros estão ao redor dele; todos estes incircuncidados foram mortos à espada, porque espalharam o terror na terra dos vivos.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 32), 27, 'Não jazerão com os heróis de outrora, com esses que baixaram à habitação dos mortos (adornados) com suas armas, debaixo de cujas cabeças foram colocadas as suas espadas, debaixo de cujos ossos foram postos os seus escudos, visto que se espalhou o seu terror na terra dos vivos.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 32), 28, 'No meio dos incircuncidados é que jazerás, entre os que foram passados ao fio da espada.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 32), 29, 'Ali está a Idumeia, e os seus reis, e todos os seus príncipes que, apesar da sua bravura, foram postos entre os mortos à espada, jazendo (assim) com os incircuncidados, com os que descem à fossa.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 32), 30, 'Ali estão todos os príncipes do aquilão, todos os Sidõnios, descidos com os que foram mortos, apesar da sua tremenda valentia. Jazem incircuncidados, com os que tinham perecido a golpes dia espada, e levam sobre si a sua confusão com os que descem à fossa.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 32), 31, 'Faraó os verá e consolar-se-á, à vista de toda esta multidão que foi morta ao fio da espada. Faraó e todo o seu exército, diz o Senhor Deus.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 32), 32, 'Porque tinha espalhado o terror sobre a terra dos vivos, ei-lo que jaz no meio dos incircuncidados, com os que tinham sido mortos pela espada. Faraó e todo o seu povo, diz o Senhor Deus.');
INSERT INTO bible_chapters (book_id, chapter_number, total_verses)
INSERT INTO bible_verses (chapter_id, verse_number, text) VALUES
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 33), 1, 'Foi-me dirigida a palavra do Senhor nestes termos:'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 33), 2, 'Filho de homem, fala aos filhos do teu povo. Dir-lhes-ás; Quando eu fizer cair a espada sobre um país, se o povo desse país tomar um homem do seu seio e o constituir sentinela para vigiar sobre eles,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 33), 3, 'e esta sentinela, vendo vir a espada sobre o pais, tocar a trombeta e avisar disto o povo,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 33), 4, 'se aquele, que ouvir o som da trombeta, não tomar em conta o aviso, de forma que sobrevenha a espada e o mate, o seu sangue cairá sobre a sua cabeça:'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 33), 5, '(porque) ouviu o som da trombeta e não tomou em conta o aviso, o seu sangue cairá sobre a sua cabeça. Quanto ao que tomou em conta o aviso, esse salvará a sua vida.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 33), 6, 'Mas, se a sentinela vir que vem a espada e não tocar a trombeta, de forma que o povo não seja avisado, se vier a espada e tirar a vida a um deles, este tal perecerá devido à sua iniquidade, mas eu pedirei contas do seu sangue à sentinela.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 33), 7, 'Ora tu, filho de homem, és aquele a quem constituí sentinela na casa de Israel; tu, pois, ouvindo as palavras da minha boca lhas anunciarás a eles, da minha parte.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 33), 8, 'Se, dizendo eu ao ímpio: ímpio, com certeza morrerás tu não falares ao ímpio, para ele se afastar do seu (mau) caminho, morrerá esse ímpio na sua iniquidade, mas eu pedir-te-ei contas do seu sangue.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 33), 9, 'Porém se, admoestando tu o ímpio para que se converta dos seus caminhos, ele se não converter, morrerá na sua iniquidade, e tu terás salva a tua vida.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 33), 10, 'Filho de homem, dize à casa de Israel: Costumais dizer isto: As nossas iniquidades e os nossos pecados estão sobre nós, e por causa deles nos vamos consumindo; como poderemos nós, pois, (ainda) viver?'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 33), 11, 'Dize-lhes: (Juro) pela minha vida, diz o Senhor Deus, que não quero a morte do ímpio, mas sim que se converta do seu mau proceder e viva. Convertei-vos, convertei-vos dos vossos maus caminhos! Por que haveis de morrer, ó (vós da) casa de Israel?'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 33), 12, 'Filho de homem, dize aos filhos do teu povo: Em qualquer dia em que o justo pecar, a sua justiça não o livrará; da mesma forma, em qualquer dia em que o ímpio se converter da sua impiedade, a impiedade, não lhe fará mal. (Sem dúvida) em qualquer dia em que o justo venha a pecar, não poderá viver da sua justiça.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 33), 13, 'Ainda quando eu disser ao justo que terá vida, se ele, confiado na sua justiça, cometer a iniquidade, todas as suas obras de justiça serão postas no esquecimento e ele morrerá na iniquidade que cometeu.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 33), 14, 'Se, por outro lado, eu tiver dito ao ímpio: Tu certamente morrerás e ele se desviar do seu pecado e praticar obras rectas e justas,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 33), 15, 'se restituir o penhor que lhe foi confiado, se tornar ao dono o que roubou, se andar nos mandamentos da vida e não fizer nada de injusto, viverá certamente, não morrerá.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 33), 16, 'Nenhum dos pecados que cometeu lhe será imputado; praticou o que era recto e justo, e assim certamente viverá.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 33), 17, 'Entretanto, os filhos do teu povo dizem; O caminho do Senhor não é justo. (Ora, não). O caminho deles é que é injusto.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 33), 18, 'Quando o justo se apartar da sua justiça e cometer obras de iniquidade, encontrará nela a morte.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 33), 19, 'Pelo contrário, quando o ímpio deixar a sua impiedade e praticar obras de rectidão e justiça, encontrará nelas a vida.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 33), 20, 'Ainda assim vós dizeis: O caminho do Senhor não á recto! Ó casa de Israel, eu hei-de julgar cada um de vós segundo as suas obras.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 33), 21, 'No ano duodécimo da nossa transmigração, no décimo mês, aos cinco do mês, um homem, que tinha fugido de Jerusalém, veio ter comigo e disse: A cidade foi tomada.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 33), 22, 'Ora a mão do Senhor tinha-se-me dado a sentir na tarde anterior à chegada do fugitivo, e o Senhor tinha-me abrido a boca antes que esse homem viesse ter comigo pela manhã. Tendo-me sido aberta a boca, não fiquei mais em silêncio.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 33), 23, 'Foi-me dirigida a palavra do Senhor, nestes termos:'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 33), 24, 'Filho de homem, os que habitam entre essas ruínas da terra de Israel, falam assim: Abraão era sozinho, quando possuíu esta terra por herança; a nós, que somos muitos, a nós é que foi dada esta terra para a usufruirmos.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 33), 25, 'Responde-lhes, pois: Assim fala o Senhor Deus: Vós que comeis (a carne com) sangue, levantais os olhos para os vossos ídolos e derramais o sangue (humano), porventura haveis de possuir esta terra?'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 33), 26, 'Apoiais-vos sobre as vossas espadas, cometeis abominações, violais a mulher do vosso próximo, e então haveis de possuir esta terra?'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 33), 27, 'Tu lhes dirás: Assim fala o Senhor Deus: (Juro), pela minha vida, que aqueles que habitam entre as ruínas (de Jerusalém) perecerão á espada; que os que estão nos campos, os entregarei como pasto às feras; que os que se acolheram aos lugares fortes e às cavernas, morrerão de peste.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 33), 28, 'Reduzirei esta terra a uma solidão e a um deserto, e terminará o orgulho da sua fortaleza; os montes de Israel serão desolados, sem que haja pessoa alguma que passe por eles.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 33), 29, 'Então se saberá que sou o Senhor, quando eu tiver reduzido o país a uma solidão e a um deserto, em castigo de todas as abominações que cometeram.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 33), 30, 'Quanto a ti, filho de homem, os filhos do teu povo, que falam de ti junto dos muros e ás portas de suas casas, dizem uns para os outros, cada um falando com o seu vizinho: Vinde, e ouçamos a palavra que saí da boca do Senhor (por meio do profeta).'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 33), 31, 'Vêm ter contigo, em massa, sentam-se diante de ti os do meu povo, ouvem as tuas palavras, mas não as põem em prática. Fazem o que é agradável à sua boca, enquanto o seu coração anda atrás do interesse.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 33), 32, 'Tu para eles és como um cantor delicioso, dotado de bela voz e que toca bem a sua cítara; ouvem as tuas palavras (com gosto), mas não as põem em prática.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 33), 33, 'Mas, quando suceder o que foi predito, (e eis que está a ponto de acontecer) então saberão que houve um profeta entre eles.');
INSERT INTO bible_chapters (book_id, chapter_number, total_verses)
INSERT INTO bible_verses (chapter_id, verse_number, text) VALUES
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 34), 1, 'Foi-me dirigida a palavra do Senhor, nestes termos;'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 34), 2, 'Filho de homem, profetiza acerca dos pastores de Israel; profetiza, dize a esses pastores: Assim fala o Senhor Deus: Ai dos pastores de Israel que se apascentam a si próprios! Porventura não é o rebanho que deve ser apascentado pelos pastores?'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 34), 3, 'Vós bebeis o leite, vestis-vos de lã, matais as reses mais gordas, mas não apascentais o meu rebanho.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 34), 4, 'Não fortalecestes as ovelhas débeis, não curastes as enfermas, não pensastes a ferida, não fizestes voltar a desgarrada não buscastes a perdida, mas exercestes domínio sobre elas com aspereza e com prepotência.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 34), 5, 'Assim as minhas ovelhas se dispersaram, por não terem pastor, tornaram-se a presa de todas as feras do campo, desgarraram-se.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 34), 6, 'O meu rebanho erra por todas as montanhas e por todos os outeiros elevados; o meu rebanho anda disperso por toda a face da terra, sem haver ninguém que tome cuidado dele, sem haver ninguém que o procure.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 34), 7, 'Por isso, ó pastores, ouvi a palavra do Senhor:'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 34), 8, '(Juro) pela minha vida, diz o Senhor Deus: Porque as minhas ovelhas foram entregues à rapina se tornaram o pasto de todas as feras do campo, por falta de pastor; porque os meus pastores não cuidaram do meu rebanho, mas só cuidavam de se apascentar a si mesmos, e não em apascentar as minhas ovelhas,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 34), 9, 'ouvi portanto, ó pastores, a palavra do Senhor:'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 34), 10, 'Isto diz o Senhor Deus: Eu mesmo vou pedir contas a esses pastores das minhas ovelhas; não mais os deixarei apascentar o rebanho, e, assim, não se apascentarão mais a si próprios. Arrancarei as minhas ovelhas da sua boca de modo que não lhes servirão mais de pasto,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 34), 11, 'Eis, pois, o que diz o Senhor Deus: Eu mesmo cuidarei das minhas ovelhas e vigiá-las-ei.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 34), 12, 'Assim como um pastor visita o seu rebanho no dia em que se acha no meio das suas ovelhas (depois que andaram) desgarradas, assim visitarei as minhas ovelhas e as livrarei de todos os lugares por onde tinham andado dispersas no dia de nublado e de escuridão.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 34), 13, 'Tirá-las-ei dentre os povos e juntá-las-ei de diversos países; introduzi-las-ei na sua terra e apascentá-las-ei sobre os montes de Israel, ao longo das ribeiras e em todos os lugares habitáveis do país.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 34), 14, 'Levá-las-ei a pastar nas pastagens férteis; os altos montes de Israel serão o seu acolhedouro: lá repousarão sobre as verdes relvas, terão sobre os montes de Israel abundantes pastagens.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 34), 15, 'Apascentarei, eu próprio, as minhas ovelhas, fá-las-ei repousar, diz o Senhor Deus.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 34), 16, 'Irei procurar a perdida, farei voltar a desgarrada, pensarei a ferida, fortalecerei a fraca, conservarei a gorda e forte, apascentarei com justiça,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 34), 17, 'Quanto a vós, ovelhas minhas, isto diz o Senhor Deus: Eis que vou fazer julgamento (de discriminação) entre ovelhas e ovelhas, vou julgar carneiros e bodes.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 34), 18, 'Porventura não vos bastará ter pastagens excelentes? (Não contentes com isso) calcastes aos pés o resto dos vossos pastos; depois de terdes bebido água límpida, turvastes o resto com os vossos pés. (ver nota)'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 34), 19, 'Assim as minhas ovelhas tinham de se apascentar do que tinha sido pisado com os vossos pés, e tinham de beber do que os vossos pés tinham turvado.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 34), 20, 'Portanto isto vos diz o Senhor Deus: Eis que eu mesmo julgarei entre ovelha gorda e ovelha magra.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 34), 21, 'Visto que vós molestastes com os vossos costados e ombros todas as ovelhas fracas, e (como touros) com as vossas pontas as feristes, até as lançar fora,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 34), 22, 'vou acudir às minhas ovelhas, para que não fiquem expostas à pilhagem, e julgar entre ovelhas e ovelhas.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 34), 23, 'Suscitarei um único pastor que as apascente, o meu servo Davide: ele as apascentará e será o seu pastor.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 34), 24, 'Eu, o Senhor, serei o seu Deus, e o meu servo Davide será príncipe no meio delas. Eu, o Senhor, o disse.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 34), 25, 'Farei com elas uma aliança de paz e exterminarei do país os animais ferozes. Elas habitarão, com segurança, no deserto, dormirão no meio dos bosques.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 34), 26, 'Pô-las-ei ao redor da minha colina, farei cair as chuvas a seu tempo: serão chuvas de bênção.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 34), 27, 'A árvore dos campos dará o seu fruto, a terra dará os seus produtos, e as minhas ovelhas habitarão sem temor no seu país. Saberão que eu sou o Senhor, quando eu tiver quebrado as cadeias do seu jugo e as tiver arrancado das mãos daqueles que as dominam.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 34), 28, 'Não serão mais a presa das nações, nem os animais da terra as devorarão; mas habitarão com toda a segurança, sem terem nada que temer.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 34), 29, 'Farei brotar para elas uma vegetação de grande nomeada; não tornarão a ser consumidas pela fome sobre a terra, nem trarão mais sobre si o opróbrio das nações.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 34), 30, 'Então saberão que eu, o Senhor seu Deus, estarei com elas, e que elas, (as ovelhas da) casa de Israel são o meu povo, diz o Senhor Deus.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 34), 31, 'Vós, ovelhas minhas, sois o rebanho humano da minha pastagem, e eu sou o Senhor vosso Deus, oráculo do Senhor Deus.');
INSERT INTO bible_chapters (book_id, chapter_number, total_verses)
INSERT INTO bible_verses (chapter_id, verse_number, text) VALUES
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 35), 1, 'Foi-me dirigida a palavra do Senhor, nestes termos:'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 35), 2, 'Filho de homem, volta o teu rosto para o monte de Seir e profetiza contra ele. Dize-lhe:'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 35), 3, 'Assim fala o Senhor Deus; Eis que venho contra ti, ó monte de Seir, estenderei a minha mão sobre ti e tornar-te-ei desolado e deserto.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 35), 4, 'Reduzirei a ruínas as tuas cidades, ficarás devastado e saberás que eu sou o Senhor.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 35), 5, 'Porque nutriste um ódio eterno aos filhos de Israel e os entregaste à espada no tempo da sua aflição, quando a sua iniquidade tinha chegado ao extremo,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 35), 6, 'por isso (juro) pela minha vida, diz o Senhor Deus, que te entregarei ao sangue, e que o sangue te perseguirá; porque pecaste, derramando o sangue, o sangue te perseguirá.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 35), 7, 'Tornarei o monte de Seir desolado e deserto, e desviarei dele todos os (transeuntes) que vão e vêm.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 35), 8, 'Encherei os seus montes de mortos: cairão passados à espada sobre os teus outeiros e nos teus vales e nas tuas torrentes.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 35), 9, 'Reduzir-te-ei a solidões eternas: as tuas cidades não serão mais habitadas. Assim sabereis que eu sou o Senhor Deus.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 35), 10, 'Porque disseste: Duas nações e dois países serão meus eu os possuirei como minha herança quando o Senhor estava lá presente'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 35), 11, 'por essa razão, juro, diz o Senhor Deus, que te hei-de tratar conforme a ira e o ciúme que sempre mostraste no teu ódio contra eles (os Israelitas) e que me farei conhecer por meio deles, quando te julgar.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 35), 12, 'Saberás que eu, o Senhor, ouvi todos os insultos que proferiste contra os montes de Israel, dizendo: São uns montes desertos, que nos foram dados para nós os devorarmos (como uma presa).'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 35), 13, 'Postes desbocados contra mim, multiplicastes contra mim as vossas palavras; eu as ouvi.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 35), 14, 'Isto diz o Senhor Deus: Com júbilo de toda a terra, reduzir-te-ei a uma solidão.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 35), 15, 'Assim como te regozijaste acerca da herança da casa de Israel, porque foi destruída, assim eu te tratarei a ti; serás arruinado, monte de Seir, bem como toda a Idumeia. Assim se saberá que eu sou o Senhor.');
INSERT INTO bible_chapters (book_id, chapter_number, total_verses)
INSERT INTO bible_verses (chapter_id, verse_number, text) VALUES
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 36), 1, 'Tu, filho de homem, profetiza acerca dos montes de Israel. Dize-lhes: Montes de Israel, ouvi a palavra do Senhor:'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 36), 2, 'Assim fala o Senhor Deus: Porque o inimigo disse de vós: Bem feito! Estas alturas eternas (de Israel) foram-nos dadas como herança!'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 36), 3, 'por isso profetiza o seguinte: Assim fala o Senhor Deus: Porque tendes sido desolados e pisados aos pés, por todas as partes, e vos tornastes propriedade das outras nações, e andastes na boca de todos, feitos o escárnio da plebe,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 36), 4, 'por causa disto, ouvi, montes de Israel, a palavra do Senhor Deus; Isto diz o Senhor Deus às montanhas e aos outeiros, às torrentes, aos vales, às ruínas desertas e às cidades abandonadas que foram entregues à pilhagem e insultadas pelos outros povos das cercanias.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 36), 5, 'Assim fala, pois, o Senhor Deus: Sim, foi no ardor do meu zelo que falei contra as outras nações e contra toda a Idumeia, as quais se apropriaram da minha terra, com gozo do coração e profundo desprezo, para a despovoar e saquear:'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 36), 6, 'portanto profetiza sobre a terra de Israel, dize às montanhas e aos outeiros, às ribeiras e aos vales: Assim fala o Senhor Deus: Eis que falei no meu zelo e no meu furor, pelo motivo de terdes sofrido os insultos das nações.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 36), 7, 'Por isso, isto diz o Senhor Deus: Levantei a minha mão, (jurando) que as nações que estão em torno de vós, essas mesmas hão-de carregar sobre si os próprios insultos.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 36), 8, 'E vós, montes de Israel, lançareis os vossos ramos e dareis o vosso fruto ao meu povo de Israel, porque está para voltar (do cativeiro).'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 36), 9, 'Eis que venho a vós, me volto para vós: (de novo) sereis lavrados e recebereis a semente.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 36), 10, 'Multiplicarei em vós os homens, toda a casa de Israel; as cidades serão habitadas, e os lugares arruinados serão reconstruídos.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 36), 11, 'Multiplicarei em vós homens e animais; eles serão numerosos e fecundos; farei que sejais habitados como dantes, dar-vos-ei bens ainda maiores que os que tivestes no princípio, e sabereis que eu sou o Senhor.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 36), 12, 'Sobre vós farei vir homens, (que constituam) o meu povo de Israel, e eles vos possuirão como sua herança; sereis a sua herança e não os privareis mais dos seus filhos.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 36), 13, 'Assim fala o Senhor Deus: Já que dizem de vós que sois uma terra que devora homens e que mata os seus filhos.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 36), 14, 'por isso (ó Israel) tu não devorarás mais homens nem matarás mais teus filhos, diz o Senhor Deus.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 36), 15, 'Farei que se não ouçam mais em ti os insultos das nações, e não levarás mais sobre ti o opróbrio dos povos, nem perderás mais a tua gente, diz o Senhor Deus.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 36), 16, 'Foi-me dirigida a palavra do Senhor, nestes termos:'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 36), 17, 'Filho de homem, os da casa de Israel habitaram na sua terra e contaminaram-na com o seu proceder, com as suas obras; o seu proceder tornou-se diante de mim como a imundície da mulher menstruada.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 36), 18, 'Então derramei a minha indignação sobre eles, por causa do sangue que derramaram sobre a terra, e dos ídolos com que a contaminaram.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 36), 19, 'Dispersei-os entre as nações e foram disseminados por várias terras; julguei-os segundo o seu proceder, segundo as suas obras.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 36), 20, 'Tendo chegado às nações para onde foram (dispersos), desonraram o meu santo nome, pois que se dizia deles: Este é o povo do Senhor, estes são os que saíram da sua terra.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 36), 21, 'E eu perdoei-lhes por amor do meu santo nome, o qual a casa de Israel profanou entre as nações, para onde tinha ido.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 36), 22, 'Por isso dirás à casa de Israel: Assim fala o Senhor Deus: Não é por amor de vós, casa de Israel, que procedo desta forma, mas por atenção ao meu santo nome, que vós profanastes entre as nações, para onde fostes. Santificarei o meu grande nome, que foi profanado entre as nações, o qual vós desonrastes no meio delas, a fim de que as nações saibam que eu sou o Senhor, diz o Senhor dos exércitos, quando mostrar a minha santidade, a seus olhos, no meio de vós.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 36), 24, 'Tirar-vos-ei dentre as nações, congregar-vos-ei de todos os países e conduzir-vos-ei para a vossa terra.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 36), 25, 'Derramarei sobre vós uma água pura, e sereis purificados de todas as vossas imundícies; purificar-vos-ei de todos os vossos ídolos. (ver nota)'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 36), 26, 'Dar-vos-ei um coração novo e porei um novo espírito no meio de vós; tirarei da vossa carne o coração de pedra e dar-vos-ei um coração de carne.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 36), 27, 'Porei em vós o meu espírito e farei que andeis nos meus preceitos, que guardeis as minhas leis e as pratiqueis.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 36), 28, 'Habitareis na terra que dei a vossos pais; sereis o meu povo e eu serei o vosso Deus.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 36), 29, 'Purificar-vos-ei de todas as vossas imundícies; farei vir o trigo e multiplicá-lo-ei, e não trarei mais a fome sobre vós.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 36), 30, 'Multiplicarei o fruto das árvores e as produções dos campos, para que não tragais mais sobre vós o opróbrio da fome, entre as nações.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 36), 31, 'Então vos recordareis dos vossos maus caminhos e das vossas obras depravadas, e as vossas iniquidades e os vossos crimes vos desagradarão.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 36), 32, 'Não é por amor de vós que faço isto, diz o Senhor Deus; sabei-o. Confundi-vos e envergonhai-vos do vosso proceder, casa de Israel,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 36), 33, 'Isto diz o Senhor Deus: No dia em que vos purificar de todas as vossas iniquidades, farei repovoar as vossas cidades e restabelecer os lugares arruinados.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 36), 34, 'A terra inculta, até aí desolada aos olhos do viandante, será cultivada.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 36), 35, 'Dlr-se-á: Esta terra que estava devastada, tornou-se como um jardim de Eden, e as cidades que estavam arruinadas, desertas e subvertidas, são já praças fortes habitadas.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 36), 36, 'E todas as nações que tiverem ficado à roda de vós saberão que eu, o Senhor, restaurei os lugares arruinados e cultivei os incultos. Eu o Senhor, o disse e o executarei.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 36), 37, 'Assim fala o Senhor Deus: Ainda nisto me acharão favorável os da casa de Israel, far-lhes-ei esta mercê; Multiplicá-los-ei como um rebanho de homens,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 36), 38, 'como um rebanho santo, como o rebanho de Jerusalém nas suas festas; assim é que as cidades arruinadas serão cheias dum rebanho de homens. E saber-se-á que eu sou o Senhor.');
INSERT INTO bible_chapters (book_id, chapter_number, total_verses)
INSERT INTO bible_verses (chapter_id, verse_number, text) VALUES
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 37), 1, 'A mão do Senhor veio sobre mim, e o Senhor levou-me em espírito, e deixou-me no meio dum campo que estava cheio de ossos.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 37), 2, 'Fez-me dar uma volta em roda deles; eram muito numerosos estendidos sobre a superfície do campo, e todos completamente secos.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 37), 3, 'Disse-me (O Senhor): Filho de homem, porventura (julgas que) estes ossos poderão reviver? Respondi-lhe: Senhor Deus, tu o sabes.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 37), 4, 'Ele disse-me: Profetiza acerca destes ossos. Dir-lhes-ás; Ossos secos, ouvi a palavra do Senhor.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 37), 5, 'Assim fala o Senhor Deus a estes ossos: Eis que vou infundir em vós o espírito, e vivereis.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 37), 6, 'Porei sobre vós nervos, farei vir carnes sobre vós, cobrir-vos-ei de pele, dar-vos-ei espírito, e revivereis e sabereis que eu sou o Senhor.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 37), 7, 'Eu, pois, profetizei, como me tinha sido mandado. Ora, enquanto profetizava ouviu-se um ruído, depois fez-se uma agitação e os ossos aproximaram-se uns dos outros.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 37), 8, 'Olhei e vi que se haviam formado sobre eles nervos, e carnes para os revestir, e que a pele se havia estendido por cima. Mas não tinham espirito (ou vida).'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 37), 9, 'Então disse-me o Senhor: Profetiza ao espírito, profetiza, filho de homem, dize ao espírito; Assim fala o Senhor Deus: Espírito, vem dos quatro ventos, e sopra sobre estes mortos, para que revivam.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 37), 10, 'Profetizei, pois, como o Senhor me tinha ordenado, e o espírito entrou neles, que reviveram e se puseram de pé: grande, enorme exército.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 37), 11, 'Disse-me o Senhor: Filho de homem, estes ossos são toda a casa de Israel. Eles dizem: Os nossos ossos tornaram-se secos, a nossa esperança sumiu-se, estamos perdidos!'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 37), 12, 'Profetiza, pois, dize-lhes: Assim fala o Senhor Deus: Povo meu, vou abrir os vossos túmulos tirar-vos dos vossos sepulcros e introduzir-vos na terra de Israel.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 37), 13, 'Sabereis, povo meu, que sou o Senhor quando eu abrir os vossos sepulcros, e vos tirar dos vossos túmulos'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 37), 14, 'e infundir o meu espírito em vós para reviverdes, e vos fizer repousar sobre a vossa terra; sabereis que eu, o Senhor, o disse e o fiz oráculo do Senhor Deus.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 37), 15, 'Foi-me dirigida a palavra do Senhor, nestes termos:'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 37), 16, 'Filho de homem, toma um pedaço de tábua e escreve sobre ela: (A favor de) Judá e (a favor dos) filhos de Israel, seus companheiros. Toma outro pedaço de tábua e escreve nela: (Por) José, lenho de Efraim e (por) toda a casa de Israel sua associada.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 37), 17, 'Depois junta estes dois pedaços de tábua um ao outro, para os unir, de modo que fiquem a ser na tua mão um só pedaço de tábua.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 37), 18, 'Quando os filhos do teu povo te falarem, dizendo: Não nos explicarás o que queres dizer com isso?'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 37), 19, '— responder-lhes-ás: Assim fala o Senhor Deus: Vou tomar o lenho de José, que está na mão de Efraim, e as tribos de Israel, que lhe estão unidas: pô-las-ei juntas com o lenho de Judá, fá-las-ei juntar num só lenho, (ou cetro) e serão um só lenho na minha mão.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 37), 20, 'Terás na tua mão, diante de seus olhos, estes dois pedaços de tábua, sobre que escreveres.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 37), 21, 'Dir-lhes-ás: Assim fala o Senhor Deus: Vou tomar os filhos de Israel do meio das nações para onde foram, juntá-los de todas as partes e torná-los a trazer para a sua terra;'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 37), 22, 'formarei deles uma só nação, na terra, sobre os montes de Israel, e será um só o rei que os governará a todos: nunca mais formarão duas nações, não se dividirão para o futuro em dois reinos.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 37), 23, 'Não se mancharão mais com os seus ídolos, nem com as suas abominações, nem com todas as suas iniquidades; tirá-los-ei salvos de todas as iniquidades que cometeram, purificá-los-ei; serão o meu povo, e eu serei o seu Deus.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 37), 24, 'O meu servo Davide reinará sobre eles; será um só o pastor de todos eles; observarão as minhas leis, guardarão os meus preceitos e praticá-los-ão.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 37), 25, 'Habitarão sobre a terra que dei ao meu servo Jacob, na qual vossos pais habitaram; habitarão nela, eles e os seus filhos e os filhos dos seus filhos, para sempre; o meu servo Davide será para sempre o seu príncipe.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 37), 26, 'Farei com eles uma aliança de paz; a minha aliança com eles será eterna; estabelecê-los-ei (sòlidamente), multiplicá-los-ei e porei para sempre o meu santuário no meio deles.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 37), 27, 'O meu tabernáculo estará entre eles; serei o seu Deus e eles serão o meu povo.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 37), 28, 'E as nações saberão que eu sou o Senhor, o santificador de Israel, quando o meu santuário estiver para sempre no meio deles.');
INSERT INTO bible_chapters (book_id, chapter_number, total_verses)
INSERT INTO bible_verses (chapter_id, verse_number, text) VALUES
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 38), 1, 'Foi-me dirigida a palavra do Senhor nestes termos;'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 38), 2, 'Filho de homem, volta o teu rosto para Gog, na terra de Magog, príncipe soberano de Mosoc e de Tubal e profetiza acerca dele.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 38), 3, 'Dirás: Assim fala o Senhor Deus: Eis que venho contra ti, Gog, príncipe soberano de Mosoc e de Tubal;'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 38), 4, 'far-te-ei ir e vir (para onde quiser) pôr-te-ei um freio nos queixos, tirar-te-ei para fora a ti e a todo o teu exército, aos cavalos e aos cavaleiros, todos cobertos de couraças, uma grande multidão de homens, brandindo lanças, embraçando escudos e empunhando espadas.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 38), 5, 'Persas, Etíopes e Líbios estarão com eles, todos de escudos e capacetes.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 38), 6, 'Gomer e todas as suas tropas, a casa de Togorma, dos confins do aquilão, com todas as suas forças, povos numerosos estarão contigo.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 38), 7, 'Apronta-te, prepara-te com toda essa numerosa multidão que se juntou ao redor de ti, e dá-lhes as tuas ordens.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 38), 8, 'Depois de muitos dias, receberás ordens; ao fim de anos irás a uma nação que foi salva da espada e que, tirada dentre muitos povos, foi congregada nos montes de Israel, que estiveram muito tempo desertos, nação tirada dentre os povos, que vive toda sem receio.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 38), 9, 'Avançando, irás a ela como uma tempestade e como uma nuvem, para cobrir a terra, tu e todos os teus esquadrões, muitos povos contigo.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 38), 10, 'Isto diz o Senhor Deus; Naquele dia formarás em teu coração altivos projectos, forjarás planos malignos.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 38), 11, 'Dirás: Irei contra uma terra que está sem muros, atacarei homens em paz, que habitam com segurança; todos eles têm habitações sem muros, sem ferrolhos nem portas.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 38), 12, '(Tu irás) para saquear, tomar despojos, para descarregar a tua mão sobre ruínas (agora) habitadas, sobre um povo que foi congregado do meio das nações, o qual multiplica rebanhos e bens, e habita (o pais que era considerado como) o centro (das nações) da terra.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 38), 13, 'Sabá, Dedan, os negociantes de Tarsis e todos os seus leões (ou príncipes) dir-te-ão: Porventura vens fazer pilhagem? Juntaste essa tua multidão para saquear, para levar prata e ouro, para tirar rebanhos e bens, para tomar um enorme despojo?'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 38), 14, 'Por isso tu, filho de homem, profetiza, dize a Gog: Assim fala o Senhor Deus: Porventura não saberás bem o dia em que o meu povo de Israel viverá com toda a segurança?'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 38), 15, 'Virás então do teu país, lá dos confins do aquilão, tu e muitos povos contigo, montados todos a cavalo, multidão imensa, exército poderoso.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 38), 16, 'Dirigir-te-ás contra o meu povo de Israel, como uma nuvem de tempestade que cobre o país. Acontecerá nos últimos dias, que te farei vir sobre a minha terra, para que as nações me conheçam quando for santificado em ti a seus olhos, ó Gog.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 38), 17, 'Eis o que diz o Senhor Deus: Tu és aquele de quem falei nos séculos passados, por meio de meus servos, os profetas de Israel, quando profetizaram naqueles tempos, que eu te faria vir contra eles.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 38), 18, 'Naquele dia, no dia da chegada de Gog à terra de Israel, diz o Senhor Deus, a minha indignação subirá.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 38), 19, 'Digo-o no meu zelo, no fogo da minha ira: Naquele dia haverá uma grande comoção sobre a terra de Israel;'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 38), 20, 'os peixes do mar, as aves do céu, os animais do campo, todos os répteis que se movem sobre a terra, todos os homens que há sobre a face da terra tremerão diante de mim; os montes serão deitados abaixo, os rochedos tombarão, todas as muralhas cairão por terra.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 38), 21, 'Chamarei contra ele a espada sobre todos os meus montes, diz o Senhor Deus; a espada de cada um se voltará contra seu irmão.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 38), 22, 'Exercerei os meus juízos contra ele, pela peste, pelo sangue; farei cair chuvas torrenciais, saraivadas, fogo e enxofre, sobre ele, sobre o seu exército e sobre os numerosos povos que estão com ele.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 38), 23, 'Com isto manifestarei a minha grandeza e a minha santidade, far-me-ei conhecer aos olhos de muitas nações, e saberão que eu sou o Senhor.');
INSERT INTO bible_chapters (book_id, chapter_number, total_verses)
INSERT INTO bible_verses (chapter_id, verse_number, text) VALUES
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 39), 1, 'Tu, filho do homem, profetiza contra Gog, dize: Assim fala o Senhor Deus: Eis-me aqui contra ti, ó Gog, príncipe soberano de Mosoc e de Tubal;'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 39), 2, 'far-te-ei ir e vir (para onde quiser), tirar-te-ei para fora, far-te-ei vir das bandas do aquilão e te conduzirei sobre os montes de Israel.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 39), 3, 'Quebrarei o teu arco na tua mão esquerda, e farei que te caiam da mão direita as tuas flechas.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 39), 4, 'Cairás sobre os montes de Israel, com todos os teus esquadrões e os povos que estão contigo; entregar-te-ei às aves de rapina, a todo o animal volátil e aos animais dá terra, para que te devorem.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 39), 5, 'Cairás sobre a superfície do campo, porque eu o decretei, diz o Senhor Deus.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 39), 6, 'Enviarei fogo sobre Magog assim como sobre os que habitam confiadamente nas ilhas, e saberão que eu sou o Senhor.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 39), 7, 'Tornarei, assim, conhecido meu santo nome no meio do meu povo de Israel não deixarei profanar mais o meu santo nome, e as nações saberão que eu sou o Senhor, o santo de Israel.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 39), 8, 'Eis que isto se abeira, vai já suceder, diz o Senhor Deus: eis o dia de que falei.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 39), 9, 'Os habitantes das cidades de Israel sairão delas, e queimarão e reduzirão a cinzas as armas, os escudos e os broquéis, os arcos e as flechas, os bastões e os piques; tudo isto consumirão no fogo durante sete (durante muitos) anos.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 39), 10, 'Não mais trarão lenha dos campos, nem a cortarão das matas, porque sustentarão o seu fogo com estas armas; despojarão aqueles que os tinham despojado, pilharão aqueles que os tinham pilhado, diz o Senhor Deus.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 39), 11, 'Naquele dia darei a Gog em Israel um lugar célebre por sepulcro, o vale dos Transeuntes, ao oriente do mar, que tapará o caminho aos viandantes. Lá sepultarão Gog com toda a sua multidão de tropas, e este vale se chamará Vale de Hamon-Gog.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 39), 12, 'A casa de Israel os sepultará durante sete meses, para purificar a terra.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 39), 13, 'Todo o povo da terra trabalhará no seu enterramento; será para eles célebre o dia em que eu for glorificado, diz o Senhor Deus.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 39), 14, 'Constituirão homens que incessantemente percorram o país para sepultarem e buscarem aqueles que tinham ficado sobre a face da terra, a fim de a purificarem; farão esta busca depois de sete meses.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 39), 15, 'Percorrerão todo o país; quando tiverem achado ossos humanos, pôr-lhes-ão ao pé um sinal, até que os enterradores dos mortos os sepultem no Vale de Hamon-Gog.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 39), 16, 'O nome da cidade será Hamona. Desta forma purificarão a terra.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 39), 17, 'E tu, filho de homem (ouve); Assim fala o Senhor Deus: Dize a todo o animal volátil e a todos os animais do campo: Juntai-vos, vinde, concorrei de todas as partes ao meu sacrifício que vos ofereço, a um grande sacrifício sobre os montes de Israel, para que comais a carne e bebais o sangue.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 39), 18, 'Comereis as carnes dos heróis, bebereis o sangue dos príncipes da terra, dos carneiros, dos cordeiros, dos bodes, dos touros gordos de Basan.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 39), 19, 'Comereis carnes gordas até vos fartardes, bebereis sangue até ficardes embriagados neste sacrifício que vos ofereço;'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 39), 20, 'fartar-vos-eis à minha mesa da carne dos cavalos, e da carne dos cavaleiros valentes e de todos os homens de guerra, diz o Senhor Deus.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 39), 21, 'Manifestarei a minha glória entre as nações, e todas as nações verão o meu juízo, quando o executar, a minha mão, quando a descarregar sobre eles.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 39), 22, 'E os da casa de Israel saberão que eu sou o Senhor seu Deus, desde aquele dia e dali em diante.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 39), 23, 'As nações saberão que a casa de Israel foi levada cativa por causa da sua iniquidade, porque me atraiçoaram; escondi deles a minha face, entreguei-os nas mãos de seus inimigos, e todos caíram mortos ao fio da espada.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 39), 24, 'Tratei-os segundo a sua impureza e maldade, escondendo deles a minha face.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 39), 25, 'Por isso, isto diz o Senhor Deus : Agora tornarei a trazer os cativos de Jacob, compadecer-que-ei de toda a casa de Israel, mostrarei o meu zelo pela honra do meu santo nome.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 39), 26, 'Trarão sobre si a confusão de todas as prevaricações que cometeram contra mim, quando habitarem tranquilamente na sua terra, sem ter medo de ninguém.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 39), 27, 'Quando eu os tiver trazido dentre os povos e os tiver juntado das terras de seus inimigos, quando tiver sido santificado no meio deles, aos olhos de muitíssimas nações,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 39), 28, 'saberão que eu sou o Senhor seu Deus, porque, depois de os haver levado ao exílio entre as nações, os fiz voltar todos juntos para a sua terra, sem lá deixar nenhum deles.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 39), 29, 'Não lhes esconderei mais a minha face, porque derramarei o meu espírito sobre toda a casa de Israel, diz o Senhor Deus.');
INSERT INTO bible_chapters (book_id, chapter_number, total_verses)
INSERT INTO bible_verses (chapter_id, verse_number, text) VALUES
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 40), 1, 'No ano vinte e cinco do nosso cativeiro, no princípio do ano, no décimo dia do mês, no ano décimo quarto depois que a cidade foi destruída, neste mesmo dia veio a mão do Senhor sobre mim e conduziu-me lá (a Jerusalém).1'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 40), 2, 'Em visões divinas levou-me à terra de Israel e deixou-me sobre um monte muito alto, sobre o qual parecia construída uma cidade, ao sul.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 40), 3, 'Quando me introduziu lá, vi um homem, cujo aspecto era como de (lucidíssimo) bronze, o qual, tendo na mão um cordel de linho e uma cana de medir, estava à porta.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 40), 4, 'Este homem disse-me: Filho de homem, vê com os teus olhos, ouve com os teus ouvidos e põe no teu coração todas as coisas que te vou mostrar porque para elas te serem mostradas é que tu foste aqui trazido. Anuncia à casa de Israel todas as coisas que vais ver.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 40), 5, 'Um muro exterior por todas as partes cercava a casa. O homem tinha na mão uma cana de medir, de seis côvados, sendo cada côvado equivalente a um côvado (ordinário) e um palmo, e mediu a largura do muro que era duma cana, e a altura, que era também duma cana.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 40), 6, 'Depois foi ao pórtico voltado para o oriente, subiu pelos degraus e mediu o limiar da porta, que tinha uma oriental cana de largo;'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 40), 7, 'cada câmara tinha uma cana de comprido e uma cana de largo; entre as câmaras havia cinco côvados.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 40), 8, 'O limiar do pórtico, do lado do vestíbulo do pórtico, para o interior, media uma cana.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 40), 9, 'Mediu o vestíbulo do pórtico, o qual tinha oito côvados, e as suas pilastras (que tinham) dois côvados; o vestíbulo do pórtico estava para a parte de dentro (do edifício).'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 40), 10, 'As câmaras do pórtico do oriente eram três dum lado e três do outro as três câmaras tinham a mesma medida, e a mesma medida tinham as pilastras de ambas as partes.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 40), 11, 'Mediu a largura do limiar da porta, que era de dez côvados, e o comprimento do pórtico, que era de treze côvados.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 40), 12, 'Havia diante das câmaras o espaço dum côvado, de cada lado; cada câmara, tanto de uma parte como da outra, tinha seis côvados.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 40), 13, 'E mediu o pórtico, desde o tecto duma câmara até ao tecto da outra: a largura era de vinte e cinco côvados de porta a porta.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 40), 14, 'Para as pilastras, contou sessenta côvados; junto delas se achava o átrio que cercava o pórtico por todos os lados.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 40), 15, 'Desde a porta de entrada até à face do vestíbulo da porta interior, havia cinqüenta côvados.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 40), 16, 'Havia janelas gradeadas nas câmaras, entre as suas pilastras, para o interior do pórtico, ao redor; havia também nos vestíbulos janelas à roda, dando para o interior, e, nas pilastras, havia palmas.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 40), 17, 'Depois conduziu-me ao átrio exterior, e vi ali câmaras e um pavimento que circundava o átrio; ao redor do pavimento havia trinta câmaras.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 40), 18, 'O pavimento estendia-se ao longo dos pórticos, com a mesma extensão deles; era o pavimento inferior.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 40), 19, 'Mediu a largura, desde a frente do pórtico inferior até à frente do átrio interior: tinha cem côvados ao oriente e (outros tantos) ao norte.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 40), 20, 'Mediu também o pórtico setentrional do átrio exterior, tanto no comprimento como na largura,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 40), 21, 'e as suas câmaras, que eram três dum lado e três do outro, e as suas pilastras e o seu vestíbulo, que tinham a mesma medida dos do primeiro pórtico, a saber, cinqüenta côvados de comprimento, e vinte e cinco de largura.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 40), 22, 'As suas janelas, o vestíbulo e as palmas tinham a mesma medida que os do pórtico que olha para o oriente; subia-se até lá por sete degraus diante dos quais havia um vestíbulo.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 40), 23, 'Para o átrio interior havia uma porta em frente do pórtico setentrional e do oriental; dum pórtico ao outro mediu cem côvados.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 40), 24, 'Levou-me em seguida na direcção do meio-dia onde havia um pórtico que olhava para o meio-dia; mediu as suas pilastras e o seu vestíbulo, que tinham as mesmas dimensões.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 40), 25, 'Havia janelas em torno deste pórtico e do vestíbulo, como as outras janelas, ao longo de cinqüenta côvados de comprido e vinte e cinco côvados de largo.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 40), 26, 'Subia-se até aí por sete degraus, diante dos quais estava um vestíbulo; nas suas pilastras, havia palmas, uma dum lado e outra do outro.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 40), 27, 'O átrio interior tinha também um pórtico do lado do meio-dia; mediu, dum pórtico ao outro, na direcção do meio-dia, cem côvados.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 40), 28, 'Introduziu-me no átrio interior pelo pórtico do meio-dia, o qual tinha as mesmas medidas.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 40), 29, 'As suas câmaras, as suas pilastras e o seu vestíbulo tinham as mesmas medidas; havia janelas, em torno deste pórtico e do seu vestíbulo, ao longo de cinqüenta côvados de comprimento e vinte e cinco côvados de largura.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 40), 30, 'Os vestíbulos, que havia ao redor, tinham, cada um, vinte e cinco côvados de comprido, e cinco côvados de largo.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 40), 31, 'O seu vestíbulo dava para o átrio exterior; havia palmas nas pilastras e oito degraus por onde se subia.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 40), 32, 'Depois introduziu-me no átrio interior, do lado do oriente, e mediu o pórtico que tinha as medidas precedentes.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 40), 33, '(Mediu também) as suas câmaras, as suas pilastras e o seu vestíbulo que tinham as dimensões ditas acima; havia janelas, em torno do pórtico e do seu vestibulo, ao longo de cinqüenta côvados de comprido e vinte e cinco côvados de largo.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 40), 34, 'E (mediu) o seu vestíbulo, que dava para o átrio exterior; tinha palmas nas suas pilastras, dum lado e do outro, e uma escada de oito degraus.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 40), 35, 'Conduziu-me em seguida ao pórtico setentrional, que mediu, sendo as dimensões as mesmas (dos outros).'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 40), 36, '(Mediu também) as suas câmaras, as suas pilastras e o seu vestíbulo, com janelas em roda; (as medidas eram) cinqüenta côvados de comprido e vinte e cinco côvados de largo.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 40), 37, 'O seu vestíbulo olhava para o átrio exterior; nas suas pilastras havia palmas, dum lado e dó outro, e uma escada de oito degraus.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 40), 38, 'Havia uma câmara, cuja porta ficava perto das pilastras dos pórticos; era lá que lavavam os holocaustos.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 40), 39, 'No vestíbulo do pórtico havia duas mesas dum lado, e duas nelas do outro, para nelas se imolarem (as vitimas para) os holocaustos, pelo pecado e pelo delito.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 40), 40, 'No lado de fora do vestíbulo, á entrada setentrional do pórtico, havia duas mesas, e do outro lado do vestíbulo do pórtico havia também duas mesas;'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 40), 41, 'assim havia quatro mesas dum lado e quatro mesas do outro, ao todo oito mesas, sobre as quais imolavam (as vitimas).'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 40), 42, 'Além disso, havia mais quatro mesas para o holocausto, feitas de pedras de silharia, de côvado e meio de comprido, de côvado e meio de largo, e dum côvado de altura, para porem sobre elas os instrumentos que se empregavam na imolação das vítimas dos holocaustos e sacrifícios.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 40), 43, 'Tinham umas bordas dum palmo, dispostas interiormente, em toda a roda; sobre as mesas punham-se as carnes dos sacrifícios.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 40), 44, 'Fora do pórtico interior, estavam as câmaras dos cantores, no átrio interior, uma ao lado do pórtico setentrional, voltada para o sul, outra ao lado do pórtico oriental, voltada para o norte.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 40), 45, 'O homem disse-me: Esta câmara, que olha para o meio-dia, será para os sacerdotes que vigiam na guarda do templo;'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 40), 46, 'a câmara que olha para o aquilão será para os sacerdotes que cuidam de servir ao altar. São os filhos de Sadoc, dentre os filhos de Levi, aqueles que se aproximam do Senhor para o servirem.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 40), 47, 'Mediu também o átrio, que era um quadrado de cem côvados de comprimento e cem côvados de largo; o altar estava diante do templo.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 40), 48, 'Introduziu-me no vestíbulo do templo e mediu as pilastras do vestíbulo, que tinham cinco côvados dum lado e cinco côvados do outro; a medida do pórtico era de três côvados dum lado e três côvados do outro.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 40), 49, 'O comprimento do vestíbulo era de vinte côvados, a largura de onze côvados; subia-se a ele por dez degraus. Perto das pilastras, havia duas colunas, uma dum lado e outra do outro.');
INSERT INTO bible_chapters (book_id, chapter_number, total_verses)
INSERT INTO bible_verses (chapter_id, verse_number, text) VALUES
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 41), 1, 'Depois introduziu-me no templo e mediu as pilastras (da entrada), (que tinham) seis côvados de extensão dum lado, e seis côvados do outro medida do tabernáculo.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 41), 2, 'A largura da porta era de dez côvados; as paredes laterais da porta tinham cinco côvados dum lado e cinco côvados do outro. Mediu também o comprimento do templo, que era de quarenta côvados, e a sua largura, de vinte côvados.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 41), 3, 'Depois, tendo entrado no interior, mediu as pilastras da porta, que tinham dois côvados, e a porta (no seu comprimento), que tinha seis côvados, e a largura da porta, que era de sete côvados.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 41), 4, 'Depois mediu (o interior do Santuário), diante da face do templo, um comprimento de vinte côvados e uma largura também de vinte côvados, e disse-me: Este é o Santo dos Santos.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 41), 5, 'Mediu a parede do templo, que tinha seis côvados; a largura das câmaras, postas de todas as partes à roda do templo, era de quatro côvados.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 41), 6, 'Estas câmaras laterais estavam umas sobre as outras, em três planos, trinta em cada plano. Havia um muro exterior construído em volta do edifício, para suster as câmaras, que estas tocassem na parede do templo.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 41), 7, 'A largura aumentava, dum andar para o outro, à medida que se subia, em toda a volta do templo... (ver nota)'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 41), 8, 'Observei neste edifício, ao redor dele, um talude, base das câmaras laterais, com a medida duma cana inteira de seis côvados.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 41), 9, 'A espessura da parede do lado de fora (era) de cinco côvados, igualmente a da passagem junto das câmaras laterais.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 41), 10, 'Entre as câmaras havia um espaço de vinte côvados ao redor do edifício, por todos os lados.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 41), 11, 'As portas de todas estas câmaras davam para a passagem; havia uma porta para o aquilão, e outra porta para o meio dia; a largura da passagem era de cinco côvados em circuito.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 41), 12, 'O edifício separado, que estava voltado para ocidente, tinha setenta côvados de largura; a muralha do edifício tinha cinco côvados de espessura ao redor, e um comprimento de noventa côvados.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 41), 13, 'Mediu o comprimento da casa, que era de cem côvados; o edifício que estava dela separado, o espaço vazio (entre as duas construções) e as suas paredes tinham também cem côvados de comprido.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 41), 14, 'A largura da fachada do templo e do espaço livre, para oriente, era de cem côvados.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 41), 15, 'Mediu também o comprimento do edifício que se acha defronte do espaço livre, por trás da construção, com as galerias dos dois lados: era de cem côvados.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 41), 16, 'O templo, no seu interior, e o vestíbulo do átrio, os umbrais, as janelas gradeadas e os pórticos que estavam ao redor por três lados, defronte do limiar de cada porta, estavam revestidos dum lambril de madeira que cercava tudo, desde a terra até às janelas, as quais janelas estavam fechadas.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 41), 17, 'Desde a entrada até à casa interior, e por toda a parede em roda, por dentro e por fora, tudo estava coberto de figuras:'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 41), 18, 'querubins e palmeiras; entre querubim e querubim estava uma palmeira. Cada querubim tinha duas faces;'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 41), 19, 'uma face de homem junto duma palmeira dum lado, e uma face de leão junto de outra palmeira do outro lado, esculpidas em relevo em toda a volta do templo.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 41), 20, 'Estas representações dos querubins e das palmeiras estavam na parede do templo, desde o pavimento até ao cimo da porta.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 41), 21, 'Os pilares do templo eram quadrados. Diante do santuário havia qualquer coisa que parecia um altar de madeira;'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 41), 22, 'a sua altura era de três côvados, o seu comprimento de dois côvados; tinha ângulos e os suportes e os lados de madeira. O homem disse-me: Esta é a mesa que está diante do Senhor.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 41), 23, 'Tanto o templo como o santuário tinham, cada um uma porta.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 41), 24, 'Nestas duas portas duma e outra parte, havia dois batentes que se fechavam um sobre o outro, porque eram duas as portas duma e outra parte da porta (principal).'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 41), 25, 'Sobre as referidas portas do templo havia representados querubins e palmas como os que se viam sobre as paredes. Havia um anteparo de madeira sobre a fachada do vestíbulo por fora.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 41), 26, 'Havia janelas gradeadas e figuras de palmas dum e doutro lado sobre as paredes laterais do vestíbulo, sobre as câmaras laterais, e em toda a extensão dos anteparos.');
INSERT INTO bible_chapters (book_id, chapter_number, total_verses)
INSERT INTO bible_verses (chapter_id, verse_number, text) VALUES
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 42), 1, '(Depois) fez-me sair para o átrio exterior, ao norte; e introduziu-me nas câmaras, que estavam em frente do espaço livre e em frente da casa que olhava para o norte.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 42), 2, '(Este edifício) tinha na fachada cem côvados de comprimento, do lado da porta setentrional, e cinqüenta côvados de largura.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 42), 3, 'Tinha vista para o átrio interior, que era de vinte côvados, e para o pavimento do átrio exterior, onde estava uma galeria defronte da galeria de três planos.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 42), 4, 'Diante das câmaras havia um passeio de dez côvados de largo, e para ir ao interior um caminho dum côvado. As suas portas estavam ao norte.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 42), 5, 'Estas câmaras eram mais estreitas no plano superior que as inferiores e as médias, porque as galerias lhes tiraram espaço.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 42), 6, 'Havia três andares, mas não tinham colunas como as colunas do átrio; por isso as câmaras superiores eram mais estreitas que as inferiores e as do meio.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 42), 7, 'O muro exterior ao longo das câmaras, no caminho do átrio exterior, tinha, diante das câmaras, cinqüenta côvados de comprido.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 42), 8, 'Com efeito, o comprimento das câmaras do átrio exterior era de cinqüenta côvados ao passo que a extensão defronte do templo, era de cem côvados.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 42), 9, 'Por baixo destas câmaras havia uma entrada ao oriente, para os que entravam nelas do átrio exterior.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 42), 10, 'Na largura do muro do átrio, que estava defronte da porta oriental do espaço livre e do edifício, havia câmaras.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 42), 11, 'Existia também um caminho ao longo destas câmaras, como havia um ao longo das câmaras que estavam ao norte; o seu comprimento e a sua largura eram os mesmos, assim como eram as mesmas as saídas, a disposição e as portas;'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 42), 12, 'estas entradas eram como as portas das câmaras, que estavam ao meio-dia; havia uma porta no topo do caminho, ao longo do muro correspondente, para servir aos que entravam pela parte do oriente.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 42), 13, 'Disse-me: As câmaras que ficam ao setentrião e as que ficam ao meio-dia, diante do espaço livre, são câmaras santas; aqui é onde os sacerdotes, que se aproximam do Senhor, comem coisas santíssimas; aqui é que eles porão coisas sacrossantas, a oblação e a oferenda pelo pecado e pelo delito, porque este lugar é santo.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 42), 14, 'Quando os sacerdotes tiverem entrado, não sairão do lugar santo para o átrio exterior sem deixarem lá as vestimentas com que exercem o seu ministério, porque são santas. Tomarão outras vestes, para ir ter aos lugares do povo.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 42), 15, 'Quando ele acabou de tomar as medidas do interior da casa, fez-me sair, pelo pórtico oriental e mediu a casa em toda a volta.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 42), 16, 'Mediu o lado do oriente com a cana de medir: quinhentos côvados (medidos) com a cana de medir, ao redor.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 42), 17, 'Mediu o lado do setentrião; quinhentos côvados, com a cana de medir, ao redor.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 42), 18, 'Mediu o lado do meio-dia: quinhentos côvados, com a cana de medir, ao redor.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 42), 19, 'Mediu o lado do ocidente; quinhentos côvados. com a cana de medir (ao redor).'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 42), 20, 'Mediu assim a parede de cintura, pelos quatro lados, andando á roda, achando o comprimento de quinhentos côvados e a largura de quinhentos côvados; (essa parede) separava o (lugar) sagrado do profano.');
INSERT INTO bible_chapters (book_id, chapter_number, total_verses)
INSERT INTO bible_verses (chapter_id, verse_number, text) VALUES
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 43), 1, 'Depois conduziu-me ao pórtico oriental.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 43), 2, 'E eis que entrava a glória do Deus de Israel pelo lado do oriente, com um ruído semelhante ao ruído das grandes águas, e a terra estava resplandecente pela (presença da) sua glória.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 43), 3, 'A visão que tive era semelhante à que tinha tido, quando vim para destruir a cidade, semelhante à que tinha tido junto do rio Cobar. Prostrei-me sobro o meu rosto.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 43), 4, 'A glória do Senhor entrou no templo pela porta oriental.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 43), 5, 'O espírito arrebatou-me e introduziu-me no átrio interior. E eis que a casa estava cheia da glória do Senhor.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 43), 6, 'Então ouvi alguém que me falava de dentro da casa, enquanto o homem estava junto de mim.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 43), 7, 'Disse-me: Filho de homem, este é o lugar do meu trono, o lugar onde assentarei os meus pés, onde habitarei para sempre entre os filhos de Israel; os da casa de Israel não profanarão mais para o futuro o meu santo nome, nem eles, nem os seus reis, com as suas fornicações (ou idolatrias), com os cadáveres dos seus reis e com os seus lugares altos.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 43), 8, 'Eles edificaram a sua porta junto da minha porta (ou templo), os postes da entrada da sua casa ao pé dos meus postes, de sorte que havia apenas um muro entre mim e eles; assim profanaram o meu santo nome pelas abominações que cometeram; por isso os consumi na minha ira. (ver nota)'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 43), 9, 'Agora, porém, deitarão para longe de mim as suas prostituições e os cadáveres dos seus reis, e eu habitarei sempre no meio deles.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 43), 10, 'Tu, filho de homem, mostra o templo à casa de Israel, para que eles se confundam das suas iniquidades. Que meçam toda a sua fábrica.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 43), 11, 'Se se envergonharem de tudo o que fizeram, mostra-lhes a figura da casa (ou do templo), a sua disposição, as saídas e entradas do edifício, toda a sua traça, todos os preceitos acerca dela, toda a sua ordem e todas as suas leis; tudo isso porás, por escrito, diante dos seus olhos, a fim de que observem todas as indicações, todos os seus preceitos, e os cumpram.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 43), 12, 'Tal é a lei (ou norma) que se deve guardar na edificação da casa: Sobre o cume do monte, todo o espaço em roda é santíssimo. Tal é, pois, a lei da casa.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 43), 13, 'Eis as medidas do altar, em côvados (extraordinários que têm a medida) de um côvado (vulgar) e um palmo: a base era dum côvado de altura e dum côvado de largura; o seu rebordo, por todo o circuito, era de um palmo. Eis a altura do altar:'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 43), 14, 'desde a base que estava na terra até ao primeiro rebordo havia dois côvados (de altura), e um côvado de largura; e desde o rebordo mais pequeno até ao maior havia quatro côvados, e a sua largura era dum côvado.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 43), 15, 'A parte (do altar) reservada a cremação (das vitimas) tinha quatro côvados; daí para cima levantavam-se quatro hastes.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 43), 16, 'A parte reservada à cremação tinha doze côvados de comprido e doze côvados de largo, em quadrado.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 43), 17, 'E a base era de catorze côvados de comprido e de catorze côvados de largo. O rebordo em roda dele era de meio côvado, a base era dum côvado em roda; os seus degraus estavam voltados para o oriente.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 43), 18, '(O meu guia) disse-me: Filho de homem, assim fala o senhor Deus: Estas são as cerimônias que se devem observar a respeito do altar, quando for edificado, para que sobre ele se ofereça o holocausto e se derrame o sangue.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 43), 19, 'Darás aos sacerdotes levíticos, que são da linhagem de Sadoc, que se aproximam de mim, diz o Senhor Deus, para me servir, um novilho para sacrifício pelo pecado.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 43), 20, 'Tomarás do seu sangue e pô-lo-ás sobre os quatro remates do altar, sobre os quatro cantos do quadro e sobre a cornija ao redor. Assim farás a purificação e a expiação.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 43), 21, 'Depois tomarás o novilho que tiver sido oferecido pelo pecado, o qual será queimado num lugar separado da casa fora do santuário.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 43), 22, 'No segundo dia oferecerás pelo pecado um bode novo, sem defeito; purificar-se-á o altar, como se purificou com o novilho.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 43), 23, 'Depois que tiveres acabado de o purificar, oferecerás um novilho, sem defeito, e um carneiro do rebanho, também sem defeito.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 43), 24, 'Oferecê-los-ás na presença do Senhor; os sacerdotes deitarão sal sobre eles e oferecê-los-ão em holocausto ao Senhor.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 43), 25, 'Durante sete dias, oferecerás cada dia um bode pelo pecado, e da mesma sorte será oferecido um novilho da manada e um carneiro do rebanho, sem defeito.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 43), 26, 'Durante sete dias far-se-á a propiciação do altar, purificar-se-á e consagrar-se-á.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 43), 27, 'Passados os sete dias, ao oitavo dia e nos seguintes, os sacerdotes oferecerão sobre o altar os vossos holocaustos e os vossos sacrifícios pacíficos, e eu me reconciliarei convosco, diz o Senhor Deus.');
INSERT INTO bible_chapters (book_id, chapter_number, total_verses)
INSERT INTO bible_verses (chapter_id, verse_number, text) VALUES
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 44), 1, 'Fez-me voltar depois para o pórtico exterior do santuário que olhava para o oriente, o qual estava fechado.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 44), 2, 'O Senhor disse-me; Este pórtico estará fechado: não se abrirá, ninguém passará por ele, porque o Senhor Deus de Israel por aí passou: ficará fechado.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 44), 3, 'Porém o príncipe, como príncipe sentar-se-à nele para comer o pão diante do Senhor; mas entrará pelo caminho do vestíbulo do pórtico, e pelo mesmo caminho sairá.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 44), 4, 'Levou-me pelo pórtico do setentrião, diante do templo; olhei e vi que a glória do Senhor enchia a casa do Senhor; (ao ver isto) prostrei-me sobre o meu rosto.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 44), 5, 'E o Senhor disse-me: Filho de homem, considera no teu coração, olha com os teus olhos e ouve com os teus ouvidos todas as coisas que te disser acerca de todas as ordenações da casa do Senhor, de todos os seus regulamentos; aplica o teu coração a conhecer como entrar no templo e a conhecer também todas as saídas do santuário.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 44), 6, 'Dirás à casa de Israel, a estes rebeldes: Assim fala o Senhor Deus: Bastem-vos já, casa de Israel, todas as vossas maldades:'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 44), 7, 'introduzistes filhos estrangeiros, incircuncidados de coração e incircuncidados de carne, para estarem no meu santuário, profanando a minha casa, quando oferecíeis os meus pães, a gordura e o sangue, quebrando assim, o meu pacto com todas as vossas abominações.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 44), 8, 'Não observastes as leis do meu santuário estabelecestes (estes incircuncidados) para fazer o meu serviço no meu santuário, em lugar de vós (violando deste modo os preceitos divinos).'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 44), 9, 'Isto diz o Senhor Deus: Nenhum estrangeiro, incircuncidado de coração e incircuncidado de carne, entrará no meu santuário, nenhum filho de estrangeiro, que viva no meio dos filhos de Israel.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 44), 10, 'Até os levitas, que se apartaram de mim, entregando-se ao erro dos filhos de Israel, quando estes se desencaminharam, deixando-me a mim para irem atrás dos seus ídolos, suportarão o castigo da sua iniquidade.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 44), 11, 'Serão no meu santuário simples porteiros guardas das portas da casa e seus serventes; matarão os (animais destinados aos) holocaustos e sacrifícios pelo povo, e estarão na sua presença para o servir.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 44), 12, 'Visto que lhe prestaram o seu ministério na presença dos seus ídolos, e foram para a casa de Israel uma ocasião de escândalo e de iniquidade, por isso levantei a minha mão contra eles, diz o Senhor Deus, e eles levarão o peso da sua iniquidade.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 44), 13, 'Não mais se aproximarão de mim, para exercer as funções do sacerdócio na minha presença nem para tocar nas coisas santas, no lugar santíssimo, mas levarão sobre si a sua confusão e o castigo das maldades que cometeram.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 44), 14, 'Constituí-los-ei (simples) guardas da casa e seus serventes, para tudo o que nela for preciso fazer.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 44), 15, 'Porém aqueles sacerdotes levíticos, filhos de Sadoc, que guardaram as ordenações do meu santuário, quando os filhos de Israel se desencaminharam de mim, esses aproximar-se-ão de mim para me servirem de ministros, estarão na minha presença para me oferecerem a gordura e o sangue, diz o Senhor Deus.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 44), 16, 'Esses é que entrarão no meu santuário, que se aproximarão da minha mesa, para o meu serviço, observando as minhas ordenações.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 44), 17, 'Quando eles entrarem nas portas do átrio interior, estarão vestidos de roupas de linho; não terão nada sobre si que seja de lã, quando exercerem as funções do seu ministério nos pórticos do átrio interior e dentro.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 44), 18, 'Terão turbantes de linho na cabeça, e calções de linho sobre os rins; não se cingirão de modo a excitar o suor.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 44), 19, 'Quando saírem ao átrio exterior (para irem) ao povo, tirarão os hábitos com que tiverem exercido o seu ministério e depô-los-ão nas câmaras do santuário; vestirão outros hábitos, para não santificarem o povo com as suas vestes (sagradas).'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 44), 20, 'Não raparão a cabeça, nem deixarão crescer livremente o cabelo, mas terão cuidado de o cortar.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 44), 21, 'Nenhum sacerdote beberá vinho, quando tiver de entrar no átrio interior.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 44), 22, 'Não se casarão, nem com viúva nem com repudiada, mas com donzelas de linhagem da casa de Israel; poderão todavia casar com uma viúva doutro sacerdote.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 44), 23, 'Ensinarão ao meu povo a diferença que há entre o santo e o profano, entre o puro e o impuro.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 44), 24, 'Quando se levantar alguma controvérsia, prestar-se-ão a decidí-la; julgarão segundo o direito que estabeleci. Observarão as minhas leis e os meus preceitos, em todas as minhas solenidades, e santificarão os meus sábados.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 44), 25, 'Não se aproximarão dum cadáver, para que se não manchem excepto se for pai ou mãe, filho ou filha, irmão ou irmã que não tenha marido.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 44), 26, 'Depois que qualquer deles tiver sido purificado, contar-se-lhe-ão sete dias.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 44), 27, 'No dia em que entrar no santuário, no átrio, interior, para exercer o seu ministério no santuário oferecerá um sacrifício pelo seu pecado, diz o Senhor Deus.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 44), 28, '(Os sacerdotes) não terão herança, porque eu é que sou a sua herança; não lhes dareis quinhão em Israel, porque eu é que sou o seu quinhão.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 44), 29, 'Alimentar-se-ão das oblações e das vítimas que forem oferecidas, tanto pelo pecado como pelo delito, tudo o que for consagrado em Israel, será deles.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 44), 30, 'As primícias de todos os primogênitos e todas as oferendas de qualquer espécie pertencerão aos sacerdotes; dareis também ao sacerdote as primícias dos vossos alimentos, para que repouse a bênção sobre a vossa casa.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 44), 31, 'Os sacerdotes não comerão nada de ave, nem de outro animal, que por si tenham morrido, ou que tenham sido despedaçados.');
INSERT INTO bible_chapters (book_id, chapter_number, total_verses)
INSERT INTO bible_verses (chapter_id, verse_number, text) VALUES
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 45), 1, 'Quando começardes a dividir a terra por sortes (entre as famílias) separai, como oferta reservada ao Senhor, um pedaço da terra, que será sagrado. Terá vinte e cinco mil medidas (ou côvados) de comprimento, e dez mil de largura; será sagrado em toda a sua extensão.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 45), 2, 'De todo este espaço separareis, para santuário, um quadrado de quinhentos côvados de cada lado, tendo em toda a volta uma cerca de cinqüenta côvados de espaço vazio.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 45), 3, 'Sobre esta superfície, medireis um comprimento de vinte e cinco mil (côvados), e uma largura de dez mil onde ficará o santuário, o Santo dos Santos.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 45), 4, 'Esta porção de terra consagrada (a Deus) será para os sacerdotes, ministros do santuário, que se aproximam para servir o Senhor; tal porção será destinada para suas casas e como lugar consagrado para o santuário.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 45), 5, 'Haverá também outros vinte e cinco mil côvados de comprimento e dez mil de largura para os levitas que servem no templo; aí terão cidades (ou povoações) para morar (destinadas aos que estiverem de serviço).'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 45), 6, 'Dai-eis cinco mil côvados de largura e vinte e cinco mil de comprimento, paralelamente ao que está separado para o santuário, para domínio da cidade; isto pertencerá à casa de Israel.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 45), 7, 'Também ao príncipe (dareis a sua porção) duma e outra parte, junto ao que foi separado para o santuário e junto à possessão da cidade, em frente do que foi apartado para o santuário e em frente da possessão da cidade, do lado do ocidente, para ocidente, e, do lado do oriente, para oriente. O comprimento será igual ao de cada parte, desde a fronteira ocidental até á oriental do país.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 45), 8, 'Será a sua porção em Israel. Os príncipes não oprimirão mais o meu povo, mas deixarão a terra à casa de Israel, segundo as sua tribos.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 45), 9, 'Isto diz o Senhor Deus; Baste-vos, ó príncipes de Israel, (o que tendes feito)! Cessai de cometer a violência e as rapinas, praticai o direito e a justiça, não sobrecarregueis com mais exacções o meu povo, diz o Senhor Deus.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 45), 10, 'Seja justa a vossa balança, justo o efa, justo o bato.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 45), 11, 'O efa e o bato serão duma mesma medida, de sorte que o bato (para os líquidos) tenha a décima parte do homer, e o efa (para os sólidos) tenha a mesma décima parte do homer; a sua capacidade será igual, comparada com a medida do homer.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 45), 12, 'O siclo tem vinte óbolos. E vinte siclos, com vinte e cinco siclos mais quinze siclos, fazem uma mina.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 45), 13, 'Eis as primícias que vós oferecereis. A sexta parte dum efa, de cada homer de trigo, e a sexta parte dum efa, de cada homer de cevada.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 45), 14, 'Quanto à medida do azeite, dareis a décima parte dum bato por cada cor, que é igual ao homer, pois tem dez batos, porque dez batos enchem um homer.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 45), 15, '(Oferecereis) um carneiro de cada rebanho de duzentas cabeças das pastagens de Israel, para a oblação, para os holocaustos e para os sacrifícios pacíficos, a fim de fazer expiação por eles, diz o Senhor Deus.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 45), 16, 'Todo o povo da terra será obrigado a pagar estas primícias ao que for príncipe em Israel.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 45), 17, 'Mas estarão a cargo do príncipe os holocaustos, as oferendas e as libações nos dias solenes, nos primeiros dias de cada mês, nos sábados, em todas as solenidades da casa de Israel; ele oferecerá (o necessário para) o sacrifício pelo pecado, para o holocausto e para os sacrifícios pacíficos, a fim de se fazer a explação pela casa de Israel.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 45), 18, 'Isto diz o Senhor Deus; No primeiro mês, no primeiro dia do mês, tomarás um novilho sem defeito e expiação, purificarás o santuário.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 45), 19, 'O sacerdote tomará do sangue da vítima oferecida pelo pecado, e espargirá com ele os postes do templo, os quatro cantos do quadro do altar e os postes da porta do átrio Interior.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 45), 20, 'O mesmo farás no sétimo dia do mês, por cada um que pecou por ignorância ou por irreflexão, e (assim) purificarás o templo.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 45), 21, 'No primeiro mês, a quatorze do mês, celebrareis a solenidade da páscoa, comendo pães ázimos durante sete dias.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 45), 22, 'O príncipe oferecerá nesse dia por si e por todo o povo da terra um novilho pelo pecado.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 45), 23, 'Depois, oferecerá em holocausto ao Senhor durante a solenidade dos sete dias, sete novilhos e sete carneiros sem defeito, cada dia, durante os sete dias; oferecerá também cada dia um bode pelo pecado.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 45), 24, 'Como oblação oferecerá um efa (de farinha) por cada novilho, e um efa por cada carneiro; juntará um hin de azeite a cada efa.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 45), 25, 'No sétimo mês, aos quinze do mês, em que se celebra a solenidade (dos Tabernáculos) fará durante sete dias contínuos as mesmas coisas que se disseram acima, tanto pela expiação do pecado como pelo holocausto, e a oblação (da farinha) e do azeite.');
INSERT INTO bible_chapters (book_id, chapter_number, total_verses)
INSERT INTO bible_verses (chapter_id, verse_number, text) VALUES
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 46), 1, 'Assim fala o Senhor Deus: O pórtico do átrio interior, que olha para o oriente, estará fechado durante os seis dias de trabalho, mas abrir-se-á no dia de sábado, assim como no primeiro dia de cada mês.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 46), 2, 'O príncipe, vindo de fora para o vestíbulo do pórtico, parará no limiar da porta; os sacerdotes oferecerão então o holocausto e os sacrifícios pacíficos; ele fará adoração sobre o limiar do pórtico e depois sairá; porém o pórtico não se fechará até à tarde.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 46), 3, 'O povo do país fará sua adoração à entrada deste pórtico, nos sábados e nos primeiros dias de cada mês, diante do Senhor.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 46), 4, 'O príncipe oferecerá ao Senhor este holocausto: No dia de sábado, seis cordeiros sem defeito, um carneiro também sem defeito,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 46), 5, 'e a oblação dum efa (de farinha) com o carneiro; com os cordeiros, fará a oblação que quiser, juntando um hin de azeite por cada efa.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 46), 6, 'No primeiro dia de cada mês (oferecerá) um novilho sem defeito, e seis cordeiros e seis carneiros igualmente sem defeito.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 46), 7, 'Fará a oblação dum efa (de farinha) com o novilho, e (também) dum efa com cada carneiro; juntando por cada cordeiro a oblação que quiser, juntando um hin de azeite por cada efa.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 46), 8, 'Quando o príncipe houver de entrar, entre pelo vestíbulo do pórtico e saia pelo mesmo caminho.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 46), 9, 'Quando o povo da terra entrar, para se pôr na presença do Senhor nos dias solenes, aquele que entrar pelo pórtico do aquilão para adorar, saia pelo pórtico do meio-dia; aquele que entrar pelo pórtico do meio-dia, saia pelo pórtico do aquilão. Ninguém voltará pela porta por que entrou, mas sairá pela que lhe é oposta.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 46), 10, 'O príncipe estará também no meio deles, entrará como os que entram e sairá como os que saem.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 46), 11, 'Nos dias de festa e nas solenidades, far-se-á a oblação de um efa (de farinha) com cada novilho, de um efa com cada carneiro; com os cordeiros, porém, oferecerá cada um o que quiser, juntando um hin de azeite a cada efa.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 46), 12, 'Quando o príncipe oferecer ao Senhor um holocausto voluntário, ou sacrifícios pacíficos voluntários, abrir-se-lhe-á o pórtico que olha para o oriente, e ele oferecerá o seu holocausto e os seus sacrifícios pacíficos, como o faz no dia de sábado; em seguida sairá; fechar-se-á o pórtico, depois que tiver saído.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 46), 13, 'Oferecerá todos os dias em holocausto ao Senhor um cordeiro dum ano, sem defeito; oferecê-lo-á sempre de manhã.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 46), 14, 'Todas as manhãs dará como oblação com este cordeiro a sexta parte dum efa (de farinha) e a terça parte dum hin de azeite, para ser misturado com a farinha; esta é a oblação a fazer ao Senhor lei perpétua, para sempre.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 46), 15, 'Oferecer-se-á o cordeiro, a oblação (da farinha) e o azeite, todas as manhãs como holocausto perpétuo.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 46), 16, 'Isto diz o Senhor Deus: Se o príncipe fizer qualquer doação a algum de seus filhos, passará para seus filhos, os quais a possuirão como bem de herança.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 46), 17, 'Porém, se ele oferecer um dom da sua própria fazenda a um dos seus servos, pertencer-lhe-á até o ano do jubileu, e então voltará para o príncipe. Apenas a seus filhos pertencerá o que lhe foi dado, como herança.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 46), 18, 'O príncipe não tomará nada por violência da herança do povo, despojando quem quer que seja dos seus bens, mas dará da sua fazenda própria o patrimônio a seus filhos, a fim de que ninguém do meu povo seja esbulhado da sua propriedade.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 46), 19, 'Depois introduziu-me por uma entrada, que estava ao lado do pórtico, nas câmaras do santuário, destinadas aos sacerdotes, as quais olhavam para o norte; ali havia um lugar voltado para o ocidente.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 46), 20, 'Então disse-me ele: Este é o lugar em que os sacerdotes cozerão as vítimas pelo pecado e pelo delito, onde cozerão as oblações, a fim de que as não levem ao átrio exterior, e (aconteça que) fique o povo santificado. (ver nota)'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 46), 21, 'Depois fez-me sair para o átrio exterior e levou-me à roda pelos quatro cantos do átrio; em cada um dos quatro cantos deste átrio havia um recinto.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 46), 22, 'Estes recintos pequenos, assim dispostos pelos quatro cantos do átrio, tinham quarenta côvados de comprido e trinta de largo; todos os quatro tinham a mesma medida.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 46), 23, 'Uma parede ao redor cercava estes quatro pequenos recintos; viam-se também cozinhas edificadas ao fundo da parede, em toda a volta.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 46), 24, 'E disse-me: Estas são as cozinhas nas quais os ministros da casa do Senhor cozerão as vitimas oferecidas pelo povo.');
INSERT INTO bible_chapters (book_id, chapter_number, total_verses)
INSERT INTO bible_verses (chapter_id, verse_number, text) VALUES
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 47), 1, '(Depois) fez-me voltar para a porta da casa (do Senhor). E eis que brotavam águas debaixo do limiar da porta, do lado do oriente, porque a face da casa olhava para o oriente; as águas desciam por baixo do lado direito do templo, ao meio-dia do altar.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 47), 2, 'Fez-me sair pelo pórtico do setentrião e dar a volta por fora até ao pórtico exterior, que olhava para o oriente; vi que as águas jorravam do lado direito.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 47), 3, 'Saindo para a banda do oriente, o homem, que tinha um cordel na mão, mediu mil côvados e fez-me atravessar a água, que me dava pelos tornozelos.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 47), 4, 'Mediu outros mil côvados e (ali) fez-me atravessar a água que me dava pelos joelhos.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 47), 5, 'Mediu outros mil côvados e fez-me atravessar a água, que me dava pelos rins. Mediu outros mil côvados, e era já uma torrente que não pude atravessar, porque se tinham empolado as águas, tornando-se uma profunda torrente, que não se podia passar a vau.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 47), 6, 'Então disse-me: Viste, filho de homem? Depois levou-me e reconduziu-me a borda da torrente.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 47), 7, 'Tendo eu, pois, tornado, vi sobre a borda da torrente muitíssimas árvores, de um e outro lado.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 47), 8, 'Disse-me; Estas águas vão para o distrito oriental e descem para a planície do deserto; entrarão no mar (Morto) e aí se difundirão, de maneira que as águas (do mar) ficarão saudáveis.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 47), 9, 'Todo o animal vivo, que se move (nas águas), viverá por toda a parte onde chegar a torrente; haverá peixes em abundância, porque, onde chegarem estas águas, as outras se tornarão sãs e haverá vida em toda a parte onde chegar esta torrente.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 47), 10, 'Os pescadores estarão sobre as suas margens desde Engadi até Engalim se estenderão redes; serão as espécies de seus peixes como as do Grande Mar, e com muita fartura.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 47), 11, 'Nas suas lagunas, porém, e nos seus charcos, não serão salutíferas as águas, porque destinadas à extracção de sal.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 47), 12, 'Ao longo da torrente nascerá nas suas ribanceiras, dum e doutro lado, toda a espécie de árvores frutíferas; não lhes cairá a folha, nem faltará o fruto. Darão frutos novos todos os meses, porque as suas águas manam do santuário; os seus frutos servirão de sustento, e as suas folhas de remédio.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 47), 13, 'Isto diz o Senhor Deus; Eis os limites, dentro dos quais possuireis a terra que se há-de repartir pelas doze tribos de Israel, dando a José um quinhão dobrado.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 47), 14, 'Possuireis todos igualmente, cada um tanto como seu irmão, esta terra prometida por mim com juramento a vossos pais; será esta terra a vossa herança.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 47), 15, 'Eis os limites da terra: Pelo lado setentrional, desde o Grande Mar, pelo caminho de Hetalon, vindo a Sedad:'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 47), 16, 'Hamat, Berota, Sabarim, que está entre os confins de Damasco e os confins de Hamat, Haser Hattikon, que está nos confins de Hauran.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 47), 17, 'Os seus limites irão, pois, desde o mar até Haser-Enon, tendo ao norte o termo de Damasco e a fronteira de Hamat. Isto pelo lado setentrional.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 47), 18, 'O seu limite oriental tomar-se-á entre Hauran e Damasco, entre Galaad e a terra de Israel, limitando-a o Jordão até ao mar oriental. Medireis a partir da fronteira (norte) até ao mar oriental. Tal é o lado do oriente.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 47), 19, 'O limite meridional irá desde Tamar até às águas de Meribot, de Cades, e até à torrente (do Egipto) que vai para o Grande Mar (ou Mediterrâneo). Este é o limite do meio-dia.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 47), 20, 'O limite (ocidental), do lado do mar, será o Grande Mar, desde o seu extremo até Hamat. Este será o lado do ocidente.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 47), 21, 'Dividireis esta terra entre vós, segundo as tribos de Israel;'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 47), 22, 'sorteá-la-eis para herança vossa e daqueles estrangeiros que vierem juntar-se convosco, que tiverem filhos no meio de vós; considerá-los-eis como naturais entre os filhos de Israel; tomarão parte convosco na herança, no meio das tribos de Israel.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 47), 23, 'Em qualquer tribo em que se achar um estrangeiro, vós lhe dareis ali o seu quinhão (de terra), diz o Senhor Deus.');
INSERT INTO bible_chapters (book_id, chapter_number, total_verses)
INSERT INTO bible_verses (chapter_id, verse_number, text) VALUES
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 48), 1, 'Eis os nomes das tribos. Desde a fronteira do norte, ao longo do caminho de Hetalon, quando se vai a Hamat, até Haser-Enon, deixando o limite da banda de Damasco, ao norte, ao longo do caminho de Hamat, (os limites) desde o lado oriental ao ocidental determinam a porção (da tribo) de Dan.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 48), 2, 'Junto dos confins de Dan, desde o oriente até ao ocidente, será a porção de Aser.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 48), 3, 'Junto dos confins de Aser, da região oriental até à ocidental, a porção de Neftali.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 48), 4, 'Junto dos confins de Neftali, desde a região oriental até à ocidental, a porção de Manassés.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 48), 5, 'Junto dos confins de Manassés. desde a região oriental até à ocidental, a porção de Efraim.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 48), 6, 'Junto dos confins de Efraim, desde a região oriental até à ocidental, a porção de Ruben.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 48), 7, 'Junto dos confins de Ruben, desde a região oriental até à ocidental, a porção de Judá.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 48), 8, 'Junto dos confins de Judá, desde a região oriental à ocidental, serão as primícias (ou porções) que separareis, as quais terão vinte e cinco mil medidas (ou côvados) de largura, e um comprimento igual a cada um dos outros quinhões, desde a região oriental até à ocidental. O santuário ficará no meio.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 48), 9, 'Quanto às primícias (ou porções) que separareis para o Senhor, terão vinte e cinco mil côvados de comprido e dez mil de largo.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 48), 10, 'Estas primícias santas pertencerão aos sacerdotes; terão vinte e cinco mil côvados de comprimento para o aquilão, dez mil de largura, para o mar, dez mil também de largura, para o oriente, e vinte e cinco mil de comprimento, para o meio-dia. O santuário do Senhor ficará no meio (desta porção).'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 48), 11, 'Toda esta porção será destinada ao sacerdotes consagrados, filhos de Sadoc os quais observaram as minhas cerimônias e não se desencaminharam como os levitas, quando os filhos de Israel andavam desencaminhados.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 48), 12, 'O seu quinhão será no meio das porções reservadas, parte santíssima, junto aos limites dos levitas.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 48), 13, 'Os levitas terão junto aos limites dos sacerdotes, vinte e cinco mil côvados de comprimento, e dez mil de largura. Todo o comprimento (da sua porção) será de vinte e cinco mil côvados e a largura de dez mil.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 48), 14, 'Não poderão nem trocar nada disto, nem transferir a outros as primícias da terra, porque são consagradas ao Senhor.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 48), 15, 'Os cinco mil côvados que restam da largura dos vinte e cinco mil, serão considerados como profanos, ficando destinados à cidade, para habitações e para arrabaldes; a cidade ficará no meio (deste espaço).'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 48), 16, 'Eis as suas medidas: do lado setentrional terá quatro mil e quinhentos côvados; do lado meridional quatro mil e quinhentos; do lado oriental quatro mil e quinhentos; do lado ocidental quatro mil e quinhentos.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 48), 17, 'Os arrabaldes da cidade terão do lado do aquilão duzentos e cinquenta côvados, do lado do meio-dia duzentos e cinquenta, do lado do oriente duzentos e cinquenta, e do lado do mar duzentos e cinquenta.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 48), 18, 'Quanto ao que, ficar do comprimento, junto às primícias do santuário, (isto é) dez mil côvados para o oriente e dez mil para o ocidente, paralelamente à parte consagrada, os produtos de tal terreno serão destinados ao sustento daqueles que servem a cidade.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 48), 19, 'Os que trabalharem em serviço da cidade, serão de todas as tribos de Israel.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 48), 20, 'Toda a parte reservada terá vinte e cinco mil côvados em quadrado; tomareis a quarta parte da porção consagrada, para possessão da cidade.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 48), 21, 'O que restar, ao redor da porção consagrada e do quinhão da cidade, defronte dos vinte e cinco mil côvados até à fronteira oriental, e a ocidente, ao longo dos vinte e cinco mil côvados, até à fronteira ocidental, será quinhão do príncipe. Isto será do príncipe; assim a porção consagrada e o lugar santo do templo ficarão no meio (deste espaço).'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 48), 22, 'Exceptuando a possessão dos levitas e a possessão da cidade, que estão no meio da porção do príncipe, pertencerá ao príncipe o que estiver entre os confins de Judá e os confins de Benjamim.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 48), 23, 'Quanto às outras tribos: A porção de Benjamim será desde a região oriental até à região ocidental.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 48), 24, 'Junto dos confins de Benjamim, desde a região oriental até à região ocidental, a porção de Simeão.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 48), 25, 'Junto dos confins de Simeão, desde a região oriental até à região ocidental, a porção de Issacar.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 48), 26, 'Junto dos confins de Issacar, desde a região oriental até à região ocidental, a porção de Zabulon.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 48), 27, 'Junto dos confins de Zabulon, desde a região oriental até à região ocidental, a porção de Gad.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 48), 28, 'Para a banda dos confins de Gad, ao meio-dia, a fronteira irá desde Tamar até às águas de Meribot, junto a Cades, e à torrente que vai para o Grande Mar.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 48), 29, 'Esta é a terra que distribuireis por sorte entre as tribos de Israel e tais serão as suas partilhas, diz o Senhor Deus.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 48), 30, 'Eis as saídas da cidade: Medirás pelo lado do setentrião quatro mil e quinhentos côvados.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 48), 31, '(As portas da cidade tomarão os nomes das tribos de Israel). Haverá três portas pelo (citado) lado do setentrião: uma porta de Ruben, uma porta de Judá e uma porta de Levi.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 48), 32, 'Medirás da mesma sorte, para o lado do oriente, quatro mil e quinhentos côvados, e desta banda haverá (também) três portas: uma porta de José, uma porta de Benjamim e uma porta de Dan.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 48), 33, 'Medirás quatro mil e quinhentos côvados para o lado do meio-dia e (da mesma sorte) haverá aqui três portas: uma porta de Simeão, uma porta de Issacar e uma porta de Zabulon.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 48), 34, 'Medirás quatro mil e quinhentos côvados para o lado do ocidente, e haverá aqui (também) três portas: uma porta de Gad, uma porta de Aser e uma porta de Neftali.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 48), 35, 'O seu circuito será de dezoito mil côvados. Desde esse dia, o nome da cidade será: Iavé-Scham (O Senhor está ali).');
